TURATH_CHUNK(10,[{"num":2000,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ صَلَّى صَلَاةَ الصُّبْحِ فَقَرَأَ الرُّومَ فَالْتَبَسَ عَلَيْهِ فَلَمَّا صَلَّى قَالَ: مَا بَالُ أَقْوَامٍ يُصَلُّونَ مَعَنَا لَا يُحْسِنُونَ الطُّهُورَ فَإِنَّمَا يَلْبِسُ عَلَيْنَا الْقُرْآنَ أُولَئِكَ."],"takhrij":"حسن: رواه النسائي (947) عن محمد بن بشار، قال: حدثنا عبدالرحمن، قال: أنبأنا سفيان، عن عبد الملك بن عمير، عن شبيب بن أبي روح، عن رجل من أصحاب النّبي صلى الله عليه وسلم، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في القراءة في صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (947), Ahmad (23072)","chapter_en":"What has been narrated about recitation in the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["A man from the Companions reported that the Prophet ﷺ prayed the dawn prayer and recited Surat al-Rum, but it became confused for him. When he finished, he said: “What is wrong with people who pray with us yet do not perfect purification? It is they who cause the Qur’an to be confused for us.” And he added: “Whoever attends the prayer with us should perfect purification.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (947)، أحمد (23072)."},{"num":2001,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْجُمُعَةِ فِي صَلَاةِ الْفَجْرِ: ﴿الم (1) تَنْزِيلُ﴾ [سورة السجدة]، وَ ﴿هَلْ أَتَى عَلَى الإِنْسَانِ﴾ [سورة الإنسان]."],"takhrij":"متفق عليه: أخرجه البخاري في الجمعة (891)، ومسلم في الجمعة (880) كلاهما من طريق سفيان، عن سعد بن إبراهيم، عن عبدالرحمن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب القراءة في الفجر يوم الجمعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (891), Muslim (880)","chapter_en":"Recitation in the dawn prayer on Friday","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah said: In the dawn prayer on Friday, the Messenger of Allah ﷺ used to recite “Alif-Lam-Mim. The Revelation…” (Surat al-Sajdah) and “Has there come upon the human being…” (Surat al-Insan)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (891)، مسلم (880)."},{"num":2002,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ يَقْرَأُ فِي صَلَاةِ الْفَجْرِ يَوْمَ الْجُمُعَةِ: ﴿الم (1) تَنْزِيلُ﴾ [سورة السجدة] وَ ﴿هَلْ أَتَى عَلَى الْإِنْسَانِ حِينٌ مِنَ الدَّهْرِ﴾ [سورة الإنسان] وَأَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي صَلَاةِ الْجُمُعَةِ سُورَةَ الْجُمُعَةِ، وَالْمُنَافِقِينَ."],"takhrij":"صحيح: رواه مسلم في الجمعة (879) من طريق سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب القراءة في الفجر يوم الجمعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (879)","chapter_en":"Recitation in the dawn prayer on Friday","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":20,"content":{"translation":{"en":["Ibn ‘Abbas said: The Prophet ﷺ used to recite in the dawn prayer on Friday “Alif-Lam-Mim. The Revelation…” (Surat al-Sajdah) and “Has there come upon the human being a period of time…” (Surat al-Insan). And the Prophet ﷺ used to recite in the Friday prayer Surat al-Jumu‘ah and Surat al-Munafiqun."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (879)."},{"num":2003,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ يَقْرَأُ فِي صَلَاةِ الفَجْرِ يَوْمَ الْجُمُعَةِ: ﴿الم (1) تَنْزِيلُ﴾، وَ ﴿هَلْ أَتَى عَلَى الْإِنْسَانِ﴾."],"takhrij":"حسن: رواه ابن ماجه (824) قال: حدثنا إسحاق بن منصور قال: أنبأنا إسحاق بن سليمان، قال: أنبأنا عمرو بن أبي قيس، عن أبي فروة، عن أبي الأحوص، عن عبدالله بن مسعود فذكر الحديث.","grade":"حسن","chapter_ar":"باب القراءة في الفجر يوم الجمعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (824)","chapter_en":"Recitation in the dawn prayer on Friday","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":20,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: The Messenger of Allah ﷺ used to recite in the dawn prayer on Friday “Alif-Lam-Mim. The Revelation…” and “Has there come upon the human being…”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (824)."},{"num":2004,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ صَلَاةِ الظُّهْرِ بِفَاتِحَةِ الْكِتَابِ وَسُورَتَيْنِ يُطَوِّلُ فِي الْأُولَى وَيُقَصِّرُ فِي الثَّانِيَةِ وَيُسْمِعُ الْآيَةَ أَحْيَانًا، وَكَانَ يَقْرَأُ فِي الْعَصْرِ بِفَاتِحَةِ الْكِتَابِ وَسُورَتَيْنِ وَكَانَ يُطَوِّلُ فِي الْأُولَى وَكَانَ يُطَوِّلُ فِي الرَّكْعَةِ الْأُولَى مِنْ صَلَاةِ الصُّبْحِ وَيُقَصِّرُ فِي الثَّانِيَةِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان، من طريق شيبان (759)، ومسلم في الصلاة من طريق حجَّاج الصواف (451) كلاهما عن يحيى بن أبي كثير، عن عبدالله بن أبي قتادة، عن أبيه فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (759), Muslim (451)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Abu Qatadah said: The Prophet ﷺ used to recite in the first two units of the noon prayer the Opening of the Book and two chapters, making the first longer and the second shorter, and he would sometimes make a verse audible. He would recite in the afternoon prayer the Opening of the Book and two chapters. And he would make the first unit of the dawn prayer longer and the second shorter."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (759)، مسلم (451)."},{"num":2005,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: شَكَا أَهْلُ الْكُوفَةِ سَعْدًا إِلَى عُمَرَ رَضِيَ اللَّهُ عَنْهُ، فَعَزَلَهُ وَاسْتَعْمَلَ عَلَيْهِمْ عَمَّارًا فَشَكَوْا حَتَّى ذَكَرُوا أَنَّهُ لَا يُحْسِنُ يُصَلِّي، فَأَرْسَلَ إِلَيْهِ فَقَالَ: يَا أَبَا إِسْحَاقَ (كنية سعد) إِنَّ هَؤُلَاءِ يَزْعُمُونَ أَنَّكَ لَا تُحْسِنُ تُصَلِّي، قَالَ أَبُو إِسْحَاقَ: أَمَّا أَنَا وَاللَّهِ فَإِنِّي كُنْتُ أُصَلِّي بِهِمْ صَلَاةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا أَخْرِمُ عَنْهَا أُصَلِّي صَلَاةَ الْعِشَاءِ فَأَرْكُدُ فِي الْأُولَيَيْنِ وَأُخِفُّ فِي الْأُخْرَيَيْنِ، قَالَ: ذَاكَ الظَّنُّ بِكَ يَا أَبَا إِسْحَاقَ، فَأَرْسَلَ مَعَهُ رَجُلًا أَوْ رِجَالًا إِلَى الْكُوفَةِ فَسَأَلَ عَنْهُ أَهْلَ الْكُوفَةِ وَلَمْ يَدَعْ مَسْجِدًا إِلَّا سَأَلَ عَنْهُ وَيُثْنُونَ مَعْرُوفًا، حَتَّى دَخَلَ مَسْجِدًا لِبَنِي عَبْسٍ فَقَامَ رَجُلٌ مِنْهُمْ يُقَالُ لَهُ أُسَامَةُ بْنُ قَتَادَةَ يُكْنَى أَبَا سَعْدَةَ قَالَ: أَمَّا إِذْ نَشَدْتَنَا فَإِنَّ سَعْدًا كَانَ لَا يَسِيرُ بِالسَّرِيَّةِ وَلَا يَقْسِمُ بِالسَّوِيَّةِ وَلَا يَعْدِلُ فِي الْقَضِيَّةِ.","قَالَ سَعْدٌ: أَمَا وَاللَّهِ لَأَدْعُوَنَّ بِثَلَاثٍ، اللَّهُمَّ إِنْ كَانَ عَبْدُكَ هَذَا كَاذِبًا قَامَ رِيَاءً وَسُمْعَةً فَأَطِلْ عُمْرَهُ وَأَطِلْ فَقْرَهُ وَعَرِّضْهُ بِالْفِتَنِ، وَكَانَ بَعْدُ إِذَا سُئِلَ يَقُولُ شَيْخٌ كَبِيرٌ مَفْتُونٌ أَصَابَتْنِي دَعْوَةُ سَعْدٍ.","قَالَ عَبْدُ الْمَلِكِ: فَأَنَا رَأَيْتُهُ بَعْدُ قَدْ سَقَطَ حَاجِبَاهُ عَلَى عَيْنَيْهِ مِنَ الْكِبَرِ، وَإِنَّهُ لَيَتَعَرَّضُ لِلْجَوَارِي فِي الطُّرُقِ يَغْمِزُهُنَّ."],"takhrij":"متفق عليه: رواه البخاري في الآذان (755) ومسلم في الصلاة (453) كلاهما من طريق عبد الملك بن عمير، عن جابر بن سمرة واللفظ للبخاري، وأما مسلم فذكره مختصراً بدون قصة دعوة سعد على أسامة بن قتادة.","grade":"متفق عليه","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (755), Muslim (453)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn Samurah said: The people of Kufah complained about Sa‘d to ‘Umar, so he removed him and appointed ‘Ammar over them. They continued complaining until they even claimed that he did not pray well. So ‘Umar sent for him and said: “O Abu Ishaq, they claim that you do not pray well.” Abu Ishaq (Sa‘d) said: “By Allah, I used to lead them in the prayer of the Messenger of Allah ﷺ without falling short: in the night prayer I would make the first two units long, and I would lighten the last two.” He said: “That is what we expect of you, O Abu Ishaq.” Then he sent one or two men with him to Kufah to ask about him. They asked the people of Kufah, and there was no mosque they left without asking, and they praised him, until they entered a mosque of Banu ‘Abs. A man among them named Usamah ibn Qatadah, nicknamed Abu Sa‘dah, stood and said: “Since you are asking us, then (I say) Sa‘d would not go out with an expedition, he would not distribute equally, and he would not judge fairly.” Sa‘d said: “By Allah, I will supplicate with three (prayers): O Allah, if this servant of Yours is lying—standing only for showing off and reputation—then prolong his life, prolong his poverty, and expose him to trials.” Later, whenever he was asked, the man would say: “An old man, afflicted; Sa‘d’s supplication struck me.” ‘Abd al-Malik said: I saw him later with his eyebrows drooping over his eyes from old age, and he would harass young women on the roads, pinching them."]},"buhuth":{"en":["“I make the first two long” means he would stand longer—i.e., lengthen the recitation in them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (755)، مسلم (453)."},{"num":2006,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَعْمَرٍ قَالَ: قُلْنَا لِخَبَّابٍ: أَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ ؟ قَالَ: نَعَمْ، قُلْنَا: بِمَ كُنْتُمْ تَعْرِفُونَ ذَاكَ ؟ قَالَ: بِاضْطِرَابِ لِحْيَتِهِ."],"takhrij":"صحيح: رواه البخاري في الأذان (746) من طريق الأعمش قال: سمعت عمارة بن عمير، يُحدث عن أبي معمر قال: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (746)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Abu Ma‘mar said: We said to Khabbab: “Did the Messenger of Allah ﷺ recite in the noon and afternoon prayers?” He said: “Yes.” We said: “How did you know that?” He said: “By the movement of his beard.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (746)."},{"num":2007,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي صَلَاةِ الظُّهْرِ فِي الرَّكْعَتَيْنِ الأُولَيَيْنِ فِي كُلِّ رَكْعَةٍ قَدْرَ ثَلَاثِينَ آيَةً، وَفِي الأُخْرَيَيْنِ قَدْرَ خَمْسَ عَشْرَةَ آيَةً، أَوَ قَالَ: نِصْفَ ذَلِكَ، وَفِي الْعَصْرِ فِي الرَّكْعَتَيْنِ الأُولَيَيْنِ فِي كُلِّ رَكْعَةٍ قَدْرَ قِرَاءَةِ خَمْسَ عَشْرَةَ آيَةً، وَفِي الأُخْرَيَيْنِ قَدْرَ نِصْفِ ذَلِك.","وَفِي رِوَايَةِ: فَحَزَرْنَا قِيَامَهُ فِي الرَّكْعَتَيْنِ الأُولَيَيْنِ مِنَ الظُّهْرِ قَدْرَ قِرَاءَةِ ﴿ الٓمٓ (1) تَنْزِيلُ﴾ السَّجْدَةِ، وَحَزَرْنَا قِيَامَهُ فِي الأُخْرَيَيْنِ قَدْرَ النِّصْفِ مِنْ ذَلِكَ، وَحَزَرْنَا قِيَامَهُ فِي الرَّكْعَتَيْنِ الأُولَيَيْنِ مِنَ الْعَصْرِ عَلَى قَدْرِ قِيَامِهِ فِي الأُخْرَيَيْنِ مِنَ الظُّهْرِ، وَفِي الأُخْرَيَيْنِ مِنَ الْعَصْرِ عَلَى النِّصْفِ مِنْ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (452) من طريق منصور، عن الوليد بن أبي بشر، عن أبي الصديق الناجي، عن أبي سعيد فذكره. وفي رواية أخرى (454) قال: لقد كانت صلاة الظهر تقام، فيذهب الذاهب إلى البقيع، فيقضي حاجته، ثم يتوضأ، ثم يأتي ورسول الله صلى الله عليه وسلم في الركعة الأولى مما يطولها.","grade":"صحيح","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (452)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Prophet ﷺ used to recite in the noon prayer, in the first two units, in each unit about thirty verses; and in the last two, about fifteen verses—or he said: about half of that. In the afternoon prayer, in the first two units, in each unit about fifteen verses, and in the last two about half of that. In another narration: We estimated his standing in the first two units of noon prayer to be about the length of reciting “Alif-Lam-Mim. The Revelation…” (Surat al-Sajdah), and we estimated his standing in the last two to be about half of that. We estimated his standing in the first two units of the afternoon prayer to be like his standing in the last two units of the noon prayer, and in the last two of the afternoon prayer to be about half of that."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (452)."},{"num":2008,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَانَ يَقْرَأُ فِي الظُّهْرِ بِـــ ﴿سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى﴾ وَفِي الصُّبْحِ بِأَطْوَلَ مِنْ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (460) من طريق أبي داود الطيالسي، عن شعبة، عن سماك، عن جابر بن سمرة فذكر.","grade":"صحيح","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (460)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn Samurah said: The Prophet ﷺ used to recite in the noon prayer: “Glorify the Name of your Lord, the Most High,” and in the dawn prayer with something longer than that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (460)."},{"num":2009,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ بِـــ ﴿وَالسَّمَاءِ وَالطَّارِقِ﴾، وَ ﴿وَالسَّمَاءِ ذَاتِ الْبُرُوجِ﴾ وَنَحْوِهِمَا مِنَ السُّوَرِ."],"takhrij":"حسن: رواه أبو داود (805) والترمذي (307) والنسائي (979) والدارمي (1293) كلّهم من طريق حماد بن سلمة، عن سماك بن حرب، عن جابر بن سمرة فذكره، وزاد الدارمي: ﴿وَالْعَصْرِ﴾.","grade":"حسن","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (805), al-Tirmidhi (307), al-Nasa’i (979) — al-Tirmidhi said: “Hasan Sahih”","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn Samurah said: The Messenger of Allah ﷺ used to recite in the noon and afternoon prayers: “By the sky and the night-comer” and “By the sky containing great constellations,” and similar chapters."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (805)، الترمذي (307)، النسائي (979)، وقال الترمذي: حسن صحيح."},{"num":2010,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ بْنِ عَبْدِالْمُطَّلِب قَالَ: دَخَلْتُ عَلَى ابْنِ عَبَّاسٍ فِي شَبَابٍ مِنْ بَنِي هَاشِمٍ، فَقُلْنَا لِشَابٍّ مِنَّا: سَلْ ابْنَ عَبَّاسٍ أَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ ؟ فَقَالَ: لَا، لَا. فَقِيلَ لَهُ: فَلَعَلَّهُ كَانَ يَقْرَأُ فِي نَفْسِهِ، فَقَالَ: خَمْشًا هَذِهِ شَرٌّ مِنَ الْأُولَى كَانَ عَبْدًا مَأْمُورًا بَلَّغَ مَا أُرْسِلَ بِهِ، وَمَا اخْتَصَّنَا دُونَ النَّاسِ بِشَيْءٍ إِلَّا بِثَلَاثِ خِصَالٍ: أَمَرَنَا أَنْ نُسْبِغَ الْوُضُوءَ، وَأَنْ لَا نَأْكُلَ الصَّدَقَةَ، وَأَنْ لَا نُنْزِيَ الْحِمَارَ عَلَى الْفَرَسِ."],"takhrij":"حسن: رواه أبو داود (808) واللفظ له، والترمذي (1710) النسائي (141) وابن ماجه (426) كلهم من طرق عن أبي جهضم موسى بن سالم، عن عبدالله بن عبيدالله به فذكر مثله، قال الترمذي: حسن صحيح، إلا أن ابن ماجه اختصره.","grade":"حسن","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (808); al-Tirmidhi (1701); al-Nasa’i (141); Ibn Majah (426)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["‘Abdullah ibn ‘Ubaydillah ibn ‘Abbas ibn ‘Abd al-Muttalib said: I entered upon Ibn ‘Abbas with a group of young men from Banu Hashim. We said to one of our young men: “Ask Ibn ‘Abbas whether the Messenger of Allah ﷺ used to recite in the noon and afternoon prayers.” He said: “No, no.” It was said to him: “Perhaps he used to recite silently to himself?” He said: “May he be scratched! This is worse than the first.” He was a servant commanded to convey what he was sent with. And he did not single us out over the people with anything except three traits: “We were commanded to perform ablution thoroughly, not to eat charity, and not to mate a donkey with a horse.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (808)، الترمذي (1710)، النسائي (141)، ابن ماجه (426)."},{"num":2011,"demo":false,"sanad":"","matn":["عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، عَنْ أَبِي هُرَيْرَةَ قال: مَا صَلَّيْتُ وَرَاءَ أَحَدٍ أَشْبَهَ صَلَاةً بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ فُلَانٍ فَصَلَّيْنَا وَرَاءَ ذَلِكَ الْإِنْسَانِ وَكَانَ يُطِيلُ الْأُولَيَيْنِ مِنَ الظُّهْرِ وَيُخَفِّفُ فِي الْأُخْرَيَيْنِ وَيُخَفِّفُ فِي الْعَصْرِ وَيَقْرَأُ فِي الْمَغْرِبِ بِقِصَارِ الْمُفَصَّلِ وَيَقْرَأُ فِي الْعِشَاءِ بِالشَّمْسِ وَضُحَاهَا وَأَشْبَاهِهَا وَيَقْرَأُ فِي الصُّبْحِ بِسُورَتَيْنِ طَوِيلَتَيْنِ."],"takhrij":"حسن: رواه النسائي (982) (983) واللفظ له، وابن ماجه (827) مختصراً كلاهما من طريق الضحاك بن عثمان، عن بكير بن عبدالله بن الأشجّ، عن سليمان بن يسار، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (982–983) — wording his; Ibn Majah (827); Ahmad (8366)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Sulayman ibn Yasar narrated from Abu Hurayrah that he said: “I have not prayed behind anyone whose prayer resembles the prayer of the Messenger of Allah ﷺ more than so-and-so.” Sulayman said: We prayed behind that man, and he would lengthen the first two units of the noon prayer and shorten the last two; he would make the afternoon prayer light; he would recite in the sunset prayer from the shorter chapters of the Mufassal; he would recite in the night prayer “By the sun and its brightness” and similar chapters; and he would recite in the dawn prayer two long chapters."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (982–983)، واللفظ له، ابن ماجه (827)، أحمد (8366)."},{"num":2012,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: مَا رَأَيْتُ أَحَدًا أَشْبَهَ صَلَاةً بِصَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ هَذَا الْفَتَى، يَعْنِي عُمَرَ بْنَ عَبْدِ الْعَزِيزِ.","قَالَ الضَّحَّاكُ: فَصَلَّيْتُ خَلْفَ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ، وَكَانَ يَصْنَعُ مِثْلَ مَا قَالَ سُلَيْمَانُ بْنُ يَسَارٍ."],"takhrij":"حسن: رواه أحمد (8366) عن أبي بكر الحنفي، حدّثنا الضحاك بن عثمان، حدثني بكير بن عبدالله بن الأشج، عن سليمان بن يسار، عن أبي هريرة، فذكر الحديث كما سبق.","grade":"حسن","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (8366)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Anas ibn Malik said: I have not seen anyone whose prayer resembles the prayer of the Messenger of Allah ﷺ more than this young man—meaning ‘Umar ibn ‘Abd al-‘Aziz.","Al-Dahhak said: I prayed behind ‘Umar ibn ‘Abd al-‘Aziz, and he used to do as Sulayman ibn Yasar described."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8366)."},{"num":2013,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ: ﴿سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى﴾ وَ ﴿هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ﴾."],"takhrij":"صحيح: رواه البزار-كشف الأستار (482) عن محمد بن معمر، ثنا روح بن عبادة، ثنا حماد بن سلمة، عن ثابت وقتادة وحُميد، عن أنس فذكر الحديث.","grade":"صحيح","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bazzar (Kashf al-Astar, 482), Ibn Khuzaymah (512), Ibn Hibban (1824)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ used to recite in the noon and afternoon prayers: “Glorify the Name of your Lord, the Most High,” and “Has there come to you the news of the Overwhelming?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار (كشف الأستار، 482)، ابن خزيمة (512)، ابن حبان (1824)."},{"num":2014,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَسْلَمَ قال: دَخَلْنَا عَلَى أَنَسِ بْنِ مَالِكٍ، فَقَالَ: صَلَّيْتُمْ؟ قُلْنَا: نَعَمْ، قَالَ: يَا جَارِيَةُ هَلُمِّي لِي وَضُوءًا مَا صَلَّيْتُ وَرَاءَ إِمَامٍ أَشْبَهَ صَلَاةً بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ إِمَامِكُمْ هَذَاَ. قَالَ زَيْدٌ: وَكَانَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ يُتِمُّ الرُّكُوعَ وَالسُّجُودَ وَيُخَفِّفُ الْقِيَامَ وَالْقُعُودَ."],"takhrij":"حسن: رواه النسائي (981) عن قتيبة، قال: حدّثنا العطَّاف بن خالد، عن زيد بن أسلم، قال (فذكره).","grade":"حسن","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (981)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Zayd ibn Aslam said: We entered upon Anas ibn Malik and he said: “Have you prayed?” We said: “Yes.” He said: “Girl, bring me water for ablution. I have not prayed behind an imam whose prayer resembles the prayer of the Messenger of Allah ﷺ more than your imam.” Zayd said: That imam was ‘Umar ibn ‘Abd al-‘Aziz: he would complete the bowing and prostration, and he would lighten the standing and sitting."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (981)."},{"num":2015,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ الْأَسْلَمِيِّ، عَنْ أَبِيهِ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الظُّهْرِ بِـــ ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ وَنَحْوِهَا."],"takhrij":"حسن: رواه ابن خزيمة (511) عن محمد بن حرب الواسطي، ثنا زيد بن الحباب، عن الحسن بن واقد قاضي مرو، قال: أخبرني عبدالله بن بريدة، عن أبيه فذكر الحديث. وإسناده حسن لأجل الحسين بن واقد فإنه صدوق لأن أكثر النقاد قالوا: إنه لا بأس به، وهو من رجال مسلم، وأما الحافظ فجعله في مرتبة ثقة له أوهام وهو أحق أن يقال فيه: صدوق وسيأتي حديث آخر عن بريدة الأسلمي بهذا الإسناد في باب القراءة في صلاة العشاء، وفي الإسناد أيضاً زيد بن الحباب وهو ممن يحسن حديثه.","grade":"حسن","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (511)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["‘Abdullah ibn Buraydah al-Aslami narrated from his father that the Prophet ﷺ used to recite in the noon prayer: “When the sky is split open,” and similar chapters."]}},"tuhfa":{},"full":1,"tks":"حسن: رواه ابن خزيمة (511)."},{"num":2016,"demo":false,"sanad":"","matn":["عَنْ بَعْضِ أَصْحَابِ النَّبيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَتْ تُعْرَفُ قِرَاءَةُ النَّبيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الظُّهْرِ، بِتَحْرِيكِ لِحْيَتِهِ."],"takhrij":"صحيح: رواه الإمام أحمد (23153) عن عبدالرحمن بن مهدي، عن سفيان، عن أبي الزعراء، عن أبي الأحوص، عن بعض أصحاب النبي صلى الله عليه وسلم.","grade":"صحيح","chapter_ar":"باب القراءة في الصبح والظهر والعصر وفي الصلوات الأخرى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (23153), Ibn Abi Shaybah (1/362)","chapter_en":"Recitation in the dawn, noon, and afternoon prayers, and in the other prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["One of the Companions said: The Prophet ﷺ’s recitation in the noon prayer used to be recognized by the movement of his beard."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23153)، ابن أبي شيبة (1/362)."},{"num":2017,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: إِنَّ أُمَّ الْفَضْلِ بِنْتَ الْحَارِثِ سَمِعَتْهُ وَهُوَ يَقْرَأُ: ﴿وَالْمُرْسَلاتِ عُرْفًا﴾ فَقَالَتْ: يَا بُنَيَّ، لَقَدْ ذَكَّرْتَنِي بِقِرَاءَتِكَ هَذِهِ السُّورَةَ، إِنَّهَا لَآخِرُ مَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ بِهَا فِي الْمَغْرِبِ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (24) عن ابن شهاب، عن عبيدالله بن عبدالله بن عتبة بن مسعود، عن عبدالله بن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب القراءة في صلاة المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (24), al-Bukhari (763), Muslim (462)","chapter_en":"Recitation in the sunset prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Ibn ‘Abbas said: Umm al-Fadl bint al-Harith heard him reciting “By those sent forth,” and she said: “My son, you reminded me by reciting this chapter. It was the last thing I heard the Messenger of Allah ﷺ recite with in the sunset prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (24)، البخاري (763)، مسلم (462)."},{"num":2018,"demo":false,"sanad":"","matn":["عَنْ جُبَيْرِ بْنِ مُطْعِمٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ بِالطُّورِ فِي الْمَغْرِبِ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (23) عن ابن شهاب، عن محمد بن جبير بن مطعم، عن أبيه فذكره.","grade":"متفق عليه","chapter_ar":"باب القراءة في صلاة المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (23), al-Bukhari (765), Muslim (463)","chapter_en":"Recitation in the sunset prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Jubayr ibn Mut‘im said: I heard the Messenger of Allah ﷺ recite “By the Mount” in the sunset prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (23)، البخاري (765)، مسلم (463)."},{"num":2019,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْمَغْرِبِ بِقِصَارِ الْمُفَصَّلِ."],"takhrij":"حسن: رواه الطحاوي في شرح المعاني (1278) من حديث أبي بكر بن أبي شيبة، قال: حدثنا زيد بن الحباب، قال: ثنا الضحاك بن عثمان، قال: حدثني بكير بن الأشج، عن سليمان بن يسار، عن أبي هريرة، فذكره. وإسناده حسن.","grade":"حسن","chapter_ar":"باب القراءة في صلاة المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tahawi in Sharh Ma‘ani al-Athar (1243)","chapter_en":"Recitation in the sunset prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ used to recite in the sunset prayer from the shorter chapters of the Mufassal."]}},"tuhfa":{},"full":1,"tks":"حسن: رواه الطحاوي في شرح معاني الآثار (1278)."},{"num":2020,"demo":false,"sanad":"","matn":["عَنْ مَرْوَانَ بْنِ الْحَكَمِ قَالَ: قَالَ لِي زَيْدُ بْنُ ثَابِتٍ: مَا لَكَ تَقْرَأُ فِي الْمَغْرِبِ بِقِصَارٍ، وَقَدْ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ بِطُولِ الطُّولَيَيْنِ."],"takhrij":"صحيح: رواه البخاري في الأذان (764) عن أبي عاصم، عن ابن جريج، عن ابن أبي مليكة، عن عروة بن الزبير، عن مروان فذكر الحديث.","grade":"صحيح","chapter_ar":"باب القراءة في صلاة المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (764)","chapter_en":"Recitation in the sunset prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Marwan ibn al-Hakam said: Zayd ibn Thabit said to me: “Why do you recite short chapters in the sunset prayer, when I heard the Prophet ﷺ recite the longer of the two long surahs?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (764)."},{"num":2021,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ بِهِمْ فِي الْمَغْرِبِ: ﴿الَّذِينَ كَفَرُوا وَصَدُّوا عَنْ سَبِيلِ اللَّهِ أَضَلَّ أَعْمَالَهُمْ﴾ [سورة محمد: 1]."],"takhrij":"صحيح: أخرجه الطبراني في الكبير (13380) والأوسط (1742، 1239) والصغير sh13068(117) من طريق الحسين بن حُريت المروزي، ثنا أبو معاوية محمد ابن خازم، ثنا عبيدالله بن عمر، عن نافع، عن ابن عمر فذكر الحديث. وأخرجه ابن حبان في صحيحه (1835) من هذا الوجه.","grade":"صحيح","chapter_ar":"باب القراءة في صلاة المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Tabarani in al-Mu‘jam al-Kabir (12/372), al-Awsat (2/441), al-Saghir (1/45), and Ibn Hibban (1835)","chapter_en":"Recitation in the sunset prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported that the Prophet ﷺ used to recite with them in the sunset prayer: “Those who disbelieve and hinder others from the Way of Allah—He has rendered their deeds void.” (Qur’an 47:1)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في المعجم الكبير (13380)، وفي المعجم الأوسط (1742، 1239)، والمعجم الصغير (117)، وابن حبان (1835)."},{"num":2022,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ مِنَ الْمَغْرِبِ بِسُورَةِ الْأَنْفَالِ."],"takhrij":"حسن: رواه الطبراني في المعجم الكبير (4824) قال: حدثنا عبدالرحمن بن سلم الرازي، ثنا سهل بن عثمان، ثنا عقبة بن خالد، عن هشام بن عروة، عن أبيه، عن زيد بن ثابت فذكر الحديث.","grade":"حسن","chapter_ar":"باب القراءة في صلاة المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (5/136).","chapter_en":"Recitation in the sunset prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Zayd ibn Thabit reported that the Prophet ﷺ used to recite Surat al-Anfal in the two units of the sunset prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الكبير (4824)."},{"num":2023,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ، أَوْ عَنْ زَيْدِ بْنِ ثَابِتٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ فِي الْمَغْرِبِ بِالْأَعْرَافِ فِي الرَّكْعَتَيْنِ."],"takhrij":"صحيح: رواه الإمام أحمد (23544)، والطبراني في الكبير (4823) كلاهما عن وكيع، حدثنا هشام بن عروة، عن أبيه، عن أبي أيوب، أو عن زيد ابن ثابت فذكر الحديث.","grade":"صحيح","chapter_ar":"باب القراءة في صلاة المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (23544); al-Tabarani in al-Mu‘jam al-Kabir (5/136)","chapter_en":"Recitation in the sunset prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Abu Ayyub—or Zayd ibn Thabit—reported that the Prophet ﷺ recited Surat al-A‘raf in the sunset prayer across the two units."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23544)، الطبراني في المعجم الكبير (4823)."},{"num":2024,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ أَنَّهُ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ فَقَرَأَ فِيهَا بِـــ ﴿التِّينِ وَالزَّيْتُونِ﴾."],"takhrij":"متفق عليه: رواه مالك في الصلاة (27) عن يحيى بن سعيد، عن عدى ابن ثابت الأنصاري، عن البراء، فذكره.","grade":"متفق عليه","chapter_ar":"باب القراءة في صلاة العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (27), al-Bukhari (767), Muslim (464)","chapter_en":"Recitation in the night prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":23,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib said: I prayed the night prayer with the Messenger of Allah ﷺ, and he recited in it: “By the fig and the olive” (Surat al-Tin)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (27)، البخاري (767)، مسلم (464)."},{"num":2025,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: كَانَ مُعَاذٌ يُصَلِّي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ يَأْتِي فَيَؤُمُّ قَوْمَهُ، فَصَلَّى لَيْلَةً مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ، ثُمَّ أَتَى قَوْمَهُ فَأَمَّهُمْ، فَافْتَتَحَ بِسُورَةِ الْبَقَرَةِ، فَانْحَرَفَ رَجُلٌ فَسَلَّمَ، ثُمَّ صَلَّى وَحْدَهُ وَانْصَرَفَ، فَقَالُوا لَهُ: أَنَافَقْتَ يَا فُلَانُ ؟ قَالَ: لَا وَاللَّهِ، وَلَآتِيَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَأُخْبِرَنَّهُ، فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! إِنَّا أَصْحَابُ نَوَاضِحَ نَعْمَلُ بِالنَّهَارِ، وَإِنَّ مُعَاذًا صَلَّى مَعَكَ الْعِشَاءَ، ثُمَّ أَتَى فَافْتَتَحَ بِسُورَةِ الْبَقَرَةِ، فَأَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى مُعَاذٍ فَقَالَ: يَا مُعَاذُ! أَفَتَّانٌ أَنْتَ، اقْرَأْ بِكَذَا، وَاقْرَأْ بِكَذَا."],"takhrij":"متفق عليه: رواه مسلم في الصلاة (465) عن محمد عباد، حدثنا سفيان، عن عمرو، عن جابر فذكره.","grade":"متفق عليه","chapter_ar":"باب القراءة في صلاة العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (465).","chapter_en":"Recitation in the night prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":23,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: Muʿādh used to pray with the Prophet ﷺ and then go and lead his people in prayer. One night, he prayed ʿIshāʾ with the Prophet ﷺ, then went to his people and led them, beginning with Sūrat al-Baqarah. A man withdrew, gave salām, then prayed by himself and left. They said to him: “Have you become a hypocrite, so-and-so?” He said: “No, by Allah. I will certainly go to the Messenger of Allah ﷺ and inform him.” He came to the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ, we are people who work during the day with camels used for drawing water. Muʿādh prayed ʿIshāʾ with you, then came to us and began with Sūrat al-Baqarah.” The Messenger of Allah ﷺ turned to Muʿādh and said: “O Muʿādh, are you putting people to trial? Recite such-and-such, and recite such-and-such.” Sufyān said: I said to ʿAmr: “Abū al-Zubayr narrated to us from Jābir that he said: ‘Recite: “By the sun and its brightness,” “By the morning brightness,” “By the night when it covers,” and “Glorify the Name of your Lord, the Most High.”’” ʿAmr said: “Something like that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (465)."},{"num":2026,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهَا قَالَتْ: شَكَوْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِّي أَشْتَكِي، فَقَالَ: طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ، قَالَتْ: فَطُفْتُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَئِذٍ يُصَلِّي إِلَى جَنْبِ الْبَيْتِ وَهُوَ يَقْرَأُ بِ ﴿الطُّورِ وَكِتَابٍ مَسْطُورٍ﴾.","وَفِي رِوَايَةِ: قَالَتْ: فَطُفْتُ رَاكِبَةً بَعِيرِي، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَئِذٍ يُصَلِّي إِلَى جَانِبِ الْبَيْتِ، وَهُوَ يَقْرَأُ ﴿بِالطُّورِ وَكِتَابٍ مَسْطُورٍ﴾."],"takhrij":"متفق عليه: أخرجه مالك في الحج (123) عن أبي الأسود محمد بن عبدالرحمن بن نوفل، عن عروة بن الزبير، عن زينب بنت أبي سلمة، عن أم سلمة زوج النبي صلى الله عليه وسلم فذكرته.","grade":"متفق عليه","chapter_ar":"باب القراءة في صلاة العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (123), al-Bukhari (464), Muslim (1276)","chapter_en":"Recitation in the night prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":23,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: I complained to the Messenger of Allah ﷺ that I was unwell, so he said: “Circumambulate behind the people while riding.” She said: So I performed circumambulation while riding my camel, and at that time the Messenger of Allah ﷺ was praying by the House and reciting: “By the Mount” (Surat al-Tur)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (123)، البخاري (464)، مسلم (1276)."},{"num":2027,"demo":false,"sanad":"","matn":["عَنْ أَبِي رَافِعٍ قَالَ: صَلَّيْتُ مَعَ أَبِي هُرَيْرَةَ الْعَتَمَةَ، فَقَرَأَ: ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ فَسَجَدَ فَقُلْتُ: مَا هَذِهِ ؟ قَالَ: سَجَدْتُ بِهَا خَلْفَ أَبِي الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَا أَزَالُ أَسْجُدُ بِهَا حَتَّى أَلْقَاهُ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (768)، ومسلم في المساجد (578/110)، كلاهما عن المعتمر بن سليمان التيمي، عن أبيه، عن بكر، عن أبي رافع فذكره. وبكر هو: ابن عبدالله المزني. وأبو رافع هو: نُفَيع الصائغ مشهورٌ بكنيته.","grade":"متفق عليه","chapter_ar":"باب القراءة في صلاة العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (766), Muslim (578/110)","chapter_en":"Recitation in the night prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":23,"content":{"translation":{"en":["Abu Rafi‘ said: I prayed the night prayer with Abu Hurayrah. He recited: “When the sky is split open” (Surat al-Inshiqaq) and then performed the prostration of recitation. I asked: “What is this?” He said: “I prostrated with it behind Abu al-Qasim ﷺ, and I will keep prostrating with it until I meet him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (768)، مسلم (578/110)."},{"num":2028,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ الْأَسْلَمِيِّ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْعِشَاءِ الْآخِرَةِ بِـــ الشَّمْسِ وَضُحَاهَا وَنَحْوِهَا مِنَ السُّوَرِ."],"takhrij":"حسن: رواه الترمذي (309)، والنسائي (999) كلاهما من طريق الحسين بن واقد، عن عبدالله بن بربدة، عن أبيه بريدة فذكر مثله، ومن هذا الوجه أخرجه أيضاً الإمام أحمد (22994).","grade":"حسن","chapter_ar":"باب القراءة في صلاة العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tirmidhi (309) — he graded it good; al-Nasa’i (999); Ahmad (22994)","chapter_en":"Recitation in the night prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":23,"content":{"translation":{"en":["Buraydah al-Aslami said: The Messenger of Allah ﷺ used to recite in the later night prayer: “By the sun and its brightness,” and similar chapters."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (309) — وحسنه، النسائي (999)، أحمد (22994)."},{"num":2029,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: قَالَ عُمَر لِسَعْدٍ: لَقَدْ شَكَوْكَ فِي كُلِّ شَيْءٍ حَتَّى الصَّلَاةِ، قَالَ: أَمَّا أَنَا فَأَمُدُّ فِي الْأُولَيَيْنِ وَأَحْذِفُ فِي الْأُخْرَيَيْنِ، وَلَا آلُو مَا اقْتَدَيْتُ بِهِ مِنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: صَدَقْتَ ذَاكَ الظَّنُّ بِكَ أَوْ ظَنِّي بِكَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان(770) ومسلم في الصلاة (453/159) كلاهما من حديث شعبة، عن أبي عون، قال: سمعت جابر بن سمرة فذكره.","grade":"متفق عليه","chapter_ar":"باب في تطويل الركعتين الأوليين والاقتصار في الأخريين في العشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (770), Muslim (453/159)","chapter_en":"Lengthening the first two units and shortening the last two in the night prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn Samurah said: ‘Umar said to Sa‘d: “They have complained about you in everything, even about the prayer.” Sa‘d said: “As for me, I lengthen the first two units and shorten the last two, and I do my utmost to follow the prayer of the Messenger of Allah ﷺ.” He said: “You have spoken the truth; that is what is thought of you”—or “what I think of you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (770)، مسلم (453/159)."},{"num":2030,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَرَأَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا أُمِرَ وَسَكَتَ فِيمَا أُمِرَ. ﴿وَمَا كَانَ رَبُّكَ نَسِيًّا﴾ [مريم: 64]. ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ﴾ [الأحزاب 21]."],"takhrij":"صحيح: رواه البخاري في الأذان (774) عن مسدد، قال: حدَّثنا إسماعيل، قال: حدَّثنا أيوب، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب قراءة النبي ﷺ سِرًّا وجَهْرًا كان بيانًا لمجمل القرآن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari in the Book of the Call to Prayer (774)","chapter_en":"The Prophet ﷺ’s silent and audible recitation clarified what the Qur’an states in general terms","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":25,"content":{"translation":{"en":["Ibn ‘Abbas said: The Prophet ﷺ recited aloud where he was commanded, and he was silent where he was commanded. “And your Lord is never forgetful” (Qur’an 19:64). “Indeed, in the Messenger of Allah you have an excellent example” (Qur’an 33:21)."]},"buhuth":{"en":["“Where he was commanded” means where he was commanded to recite audibly or silently. “And he was silent” means he recited quietly (silently). And “your Lord is never forgetful” means Allah did not leave the details of prayer—such as what is recited aloud or silently—without clarification; rather, He clarified them through the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (774)."},{"num":2031,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ رَجُلًا عَلَى سَرِيَّةٍ وَكَانَ يَقْرَأُ لِأَصْحَابِهِ فِي صَلَاتِهِمْ فَيَخْتِمُ بِـــ ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ فَلَمَّا رَجَعُوا ذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: سَلُوهُ لِأَيِّ شَيْءٍ يَصْنَعُ ذَلِكَ، فَسَأَلُوهُ ؟، فَقَالَ: لِأَنَّهَا صِفَةُ الرَّحْمَنِ وَأَنَا أُحِبُّ أَنْ أَقْرَأَ بِهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَخْبِرُوهُ أَنَّ اللَّهَ يُحِبُّهُ."],"takhrij":"متفق عليه: أخرجه البخاري في التوحيد (7375)، ومسلم في صلاة المسافرين (813) كلاهما من طريق عبدالله بن وهب، ثنا عمرو بن الحارث، عن سعيد بن أبي هلال، أن أبا الرجال محمد بن عبدالرحمن حدثه، عن أمه عمرة بنت عبدالرحمن، وكانت في حَجْر عائشة زوج النبي صلى الله عليه وسلم عن عائشة فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تكرار قراءة سورة واحدة في كل ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (7375), Muslim (813)","chapter_en":"Repeating the recitation of one surah in both units","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":26,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ sent a man on an expedition. He would lead his companions in prayer and would always finish his recitation with “Say: He is Allah, One.” When they returned, they mentioned that to the Prophet ﷺ. He said: “Ask him why he does that.” They asked him and he said: “Because it describes the Most Merciful, and I love to recite it.” The Prophet ﷺ said: “Tell him that Allah loves him.”"]}},"tuhfa":{},"full":1,"rep":[246],"tks":"متفق عليه: رواه البخاري (7375)، مسلم (813)."},{"num":2032,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ رَجُلٌ مِنْ الْأَنْصَارِ يَؤُمُّهُمْ فِي مَسْجِدِ قُبَاءَ، فَكَانَ كُلَّمَا افْتَتَحَ سُورَةً يَقْرَأُ لَهُمْ فِي الصَّلَاةِ فَقَرَأَ بِهَا افْتَتَحَ بِـــ ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ حَتَّى يَفْرُغَ مِنْهَا، ثُمَّ يَقْرَأُ بِسُورَةٍ أُخْرَى مَعَهَا، وَكَانَ يَصْنَعُ ذَلِكَ فِي كُلِّ رَكْعَةٍ، فَكَلَّمَهُ أَصْحَابُهُ فَقَالُوا: إِنَّكَ تَقْرَأُ بِهَذِهِ السُّورَةِ ثُمَّ لَا تَرَى أَنَّهَا تُجْزِيكَ حَتَّى تَقْرَأَ بِسُورَةٍ أُخْرَى، فَإِمَّا أَنْ تَقْرَأَ بِهَا وَإِمَّا أَنْ تَدَعَهَا وَتَقْرَأَ بِسُورَةٍ أُخْرَى، قَالَ: مَا أَنَا بِتَارِكِهَا، إِنْ أَحْبَبْتُمْ أَنْ أَؤُمَّكُمْ بِهَا فَعَلْتُ، وَإِنْ كَرِهْتُمْ تَرَكْتُكُمْ، وَكَانُوا يَرَوْنَهُ أَفْضَلَهُمْ وَكَرِهُوا أَنْ يَؤُمَّهُمْ غَيْرُهُ، فَلَمَّا أَتَاهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرُوهُ الْخَبَرَ فَقَالَ: يَا فُلَانُ، مَا يَمْنَعُكَ مِمَّا يَأْمُرُ بِهِ أَصْحَابُكَ وَمَا يَحْمِلُكَ أَنْ تَقْرَأَ هَذِهِ السُّورَةَ فِي كُلِّ رَكْعَةٍ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أُحِبُّهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ حُبَّهَا أَدْخَلَكَ الْجَنَّةَ."],"takhrij":"صحيح: أخرجه الترمذي (2901) عن محمد بن إسماعيل (البخاري) حدثنا إسماعيل بن أبي أويس، حدثنا عبدالعزيز بن محمد، عن عبيدالله بن عمر، عن ثابت البناني، عن أنس بن مالك فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في تكرار قراءة سورة واحدة في كل ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Tirmidhi (2901) — he said: “Hasan Gharib Sahih”","chapter_en":"Repeating the recitation of one surah in both units","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":26,"content":{"translation":{"en":["Anas ibn Malik said: A man from the Ansar used to lead them in the mosque of Quba’. Whenever he began a chapter to recite for them in prayer, he would first recite “Say: He is Allah, One” until he finished it, then he would recite another chapter along with it. He did that in every unit. His companions spoke to him and said: “You recite this chapter, then you do not think it is enough until you recite another chapter. Either recite only it, or leave it and recite another chapter.” He said: “I will not leave it. If you want me to lead you with it, I will; and if you dislike it, I will step aside.” They considered him their best and disliked anyone else leading them. When the Prophet ﷺ came to them, they told him. He said: “So-and-so, what prevents you from doing what your companions ask, and what makes you recite this chapter in every unit?” He said: “O Messenger of Allah, I love it.” The Messenger of Allah ﷺ said: “Your love for it will admit you into Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[247],"tks":"صحيح: رواه الترمذي (2901) — وقال: «حسن غريب صحيح»."},{"num":2033,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ عَبْدِ اللَّهِ الْجُهَنِيِّ، أَنَّ رَجُلًا مِنْ جُهَيْنَةَ، أَخْبَرَهُ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الصُّبْحِ: ﴿إِذَا زُلْزِلَتِ الأَرْضُ﴾ فِي الرَّكْعَتَيْنِ كِلْتَيْهِمَا. فَلَا أَدْرِي أَنَسِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْ قَرَأَ ذَلِكَ عَمْدًا."],"takhrij":"حسن: رواه أبو داود (816) عن أحمد بن صالح، حدثنا ابن وهب، أخبرني عمرو، عن ابن أبي هلال، عن معاذ بن عبدالله الجهني فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في تكرار قراءة سورة واحدة في كل ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (816)","chapter_en":"Repeating the recitation of one surah in both units","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":26,"content":{"translation":{"en":["Mu‘adh ibn ‘Abd Allah al-Juhani said that a man from Juhaynah told him that he heard the Prophet ﷺ recite in the dawn prayer “When the earth is shaken…” (Surat al-Zalzalah) in both units. I do not know whether the Messenger of Allah ﷺ forgot (and repeated it) or recited it intentionally."]},"buhuth":{"en":["When a Companion says, “I do not know whether he forgot or did it intentionally,” the default is that the Prophet ﷺ’s action is treated as a valid, legislated practice. If the narrator hesitates between forgetfulness and intent, it is assumed to have been intentional unless evidence indicates otherwise. No established prohibition has been found against repeating one chapter in both units; therefore, Abu Dawud and others titled a chapter: “A man repeats one surah in the two units.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13760],"tks":"حسن: رواه أبو داود (816)."},{"num":2034,"demo":false,"sanad":"","matn":["عَنْ أَبِي وَائِلٍ قَالَ: جَاءَ رَجُلٌ إِلَى ابْنِ مَسْعُودٍ فَقَالَ : قَرَأْتُ الْمُفَصَّلَ اللَّيْلَةَ فِي رَكْعَةٍ، فَقَالَ: هَذًّا كَهَذِّ الشِّعْرِ، لَقَدْ عَرَفْتُ النَّظَائِرَ الَّتِي كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرُنُ بَيْنَهُنَّ، فَذَكَرَ عِشْرِينَ سُورَةً مِنْ الْمُفَصَّلِ سورتيِن في كُلِّ رَكْعَةٍ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (775) ومسلم في صلاة المسافرين (722/279) كلاهما من طريق شعبة، عن عمرو بن مرة قال: سمعت أبا وائل قال: جاء رجل إلى عبدالله بن مسعود فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب الجمع بين السورتين في الركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (775), Muslim (722)","chapter_en":"Combining two surahs in one unit","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":27,"content":{"translation":{"en":["Ibn Mas‘ud said: A man came to him and said: “I recited the Mufassal tonight in one unit.” He said: “Rattling it off like the recitation of poetry! I know the paired surahs that the Prophet ﷺ used to join together.” Then he mentioned twenty surahs from the Mufassal—two surahs in each unit."]},"buhuth":{"en":["Muslim names the man in one narration as Nahik ibn Sinan. In that version, Ibn Mas‘ud also said: Some people recite the Qur’an but it does not go beyond their throats; rather, when it enters the heart and becomes firmly rooted, it benefits. He also mentioned that the best part of prayer is bowing and prostration, and that he knows the paired surahs the Messenger of Allah ﷺ used to combine—two in each unit.","“Paired surahs” means surahs that resemble each other in meaning, such as admonition, rulings, or narratives. “Rattling it off” means reciting with excessive speed."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13630],"tks":"متفق عليه: رواه البخاري (775)، مسلم (722)."},{"num":2035,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا سُئِلَتْ: هَلْ كَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ السُّوَرِ فِي رَكْعَةٍ؟ قَالَتْ: الْمُفَصَّلُ."],"takhrij":"صحيح: أخرجه أحمد (25687)، وإسحاق بن راهوية (1301)، كلاهما عن وكيع، نا كهمس بن الحسن، عن عبدالله بن شقيق، أنه سأل عائشة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب الجمع بين السورتين في الركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (25687); Ishaq ibn Rahawayh (1301); Ibn Khuzaymah (539)","chapter_en":"Combining two surahs in one unit","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":27,"content":{"translation":{"en":["‘Abdullah ibn Shaqiq said: I asked ‘A’ishah: “Did the Messenger of Allah ﷺ combine surahs in one unit?” She said: “From the Mufassal.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (25687)، إسحاق بن راهويه (1301)، ابن خزيمة (539)."},{"num":2036,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْعَالِيَةِ قَالَ: حَدَّثَنِي مَنْ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَعْطُوا كُلَّ سُورَةٍ حَظَّهَا مِنَ الرُّكُوعِ وَالسُّجُودِ."],"takhrij":"صحيح: رواه الإمام أحمد (20590) عن أبي معاوية وعبدة، قالا: حدثنا عاصم، عن أبي العالية فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء لكل سورة ركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (20590), Ibn Abi Shaybah (1/369)","chapter_en":"Giving each surah its due (in bowing and prostration)","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":28,"content":{"translation":{"en":["Abu al-‘Aliyah said: Someone who heard the Prophet ﷺ told me that he said: “Give each surah its share of bowing and prostration.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20590)، ابن أبي شيبة (3710)."},{"num":2037,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي لَا أَسْتَطِيعُ أَنْ آخُذَ مِنَ الْقُرْآنِ شَيْئًا، فَعَلِّمْنِي مَا يُجْزِئُنِي مِنْهُ ؟ قَالَ: قُلْ سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ قَالَ: يَا رَسُولَ اللَّهِ! هَذَا لِلَّهِ عَزَّ وَجَلَّ فَمَا لِي ؟ قَالَ: قُلْ اللَّهُمَّ ارْحَمْنِي، وَارْزُقْنِي، وَعَافِنِي، وَاهْدِنِي، فَلَمَّا قَامَ، قَالَ هَكَذَا بِيَدِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّا هَذَا فَقَدْ مَلَأَ يَدَهُ مِنَ الْخَيْرِ."],"takhrij":"حسن: رواه أبو داود (832)، والنسائي (924) كلاهما من طريق إبراهيم بن عبدالرحمن السكسكي، عن عبدالله بن أبي أوفي فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما يجزئ من القراءة في الصلاة لمن لا يحسن القرآن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (832), al-Nasa’i (924)","chapter_en":"What suffices in prayer recitation for one who does not know Qur’an well","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":29,"content":{"translation":{"en":["‘Abdullah ibn Abi Awfa said: A man came to the Prophet ﷺ and said: “I cannot take anything from the Qur’an (I cannot memorize/recite it), so teach me what will suffice me instead.” He said: “Say: Glory be to Allah; all praise is for Allah; there is no god worthy of worship except Allah; Allah is the Greatest; and there is no might and no power except with Allah, the Most High, the Most Great.” The man said: “O Messenger of Allah, this is for Allah, Mighty and Majestic—so what is for me?” He said: “Say: O Allah, have mercy on me, provide for me, grant me well-being, and guide me.” When the man stood up, he gestured with his hand like this, and the Messenger of Allah ﷺ said: “As for this one, he has filled his hand with goodness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (832)، النسائي (924)."},{"num":2038,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ، أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ الشَّيْطَانَ قَدْ حَالَ بَيْنِي وَبَيْنَ صَلَاتِي وَقِرَاءَتِي يَلْبِسُهَا عَلَيَّ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ذَاكَ شَيْطَانٌ يُقَالُ لَهُ خَنْزَبٌ، فَإِذَا أَحْسَسْتَهُ فَتَعَوَّذْ بِاللَّهِ مِنْهُ، وَاتْفِلْ عَلَى يَسَارِكَ ثَلَاثًا، قَالَ: فَفَعَلْتُ ذَلِكَ فَأَذْهَبَهُ اللَّهُ عَنِّي."],"takhrij":"صحيح: رواه مسلم في السلام (2203) عن يحيى بن خلف الباهلي، ثنا عبد الأعلى، عن سعيد الجريري، عن أبي العلاء (يزيد بن عبدالله بن الشخير)، أن عثمان بن أبي العاص أتى النبي صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب التعوذ من وسوسة الشيطان في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (2203)","chapter_en":"Seeking protection from Satan’s whispering in prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":30,"content":{"translation":{"en":["‘Uthman ibn Abi al-‘As said: I came to the Prophet ﷺ and said: “O Messenger of Allah, Satan has come between me and my prayer and my recitation, confusing it for me.” The Messenger of Allah ﷺ said: “That is a devil called Khanzab. If you sense him, seek Allah’s protection from him and spit lightly to your left three times.” He said: I did that and Allah removed it from me."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10276],"tks":"صحيح: رواه مسلم (2203)."},{"num":2039,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَافْتَتَحَ الْبَقَرَةَ، فَقُلْتُ يَرْكَعُ عِنْدَ الْمِائَةِ، ثُمَّ مَضَى، فَقُلْتُ: يُصَلِّي بِهَا فِي رَكْعَةٍ، فَمَضَى، فَقُلْتُ: يَرْكَعُ بِهَا، ثُمَّ افْتَتَحَ النِّسَاءَ فَقَرَأَهَا، ثُمَّ افْتَتَحَ آلَ عِمْرَانَ فَقَرَأَهَا، يَقْرَأُ مُتَرَسِّلًا، إِذَا مَرَّ بِآيَةٍ فِيهَا، تَسْبِيحٌ سَبَّحَ، وَإِذَا مَرَّ بِسُؤَالٍ سَأَلَ، وَإِذَا مَرَّ بِتَعَوُّذٍ تَعَوَّذَ... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم (772) عن أبي بكر بن أبي شيبة، ثنا عبدالله بن نمير، وأبو معاوية، عن الأعمش، عن سعد بن عبيدة، عن المستورد بن الأحنف، عن صلة بن زفر، عن حذيفة، فذكره.","grade":"صحيح","chapter_ar":"باب التسبيح والسؤال والتعوذ عند آيات التسبيح والرحمة والعذاب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (772)","chapter_en":"Glorifying Allah, asking, and seeking protection when reciting verses of glorification, mercy, and punishment","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":31,"content":{"translation":{"en":["Hudhayfah said: I prayed with the Prophet ﷺ one night. He began Surat al-Baqarah and I thought he would bow at one hundred verses, but he continued. I thought he would complete it in one unit, but he continued. Then I thought he would bow after it. Then he moved on and recited Surat al-Nisa’, then recited Al ‘Imran. He recited slowly and deliberately: when he passed a verse of glorification, he glorified Allah; when he passed a verse of asking, he asked; and when he passed a verse of seeking protection, he sought protection… (the hadith continues)."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (772)."},{"num":2040,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ قَالَ: قُمْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً فَقَامَ فَقَرَأَ سُورَةَ الْبَقَرَةِ لَا يَمُرُّ بِآيَةِ رَحْمَةٍ إِلَّا وَقَفَ فَسَأَلَ، وَلَا يَمُرُّ بِآيَةِ عَذَابٍ إِلَّا وَقَفَ فَتَعَوَّذَ... (فَذَكَرَ الْحَدِيثَ)."],"takhrij":"حسن: رواه أبو داود (873)، والنسائي (1132)، وأحمد (23980) كلّهم من حديث معاوية بن صالح، عن عمرو بن قيس، عن عاصم بن حميد، عن عوف بن مالك الأشجعي، فذكره.","grade":"حسن","chapter_ar":"باب التسبيح والسؤال والتعوذ عند آيات التسبيح والرحمة والعذاب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (873), al-Nasa’i (1132), Ahmad (23980)","chapter_en":"Glorifying Allah, asking, and seeking protection when reciting verses of glorification, mercy, and punishment","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":31,"content":{"translation":{"en":["‘Awf ibn Malik al-Ashja‘i said: I stood (in night prayer) with the Messenger of Allah ﷺ one night. He stood and recited Surat al-Baqarah. Whenever he passed a verse about mercy, he paused and asked (Allah); and whenever he passed a verse about punishment, he paused and sought refuge."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (873)، النسائي (1132)، أحمد (23980)."},{"num":2041,"demo":false,"sanad":"","matn":["عَنْ مُوسَى بْنِ أَبِي عَائِشَةَ قَالَ: كَانَ رَجُل يُصَلِّي فَوْقَ بَيْتِهِ، وَكَانَ إِذَا قَرَأَ ﴿أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى﴾ [القيامة: 40] قَالَ: سُبْحَانَكَ فَبَلَى. فَسَأَلُوهُ عَنْ ذَلِكَ، فَقَالَ: سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (884) عن محمد بن المثنى، حدّثنا محمد بن جعفر، حدّثنا شعبة، عن موسى بن أبي عائشة، فذكره.","grade":"صحيح","chapter_ar":"باب التسبيح والسؤال والتعوذ عند آيات التسبيح والرحمة والعذاب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (884)","chapter_en":"Glorifying Allah, asking, and seeking protection when reciting verses of glorification, mercy, and punishment","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":31,"content":{"translation":{"en":["Musa ibn Abi ‘A’ishah said: A man used to pray on top of his house. When he recited: “Is not that One able to bring the dead to life?” (Qur’an 75:40), he would say: “Glory be to You—indeed, yes.” They asked him about that, and he said: “I heard it from the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (884)."},{"num":2042,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَرَأَ: ﴿سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى﴾ قَالَ: سُبْحَانَ رَبِّيَ الأَعْلَى."],"takhrij":"صحيح: رواه أبو داود (883) عن زهير بن حرب، حدّثنا وكيع، عن إسرائيل، عن أبي إسحاق، عن مسلم البطين، عن سعيد بن جبير، عن ابن عباس، فذكره. ورواه الإمام أحمد (2066)، والحاكم (970) كلاهما من حديث وكيع.","grade":"صحيح","chapter_ar":"باب التسبيح والسؤال والتعوذ عند آيات التسبيح والرحمة والعذاب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (883), Ahmad (2066), al-Hakim (970)","chapter_en":"Glorifying Allah, asking, and seeking protection when reciting verses of glorification, mercy, and punishment","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صفة الصلاة من التكبير والقيام والقراءة","group_en":"Chapters on the description of the prayer: the opening declaration, standing, and recitation","part_no":9,"group_no":4,"chapter_no":31,"content":{"translation":{"en":["Ibn ‘Abbas said: When the Prophet ﷺ recited: “Glorify the Name of your Lord, the Most High” (Surat al-A‘la), he would say: “Glory be to my Lord, the Most High.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (883)، أحمد (2066)، الحاكم (970)."},{"num":2043,"demo":false,"sanad":"","matn":["عَنْ أَبِي يَعْفُورٍ قَالَ: سَمِعْتُ مُصْعَبَ بْنَ سَعْدٍ يَقُولُ: صَلَّيْتُ إِلَى جَنْب أَبِي فَطَبَّقْتُ بَيْنَ كَفَّيَّ ثُمَّ وَضَعْتُهُمَا بَيْنَ فَخِذَيَّ، فَنَهَانِي أَبِي وَقَالَ: كُنَّا نَفْعَلُهُ فَنُهِينَا عَنْهُ وَأُمِرْنَا أَنْ نَضَعَ أَيْدِينَا عَلَى الرُّكَبِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (790)، ومسلم في المساجد (535) كلاهما من طريق أبي يعفور به مثله، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صفة الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (790) — wording his; Muslim (535)","chapter_en":"The description of bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abu Ya‘fur said: I heard Mus‘ab ibn Sa‘d say: I prayed beside my father and clasped my palms together, then placed them between my thighs. My father forbade me and said: “We used to do that, but we were forbidden from it, and we were commanded to place our hands on the knees.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (790) — واللفظ له، مسلم (535)."},{"num":2044,"demo":false,"sanad":"","matn":["عَنِ الأَسْوَدِ وَعَلْقَمَةَ قَالَا: أَتَيْنَا عَبْدَ اللَّهِ بْنَ مَسْعُودٍ فِي دَارِهِ فَقَالَ: أَصَلَّى هَؤُلَاءِ خَلْفَكُمْ ؟ فَقُلْنَا: لَا، قَالَ: فَقُومُوا فَصَلُّوا، فَلَمْ يَأْمُرْنَا بِأَذَانٍ وَلَا إِقَامَةٍ، قَالَ: وَذَهَبْنَا لِنَقُومَ خَلْفَهُ، فَأَخَذَ بِأَيْدِينَا فَجَعَلَ أَحَدَنَا عَنْ يَمِينِهِ وَالآخَرَ عَنْ شِمَالِهِ، قَالَ: فَلَمَّا رَكَعَ وَضَعْنَا أَيْدِيَنَا عَلَى رُكَبِنَا، قَالَ: فَضَرَبَ أَيْدِيَنَا، وَطَبَّقَ بَيْنَ كَفَّيْهِ، ثُمَّ أَدْخَلَهُمَا بَيْنَ فَخِذَيْهِ، قَالَ: فَلَمَّا صَلَّى، قَالَ: إِنَّهُ سَتَكُونُ عَلَيْكُمْ أُمَرَاءُ يُؤَخِّرُونَ الصَّلَاةَ عَنْ مِيقَاتِهَا، وَيَخْنُقُونَهَا إِلَى شَرَقِ الْمَوْتَى، فَإِذَا رَأَيْتُمُوهُمْ قَدْ فَعَلُوا ذَلِكَ، فَصَلُّوا الصَّلَاةَ لِمِيقَاتِهَا، وَاجْعَلُوا صَلَاتَكُمْ مَعَهُمْ سُبْحَةً، وَإِذَا كُنْتُمْ ثَلَاثَةً فَصَلُّوا جَمِيعًا، وَإِذَا كُنْتُمْ أَكْثَرَ مِنْ ذَلِكَ، فَلْيَؤُمَّكُمْ أَحَدُكُمْ، وَإِذَا رَكَعَ أَحَدُكُمْ فَلْيُفْرِشْ ذِرَاعَيْهِ عَلَى فَخِذَيْهِ، وَلْيَجْنَأْ وَلْيُطَبِّقْ بَيْنَ كَفَّيْهِ، فَلَكَأَنِّي أَنْظُرُ إِلَى اخْتِلَافِ أَصَابِعِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَرَاهُمْ.","وفي رواية: فَلَكَأَنِّي أَنْظُرُ إِلَى اخْتِلَافِ أَصَابِعِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ رَاكِعٌ."],"takhrij":"صحيح: رواه مسلم في المساجد (534)، من طرق عن إبراهيم النخعي، عن الأسود وعلقمة به مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (534) in the Book of Mosques. Also narrated by al-Nasa’i (1031)","chapter_en":"The description of bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Al-Aswad and ‘Alqamah said: We came to ‘Abdullah ibn Mas‘ud in his house and he said: “Have these people prayed behind you?” We said: “No.” He said: “Then stand and pray.” He did not command us to give a call to prayer or to begin it. We went to stand behind him, and he took our hands and placed one of us to his right and the other to his left. When he bowed, we placed our hands on our knees, so he struck our hands and clasped his palms together, then put them between his thighs. When he finished praying, he said: “There will be leaders over you who delay the prayer beyond its appointed time and constrict it until near the end of the day. If you see them do that, then pray the prayer at its proper time, and make your prayer with them a voluntary prayer. If you are three, pray together; and if you are more than that, let one of you lead you. When one of you bows, let him spread his forearms on his thighs, lean forward, and clasp his palms together,”—and he said: “It is as if I can see the differing of the fingers of the Messenger of Allah ﷺ,” and he showed them. In another wording: “as if I can see the differing of the fingers of the Messenger of Allah ﷺ while he was bowing.”"]},"buhuth":{"en":["“They constrict it” means they make its time tight by delaying it. “Near the end of the day” has been explained as: only a little remains before sunset; and it has also been explained with an Arabic expression describing someone at the very last moments before death."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (534) في كتاب المساجد، ورواه أيضا النسائي (1031)."},{"num":2045,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: سَأَلَ رَجُلٌ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شَيْءٍ مِنْ أَمْرِ الصَّلَاةِ ؟ فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَلِّلْ أَصَابِعَ يَدَيْكَ وَرِجْلَيْكَ، يَعْنِي إِسْبَاغَ الْوُضُوءِ, وَكَانَ فِيمَا قَالَ لَهُ: إِذَا رَكَعْتَ، فَضَعْ كَفَّيْكَ عَلَى رُكْبَتَيْكَ حَتَّى تَطْمَئِنَّ، وَقَالَ الْهَاشِمِيُّ مَرَّةً: حَتَّى تَطْمَئِنَّا، وَإِذَا سَجَدْتَ فَأَمْكِنْ جَبْهَتَكَ مِنَ الْأَرْضِ، حَتَّى تَجِدَ حَجْمَ الْأَرْضِ."],"takhrij":"حسن: رواه الإمام أحمد (2604) حدثنا سليمان بن داود الهاشمي، حدثنا عبدالرحمن بن أبي الزناد، عن موسى بن عقبة، عن صالح مولى التوأمة قال: سمعت ابن عباس يقول فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في صفة الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (2604)","chapter_en":"The description of bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas said: A man asked the Prophet ﷺ about a matter related to prayer. The Messenger of Allah ﷺ said: “Pass water between the fingers of your hands and your feet,” meaning: perfect the ablution. And among what he said was: “When you bow, place your palms on your knees until you are settled and calm—and al-Hashimi once narrated it as: ‘until they are settled’—and when you prostrate, place your forehead firmly on the ground until you feel the firmness of the earth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (2604)."},{"num":2046,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ قَالَ: سَمِعْتُ أَبَا حُمَيْدٍ السَّاعِدِيَّ فِي عَشْرَةٍ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِمْ أَبُو قَتَادَةَ، فَقَالَ أَبُو حُمَيْدٍ: أَنَا أَعْلَمُكُمْ بِصَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ....وَفِيهِ: ثُمَّ يَرْكَعُ وَيَضَعُ رَاحَتَيْهِ عَلَى رُكْبَتَيْهِ مُعْتَمِدًا، لَا يَصُبُّ رَأْسَهُ وَلَا يُقْنِعُ مُعْتَدِلًا."],"takhrij":"صحيح: رواه أبو داود (730)، والترمذي (304)، وابن ماجة (1061) كلهم من طريق عبدالحميد بن جعفر، حدثنا محمد بن عمرو بن عطاء به مثله في حديث طويل وسبق تخريجه في باب رفع اليدين وفيه كلام. ورواه أيضاً النسائي (1040) من طريق عبدالحميد مختصراً بقوله: كان النبي صلى الله عليه وسلم إذا ركع اعتدل، فلم ينصب رأسه، ولم يُقْنِعه، ووضع يديه على ركبتيه.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (730), al-Tirmidhi (304), Ibn Majah (1061). Also narrated by al-Nasa’i (1040) in a shortened wording.","chapter_en":"The description of bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Muhammad ibn ‘Amr ibn ‘Ata’ said: I heard Abu Humayd al-Sa‘idi among ten of the Companions of the Messenger of Allah ﷺ, including Abu Qatadah. Abu Humayd said: “I know the prayer of the Messenger of Allah ﷺ best…” And in it: “Then he would bow and place his palms on his knees, leaning on them. He would neither lower his head down nor raise it up, but would remain balanced.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (730)، الترمذي (304)، ابن ماجه (1061)، ورواه أيضا النسائي (1040) مختصرا."},{"num":2047,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَكَعَ فَرَّجَ أَصَابِعَهُ، وَإِذَا سَجَدَ ضَمَّ أَصَابِعَهُ."],"takhrij":"حسن: رواه ابن خزيمة (594)، وابن حبان (1920)، والحاكم (826)، والبيهقي (2695) كلهم من حديث الحارث بن عبدالله بن إسماعيل بن عقبة بن الخازن، ثنا هشيم، عن عاصم بن كليب، عن علقمة بن وائل بن حجر، عن أبيه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في صفة الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (594), Ibn Hibban (1920), al-Hakim (822), al-Bayhaqi (2/112)","chapter_en":"The description of bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Wa’il ibn Hujr said: When the Messenger of Allah ﷺ bowed, he would spread his fingers, and when he prostrated, he would bring his fingers together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (594)، ابن حبان (1920)، الحاكم (826)، البيهقي (2695)."},{"num":2048,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ الْمَسْجِدَ فَدَخَلَ رَجُلٌ فَصَلَّى فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَدَّ وَقَالَ: ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ، فَرَجَعَ يُصَلِّي كَمَا صَلَّى ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ ثَلَاثًا، فَقَالَ: وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أُحْسِنُ غَيْرَهُ فَعَلِّمْنِي، فَقَالَ: إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ، ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنَ الْقُرْآنِ، ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا، ثُمَّ ارْفَعْ حَتَّى تَعْدِلَ قَائِمًا، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا، ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا وَافْعَلْ ذَلِكَ فِي صَلَاتِكَ كُلِّهَا."],"takhrij":"متفق عليه: رواه البخاري في الأذان (757)، ومسلم في الصلاة (397) كلاهما من طريق يحيى بن سعيد القطان، عن عبيدالله، قال: حدثني سعيد بن أبي سعيد، عن أبيه، عن أبي هريرة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (757), Muslim (397)","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ entered the mosque. A man entered, prayed, then came and greeted the Prophet ﷺ. He returned the greeting and said: “Go back and pray, for you have not prayed.” The man went back and prayed as he had prayed, then came and greeted him again. The Prophet ﷺ said: “Go back and pray, for you have not prayed,” three times. The man said: “By the One who sent you with the truth, I cannot do better than this—teach me.” He said: “When you stand for prayer, say “Allāhu akbar”. Then recite what is easy for you from the Qur’an. Then bow until you are settled in bowing. Then rise until you stand upright. Then prostrate until you are settled in prostration. Then rise until you are settled while sitting. Do that throughout your entire prayer.”"]},"intro":{"ar":["قال تعالى:","(قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ) [المؤمنون: ١-٢].","قال علي بن أبي طالب: الخشوع في القلب، أن لا تلتفت في صلاتك."],"en":["“Successful indeed are the believers—those who are humble in their prayer.” (The Believers 23:1–2)","‘Ali ibn Abi Talib said: Humility is in the heart—meaning: do not become distracted in your prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (757)، مسلم (397)."},{"num":2049,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَتَرَوْنَ قِبْلَتِي هَاهُنَا، فَوَاللَّهِ مَا يَخْفَى عَلَيَّ خُشُوعُكُمْ وَلَا رُكُوعُكُمْ، إِنِّي لَأَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي."],"takhrij":"متفق عليه: رواه مالك في قصر السفر (70) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (70), al-Bukhari (418, 741), Muslim (424). Also narrated by Muslim (423) with additional wording.","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Do you think my direction of prayer is only here in front of me? By Allah, your humility and your bowing are not hidden from me; I can see you from behind my back.” Muslim also has the wording: “and your prostration as well.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9644],"tks":"متفق عليه: رواه مالك (70)، والبخاري (418، 741)، ومسلم (424)، ورواه مسلم أيضا (423) بزيادة في اللفظ."},{"num":2050,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ بْنِ رَافِعٍ قَالَ: كُنْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا فِي الْمَسْجِدِ فَدَخَلَ رَجُلٌ فَصَلَّى رَكْعَتَيْنِ، ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْمُقُهُ فِي صَلَاتِهِ فَرَدَّ عَلَيْهِ السَّلَامَ ثُمَّ قَالَ لَهُ: ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ فَرَجَعَ فَصَلَّى ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَدَّ عَلَيْهِ السَّلَامَ، ثُمَّ قَالَ: ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ حَتَّى كَانَ عِنْدَ الثَّالِثَةِ أَوِ الرَّابِعَةِ فَقَالَ: وَالَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ لَقَدْ جَهِدْتُ وَحَرَصْتُ فَأَرِنِي وَعَلِّمْنِي قَالَ: إِذَا أَرَدْتَ أَنْ تُصَلِّيَ فَتَوَضَّأْ فَأَحْسِنْ وُضُوءَكَ، ثُمَّ اسْتَقْبِلِ الْقِبْلَةَ فَكَبِّرْ، ثُمَّ اقْرَأْ، ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا، ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِمًا، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا، ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ قَاعِدًا، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا، ثُمَّ ارْفَعْ فَإِذَا أَتْمَمْتَ صَلَاتَكَ عَلَى هَذَا فَقَدْ تَمَّتْ وَمَا انْتَقَصْتَ مِنْ هَذَا فَإِنَّمَا تَنْتَقِصُهُ مِنْ صَلَاتِكَ."],"takhrij":"صحيح: رواه النسائيّ (1314) من طريق داود بن قيس، قال: حدّثني علي بن يحيى بن خلاّد بن رافع بن مالك الأنصاريّ، قال: حدّثني أبي، عن عمّ له بدريّ، قال: كنت مع رسول الله صلى الله عليه وسلم، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (1314).","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Rifa‘ah ibn Rafi‘ said: I was sitting with the Messenger of Allah ﷺ in the mosque. A man entered and prayed two units, then came and greeted the Prophet ﷺ. The Prophet had been watching him during his prayer. He returned the greeting and said: “Go back and pray, for you have not prayed.” The man went back and prayed, then came and greeted him again, so he returned the greeting and said: “Go back and pray, for you have not prayed.” When it happened the third or fourth time, the man said: “By the One who revealed the Book to you, I have tried my best—show me and teach me.” He said: “When you want to pray, perform ablution and do it well. Then face the direction of prayer, say “Allāhu akbar”, then recite. Then bow until you are settled in bowing, then rise until you stand upright. Then prostrate until you are settled in prostration, then rise until you are settled sitting, then prostrate until you are settled in prostration, then rise. If you complete your prayer in this manner, it is complete; and whatever you fall short of from this, you are only diminishing from your prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1314)."},{"num":2051,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَقِيمُوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ بَعْدِي، وَرُبَّمَا قَالَ: مِنْ بَعْدِ ظَهْرِي إِذَا رَكَعْتُمْ وَسَجَدْتُمْ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (742)، ومسلم في الصلاة (425) كلاهما عن محمد بن بشار، ثنا محمد بن جعفر غندر، ثنا شعبة، قال: سمعتُ قتادة، عن أنس فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (742), Muslim (425)","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik reported that the Prophet ﷺ said: “Perfect your bowing and prostration, for by Allah, I see you behind me— and he sometimes said: behind my back—when you bow and prostrate.”"]}},"tuhfa":{},"full":1,"rep":[9645],"tks":"متفق عليه: رواه البخاري (742)، مسلم (425)."},{"num":2052,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ وَهْبٍ قَالَ: رَأَى حُذَيْفَةُ رَجُلًا لَا يُتِمُّ الرُّكُوعَ وَالسُّجُودَ، قَالَ: مَا صَلَّيْتَ، وَلَوْ مُتَّ مُتَّ عَلَى غَيْرِ الْفِطْرَةِ الَّتِي فَطَرَ اللَّهُ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهَا.","وَفِي رِوَايَةِ: وَلَوْ مُتَّ مُتَّ عَلَى غَيْرِ سُنَّةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في الأذان (791، 808) من الوجهين، عن حذيفة.","grade":"صحيح","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (791, 808)","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Hudhayfah saw a man who did not complete his bowing and prostration, and he said: “You have not prayed. If you were to die, you would die upon something other than the natural way upon which Allah created Muhammad ﷺ.” In another narration: “You would die upon something other than the Sunnah of Muhammad ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (791، 808)."},{"num":2053,"demo":false,"sanad":"","matn":["عَنْ إِسْحَاقَ بْنِ سَعِيدِ بْنِ عَمْرِو بْنِ سَعِيدِ بْنِ الْعَاصِ، حَدَّثَنِي أَبِي، عَنْ أَبِيهِ قَالَ: كُنْتُ عِنْدَ عُثْمَانَ فَدَعَا بِطَهُورٍ فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنِ امْرِئٍ مُسْلِمٍ تَحْضُرُهُ صَلَاةٌ مَكْتُوبَةٌ فَيُحْسِنُ وُضُوءَهَا، وَخُشُوعَهَا، وَرُكُوعَهَا، إِلَّا كَانَتْ كَفَّارَةً لِمَا قَبْلَهَا مِنَ الذُّنُوبِ، مَا لَمْ يُؤْتِ كَبِيرَةً، وَذَلِكَ الدَّهْرَ كُلَّهُ."],"takhrij":"صحيح: رواه مسلم في الطهارة (228)، عن عبد بن حُميد، وحجَّاج ابن الشاعر، كلاهما عن أبي الوليد، حدَّثنا إسحاق بن سعيد بن عمرو بن سعيد بن العاص، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (228)","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Ishaq ibn Sa‘id ibn ‘Amr ibn Sa‘id ibn al-‘As said: My father narrated to me from his father that he said: I was with ‘Uthman and he called for water for ablution, then said: I heard the Messenger of Allah ﷺ say: “No Muslim man is present for an obligatory prayer and perfects its ablution, its humility, and its bowing, except that it is an expiation for the sins before it—so long as he does not commit a major sin—and that is for all time.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (228)."},{"num":2054,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَسْتَفْتِحُ الصَّلَاةَ بِالتَّكْبِيرِ وَالْقِرَاءَةَ بِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَكَانَ إِذَا رَكَعَ لَمْ يُشْخِصْ رَأْسَهُ، وَلَمْ يُصَوِّبْهُ وَلَكِنْ بَيْنَ ذَلِكَ، وَكَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ لَمْ يَسْجُدْ حَتَّى يَسْتَوِيَ قَائِمًا، وَكَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ السَّجْدَةِ لَمْ يَسْجُدْ حَتَّى يَسْتَوِيَ جَالِسًا، وَكَانَ يَقُولُ فِي كُلِّ رَكْعَتَيْنِ: التَّحِيَّةَ، وَكَانَ يَفْرِشُ رِجْلَهُ الْيُسْرَى، وَيَنْصِبُ رِجْلَهُ الْيُمْنَى، وَكَانَ يَنْهَى عَنْ عُقْبَةِ الشَّيْطَانِ، وَيَنْهَى أَنْ يَفْتَرِشَ الرَّجُلُ ذِرَاعَيْهِ افْتِرَاشَ السَّبُعِ، وَكَانَ يَخْتِمُ الصَّلَاةَ بِالتَّسْلِيمِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (498) من طريق حسين المعلم، عن بُديل ابن ميسرة، عن أبي الجوزاء، عن عائشة فذكرتِ الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (498)","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ used to begin the prayer by saying “Allāhu akbar” and the recitation with “All praise is for Allah, Lord of all worlds.” When he bowed, he would not raise his head up nor drop it down; rather, he kept it between the two. When he raised his head from bowing, he would not go down into prostration until he stood upright. When he raised his head from prostration, he would not prostrate again until he sat upright. He would recite the tashahhud in every two units. He would spread his left foot (sit on it) and keep his right foot upright. He forbade the sitting called “the devil’s sitting,” and forbade a man from spreading his forearms like a beast. And he would conclude the prayer with the closing greetings."]},"buhuth":{"en":["“He did not raise his head nor drop it” means he did not lift it excessively nor lower it excessively; rather, he remained balanced. “The devil’s sitting” has been explained as the forbidden type of sitting in which a person presses his buttocks to the ground, keeps his shins upright, and places his hands on the ground."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (498)."},{"num":2055,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الْبَدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تُجْزِئُ صَلَاةُ الرَّجُلِ حَتَّى يُقِيمَ ظَهْرَهُ فِي الرُّكُوعِ وَالسُّجُودِ."],"takhrij":"صحيح: رواه أبو داود (855) والترمذي (265)، والنسائي (1027)، وابن ماجة (870) كلهم من طريق الأعمش، عن عُمارة بن عُمير، عن أبي معمر، عن أبي مسعود الأنصاري البدري فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (855), al-Tirmidhi (265), al-Nasa’i (1027), Ibn Majah (870) — al-Tirmidhi said: “Hasan Sahih”","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abu Mas‘ud al-Badri reported that the Messenger of Allah ﷺ said: “A person’s prayer is not sufficient until he straightens his back in bowing and prostration.” In another wording: “until a person straightens his spine in bowing and prostration.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (855)، الترمذي (265)، النسائي (1027)، ابن ماجه (870) — وقال الترمذي: «حسن صحيح»."},{"num":2056,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الْقَاسِمِ قَالَ: جَلَسْنَا إِلَى عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى فَقَالَ: أَلَا أُرِيكُمْ صَلَاةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: فَقُلْنَا: بَلَى. قَالَ: فَقَامَ فَكَبَّرَ، ثُمَّ قَرَأَ، ثُمَّ رَكَعَ فَوَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ حَتَّى أَخَذَ كُلُّ عُضْوٍ مَأْخَذَهُ، ثُمَّ رَفَعَ حَتَّى أَخَذَ كُلُّ عُضْوٍ مَأْخَذَهُ، ثُمَّ سَجَدَ حَتَّى أَخَذَ كُلُّ عُضْوٍ مَأْخَذَهُ، ثُمَّ رَفَعَ حَتَّى أَخَذَ كُلُّ عَظْمٍ مَأْخَذَهُ، ثُمَّ سَجَدَ حَتَّى أَخَذَ كُلُّ عَظْمٍ مَأْخَذَهُ، ثُمَّ رَفَعَ فَصَنَعَ فِي الرَّكْعَةِ الثَّانِيَةِ كَمَا صَنَعَ فِي الرَّكْعَةِ الْأُولَى، ثُمَّ قَالَ: هَكَذَا صَلَاةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه الإمام أحمد (15371) عن هَارُون بْن مَعْرُوفٍ، حَدَّثَنَا ضَمْرَةُ، عَنِ ابْنِ شَوْذَبَ، عَنْ عَبْدِ اللَّهِ بْنِ الْقَاسِمِ قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (15371)","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn al-Qasim said: We sat with ‘Abd al-Rahman ibn Abza and he said: “Shall I show you the prayer of the Messenger of Allah ﷺ?” We said: “Yes.” He stood and said “Allāhu akbar”, then recited. Then he bowed and placed his hands on his knees until every limb settled into its proper position. Then he rose until every limb settled into its proper position. Then he prostrated until every limb settled into its proper position. Then he rose until every bone returned to its proper place. Then he prostrated until every bone returned to its proper place. Then he rose, and he did in the second unit as he did in the first. Then he said: “This is the prayer of the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15371)."},{"num":2057,"demo":false,"sanad":"","matn":["عَنْ سَالِمٍ الْبَرَّادِ قَالَ: أَتَيْنَا عُقْبَةَ بْنَ عَمْرٍو الْأَنْصَارِيَّ أَبَا مَسْعُود فَقُلْنَا لَهُ: حَدِّثْنَا عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ بَيْنَ أَيْدِينَا فِي الْمَسْجِدِ فَكَبَّرَ، فَلَمَّا رَكَعَ وَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ وَجَعَلَ أَصَابِعَهُ أَسْفَلَ مِنْ ذَلِكَ وَجَافَى بَيْنَ مِرْفَقَيْهِ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ، ثُمَّ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَقَامَ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ، ثُمَّ كَبَّرَ وَسَجَدَ وَوَضَعَ كَفَّيْهِ عَلَى الْأَرْضِ، ثُمَّ جَافَى بَيْنَ مِرْفَقَيْهِ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ، ثُمَّ رَفَعَ رَأْسَهُ فَجَلَسَ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ، فَفَعَلَ مِثْلَ ذَلِكَ أَيْضًا، ثُمَّ صَلَّى أَرْبَعَ رَكَعَاتٍ مِثْلَ هَذِهِ الرَّكْعَةِ فَصَلَّى صَلَاتَهُ. ثُمَّ قَالَ: هَكَذَا رَأَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي."],"takhrij":"حسن: رواه أبو داود (863) عن زهير بن حرب، حدثنا جرير، عن عطاء بن السائب، عن سالم البرَّاد، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (863); al-Nasa’i (1037); Ahmad (17081)","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Salim al-Barrad said: We came to ‘Uqbah ibn ‘Amr al-Ansari, Abu Mas‘ud, and said: “Tell us about the prayer of the Messenger of Allah ﷺ.” He stood in front of us in the mosque and said “Allāhu akbar”. When he bowed, he placed his hands on his knees and let his fingers extend below that, and he kept his elbows away from his sides until everything in him settled. Then he said: “Allah hears the one who praises Him,” and he stood until everything in him settled. Then he said “Allāhu akbar” and prostrated, placed his palms on the ground, and kept his elbows away from his sides until everything in him settled. Then he raised his head and sat until everything in him settled. He did the same again. Then he prayed four units like this unit, completing his prayer, then said: “This is how we saw the Messenger of Allah ﷺ pray.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (863)، النسائي (1037)، أحمد (17081)."},{"num":2058,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ شَيْبَانَ، وَكَانَ مِنَ الْوَفْدِ قَالَ: خَرَجْنَا حَتَّى قَدِمْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعْنَاهُ، وَصَلَّيْنَا خَلْفَهُ، فَلَمَحَ بِمُؤْخِرِ عَيْنِهِ رَجُلًا لَا يُقِيمُ صَلَاتَهُ، يَعْنِي صُلْبَهُ فِي الرُّكُوعِ وَالسُّجُودِ، فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّلَاةَ قَالَ: يَا مَعْشَرَ الْمُسْلِمِينَ لَا صَلَاةَ لِمَنْ لَا يُقِيمُ صُلْبَهُ فِي الرُّكُوعِ وَالسُّجُودِ."],"takhrij":"صحيح: أخرجه ابن ماجة (871) عن أبي بكر بن أبي شيبة، قال: حدثنا ملازم بن عمرو، عن عبدالله بن بدر، قال: أخبرني عبدالرحمن بن علي بن شيبان، عن أبيه علي بن شيبان فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (871). Also authenticated by Ibn Khuzaymah (593) and Ibn Hibban (1891)","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["‘Ali ibn Shayban, who was part of a delegation, said: We came to the Messenger of Allah ﷺ, pledged allegiance to him, and prayed behind him. He noticed, out of the corner of his eye, a man who did not straighten his prayer—meaning his spine in bowing and prostration. When the Prophet ﷺ finished, he said: “O community of Muslims, there is no prayer for the one who does not straighten his spine in bowing and prostration.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (871)، وصححه أيضا ابن خزيمة (593)، وابن حبان (1891)."},{"num":2059,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ قَالَ: سَمِعْتُهُ وَهُوَ فِي عَشَرَةٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَحَدُهُمْ أَبُو قَتَادَةَ بْنُ رِبْعِيٍّ يَقُولُ: أَنَا أَعْلَمُكُمْ بِصَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالُوا: مَا كُنْتَ أَقْدَمَنَا لَهُ صُحْبَةً وَلَا أَكْثَرَنَا لَهُ إِتْيَانًا، قَالَ: بَلَى، قَالُوا: فَاعْرِضْ، فَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ إِلَى الصَّلَاةِ اعْتَدَلَ قَائِمًا وَرَفَعَ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا مَنْكِبَيْهِ، فَإِذَا أَرَادَ أَنْ يَرْكَعَ رَفَعَ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا مَنْكِبَيْهِ، ثُمَّ قَالَ: اللَّهُ أَكْبَرُ، وَرَكَعَ ثُمَّ اعْتَدَلَ فَلَمْ يُصَوِّبْ رَأْسَهُ وَلَمْ يُقْنِعْ، وَوَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ، ثُمَّ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، وَرَفَعَ يَدَيْهِ وَاعْتَدَلَ حَتَّى يَرْجِعَ كُلُّ عَظْمٍ فِي مَوْضِعِهِ مُعْتَدِلًا، ثُمَّ أَهْوَى إِلَى الْأَرْضِ سَاجِدًا، ثُمَّ قَالَ: اللَّهُ أَكْبَرُ، ثُمَّ جَافَى عَضُدَيْهِ عَنْ إِبْطَيْهِ وَفَتَخَ أَصَابِعَ رِجْلَيْهِ ثُمَّ ثَنَى رِجْلَهُ الْيُسْرَى وَقَعَدَ عَلَيْهَا، ثُمَّ اعْتَدَلَ حَتَّى يَرْجِعَ كُلُّ عَظْمٍ فِي مَوْضِعِهِ مُعْتَدِلًا، ثُمَّ أَهْوَى سَاجِدًا، ثُمَّ قَالَ: اللَّهُ أَكْبَرُ، ثُمَّ ثَنَى رِجْلَهُ وَقَعَدَ وَاعْتَدَلَ حَتَّى يَرْجِعَ كُلُّ عَظْمٍ فِي مَوْضِعِهِ، ثُمَّ نَهَضَ ثُمَّ صَنَعَ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ حَتَّى إِذَا قَامَ مِنَ السَّجْدَتَيْنِ كَبَّرَ وَرَفَعَ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا مَنْكِبَيْهِ كَمَا صَنَعَ حِينَ افْتَتَحَ الصَّلَاةَ، ثُمَّ صَنَعَ كَذَلِكَ حَتَّى كَانَتِ الرَّكْعَةُ الَّتِي تَنْقَضِي فِيهَا صَلَاتُهُ أَخَّرَ رِجْلَهُ الْيُسْرَى، وَقَعَدَ عَلَى شِقِّهِ مُتَوَرِّكًا ثُمَّ سَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (963)، والترمذي (304)، والنسائي (1039)، وابن ماجة (862) كلهم من طرق عن عبدالحميد بن جعفر، ثنا محمد بن عمرو بن عطاء، عن أبي حُميد السّاعدي فذكر الحديث، واللفظ للترمذي وقال: حسن صحيح، ولفظ النسائي مختصر، وسبق ذكر الحديث في باب رفع اليدين في الصلاة. وصحَّحه ابن حبان (1870).","grade":"صحيح","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good and authentic: Narrated by Abū Dāwūd (963) and al-Tirmidhī (304).","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abū Ḥumayd al-Sāʿidī, while among ten of the Companions of the Prophet ﷺ, among them Abū Qatādah al-Ḥārith ibn Ribʿī, said: “I know the prayer of the Messenger of Allah ﷺ better than you.” They said: “Why? You were neither the one among us who followed him most nor the earliest of us in companionship with him.” He said: “Indeed.” They said: “Then present it to us.” He said: When the Messenger of Allah ﷺ stood for prayer, he stood upright and raised his hands until they were level with his shoulders. When he intended to bow, he raised his hands until they were level with his shoulders, then said: “Allah is the Greatest.” He bowed and kept himself balanced, neither lowering his head nor raising it, and placed his hands upon his knees. Then he said: “Allah hears the one who praises Him.” He raised his hands and stood upright until every bone returned properly to its place. Then he went down to the ground in prostration and said: “Allah is the Greatest.” He kept his upper arms away from his sides and spread the toes of his feet. Then he bent his left leg and sat upon it, and sat upright until every bone returned properly to its place. Then he went down in prostration and said: “Allah is the Greatest.” Then he bent his leg, sat, and straightened himself until every bone returned to its place, then he stood up. He did the same in the second rakʿah. When he stood after the two prostrations, he said the takbīr and raised his hands until they were level with his shoulders, just as he had done when beginning the prayer. He continued in that manner until he reached the rakʿah in which his prayer would end. Then he moved his left leg aside and sat upon his left side in the tawarruk position, then gave the salām."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (963)، والترمذي (304)."},{"num":2060,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: جَاءَ رَجُلٌ مِنَ الأَنْصَارِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ كَلِمَاتٌ أَسْأَلُ عَنْهُنَّ. قَالَ: اجْلِسْ. وَجَاءَ رَجُلٌ مِنْ ثَقِيفٍ فَقَالَ: يَا رَسُولَ اللَّهِ كَلِمَاتٌ أَسْأَلُ عَنْهُنَّ. فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَبَقَكَ الأَنْصَارِيُّ. فَقَالَ الأَنْصَارِيُّ: إِنَّهُ رَجُلٌ غَرِيبٌ وَإِنَّ لِلْغَرِيبِ حَقًّا فَابْدَأْ بِهِ . فَأَقْبَلَ عَلَى الثَّقَفِيِّ فَقَالَ: إِنْ شِئْتَ أَجَبْتُكَ عَمَّا كُنْتَ تَسْأَلُ، وَإِنْ شِئْتَ سَأَلْتَنِي وَأُخْبِرْكَ. فَقَالَ: يَا رَسُولَ اللَّهِ بَلْ أَجِبْنِي عَمَّا كُنْتُ أَسْأَلُكَ قَالَ: جِئْتَ تَسْأَلُنِي عَنِ الرُّكُوعِ وَالسُّجُودِ وَالصَّلاةِ وَالصَّوْمِ. فَقَالَ: لا وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَخْطَأْتَ مِمَّا كَانَ فِي نَفْسِي شَيْئًا قَالَ: فَإِذَا رَكَعْتَ فَضَعْ رَاحَتَيْكَ عَلَى رُكْبَتَيْكَ، ثُمَّ فَرِّجْ بَيْنَ أَصَابِعِكَ، ثُمَّ أَمْكُثْ حَتَّى يَأْخُذَ كُلُّ عُضْوٍ مَأْخَذَهُ، وَإِذَا سَجَدْتَ فَمَكِّنْ جَبْهَتَكَ وَلا تَنْقُرُ نَقْرًا، وَصَلِّ أَوَّلَ النَّهَارِ وَآخِرَهُ. فَقَالَ: يَا نَبِيَّ اللَّهِ، فَإِنْ أَنَا صَلَّيْتُ بَيْنَهُمَا ؟ قَالَ: فَأَنْتَ إِذًا مُصَلٍّ... (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"حسن: رواه ابن حبان (1887)، والبيهقي في دلائل النبوة (6/294)، والبزار ـ كشف الأستار (1082) كلهم من حديث يحيى بن عبدالرحمن الأرحبي، حدثني عبيدة بن الأسود، عن القاسم بن الوليد، عن سنان بن الحارث بن مصرف، عن طلحة بن مصرف، عن مجاهد، عن ابن عمر، فذكر حديثاً طويلاً، وهذا جزء منه.","grade":"حسن","chapter_ar":"باب ما جاء من الخشوع في الصلاة والإقبال عليها والاعتدال في الركوع والسجود والتورك في الجلوس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Ḥibbān (1887).","chapter_en":"Humility in prayer, attentiveness, balance in bowing and prostration, and sitting with tawarruk","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Umar said: A man from the Ansar came to the Prophet ﷺ and said: “O Messenger of Allah, I have some words to ask about.” He said: “Sit.” Then a man from Thaqif came and said: “O Messenger of Allah, I have some words to ask about.” He said: “The Ansari came before you.” The Ansari said: “He is a stranger, and a stranger has a right, so begin with him.” So he turned to the Thaqafi and said: “If you wish, I will answer what you were going to ask; and if you wish, you may ask me and I will inform you.” He said: “Rather, answer what I was going to ask.” He said: “You came to ask me about bowing, prostration, prayer, and fasting.” He said: “No, by the One who sent you with the truth—you have not missed anything that was in my mind.” He said: “When you bow, place your palms on your knees, spread your fingers, and remain until every limb settles into its proper place. When you prostrate, place your forehead firmly and do not peck like a bird. Pray at the beginning of the day and at its end.” He said: “O Prophet of Allah, what if I pray between them?” He said: “Then you are (indeed) a person who prays.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (1887)."},{"num":2061,"demo":false,"sanad":"","matn":["عَنْ أَبِي عَبْدِ اللَّهِ الأَشْعَرِيِّ قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَصْحَابِهِ ثُمَّ جَلَسَ فِي طَائِفَةٍ مِنْهُمْ، فَدَخَلَ رَجُلٌ فَقَامَ يُصَلِّي فَجَعَلَ يَرْكَعُ وَيَنْقُرُ فِي سُجُودِهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَتَرَوْنَ هَذَا، مَنْ مَاتَ عَلَى هَذَا مَاتَ عَلَى غَيْرِ مِلَّةِ مُحَمَّدٍ يَنْقُرُ صَلاتَهُ كَمَا يَنْقُرُ الْغُرَابُ الدَّمَ، إِنَّمَا مَثَلُ الَّذِي يَرْكَعُ وَيَنْقُرُ فِي سُجُودِهِ كَالْجَائِعِ لا يَأْكُلُ إِلا التَّمْرَةَ وَالتَّمْرَتَيْنِ، فَمَاذَا تُغْنِيَانِ عَنْهُ، فَأَسْبِغُوا الْوُضُوءَ، وَيْلٌ لِلأَعْقَابِ مِنَ النَّارِ، أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ.","قَالَ أَبُو صَالِحٍ: فَقُلْتُ لأَبِي عَبْدِ اللَّهِ الأَشْعَرِيِّ: مَنْ حَدَّثَكَ بِهَذَا الْحَدِيثِ ؟ فَقَالَ: أُمَرَاءُ الأَجْنَادِ عَمْرُو ابْنُ الْعَاصِ، وَخَالِدُ بْنُ الْوَلِيدِ، وَيَزِيدُ بْنُ أَبِي سُفْيَانَ، وَشُرَحْبِيلُ بْنُ حَسَنَةَ، كُلُّ هَؤُلاءِ سَمِعُوهُ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه ابن خزيمة (665) عن إسماعيل بن إسحاق، حدّثنا صفوان بن صالح، حدّثنا الوليد بن مسلم، حدّثنا شيبة بن الأحنف الأوزاعي، حدّثنا أبو سلام الأسود، نا أبو صالح الأشعري، عن أبي عبدالله الأشعريّ، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن نقرة الغراب والديك في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Khuzaymah (665)","chapter_en":"Prohibition of pecking like a crow or a rooster in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abu ‘Abdullah al-Ash‘ari said: The Messenger of Allah ﷺ prayed with his Companions, then sat with a group of them. A man entered and began praying, bowing and “pecking” in his prostration. The Prophet ﷺ said: “Do you see this one? Whoever dies upon this dies upon other than the religion of Muhammad—he pecks at his prayer the way a crow pecks at blood. The one who bows and pecks in his prostration is like a hungry person who eats only one or two dates—what will they benefit him? Perfect your ablution. Woe to the heels from the Fire. Complete the bowing and prostration.” Abu Salih said: I asked Abu ‘Abdullah al-Ash‘ari: “Who narrated this hadith to you?” He said: The commanders of the armies: ‘Amr ibn al-‘As, Khalid ibn al-Walid, Yazid ibn Abi Sufyan, and Shurahbil ibn Hasanah—each of them heard it from the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (665)."},{"num":2062,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أَمَرَنِي رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثٍ وَنَهَانِي عَنْ ثَلَاثٍ، أَمَرَنِي بِصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَأَنْ لَا أَنَامَ إِلَّا عَلَى وِتْرٍ، وَرَكْعَتَيِ الضُّحَى، وَنَهَانِي عَنِ الِالْتِفَاتِ فِي الصَّلَاةِ الْتِفَاتَ الثَّعْلَبِ، وَأُقْعِي إِقْعَاءَ الْقِرْدِ، وَأَنْقُرُ نَقْرَ الدِّيكِ."],"takhrij":"حسن: رواه البيهقي (2741) من طريق ليث، عن مجاهد، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن نقرة الغراب والديك في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (7595), Abū Dāwūd al-Ṭayālisī (2716).","chapter_en":"Prohibition of pecking like a crow or a rooster in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ commanded me with three things and forbade me from three things. He commanded me to fast three days of every month, not to sleep except after praying an odd-numbered prayer, and to pray the two units of mid-morning prayer. And he forbade me from turning in prayer like a fox, sitting in the crouch of a monkey, and pecking like a rooster."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (7595)، وأبو داود الطيالسي (2716)."},{"num":2063,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَسْوَأُ النَّاسِ سَرَقَةً الَّذِي يَسْرِقُ صَلاتَهُ. قَالَ: وَكَيْفَ يَسْرِقُ صَلاتَهُ ؟ قَالَ: لا يُتِمُّ رُكُوعَهَا، وَلا سُجُودَهَا."],"takhrij":"حسن: رواه ابن حبان (1888)، والحاكم (841)، والبيهقي (3997) كلهم من حديث هشام بن عمار، قال: حدثنا عبدالحميد بن أبي العشرين، عن الأوزاعي، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن نقرة الغراب والديك في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Ḥibbān (1888).","chapter_en":"Prohibition of pecking like a crow or a rooster in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The worst of people in theft is the one who steals from his prayer.” He said: “And how does he steal from his prayer?” He said: “He does not complete its bowing or its prostration.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (1888)."},{"num":2064,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ شِبْلٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَنْهَى عَنْ ثَلَاثِ خِصَالٍ فِي الصَّلَاةِ: عَنْ نَقْرَةِ الْغُرَابِ، وَعَنِ افْتِرَاشِ السَّبُعِ، وَأَنْ يُوطِنَ الرَّجُلُ الْمَكَانَ كَمَا يُوطِنُ الْبَعِيرُ."],"takhrij":"حسن: رواه أبو داود (862)، والنسائي (1112)، وابن ماجه (1429)، وصححه ابن خزيمة (662)، وابن حبان (2277)، والحاكم (833)، والبيهقي (2727, 2728) كلهم من حديث جعفر بن عبدالله، أن تميم ابن محمود أخبره، أن عبدالرحمن بن شِبْل أخبره فذكر الحديث.","grade":"حسن","chapter_ar":"باب النهي عن نقرة الغراب والديك في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (862), al-Nasa’i (1112), Ibn Majah (1429), and Ibn Khuzaymah authenticated it (662)","chapter_en":"Prohibition of pecking like a crow or a rooster in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["‘Abd al-Rahman ibn Shibl said: I heard the Messenger of Allah ﷺ forbid three things: pecking like a crow, spreading one’s forearms like a beast, and that a man fix a specific spot (in the mosque) for himself the way a camel fixes a place for itself."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (862)، النسائي (1112)، ابن ماجه (1429)، وصححه ابن خزيمة (662)."},{"num":2065,"demo":false,"sanad":"","matn":["عَنِ ابْنِ أَبِي أَوْفَى قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ ظَهْرَهُ مِنَ الرُّكُوعِ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَاوَاتِ، وَمِلْءَ الأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (476: 202) عن أبي بكر بن أبي شيبة، حدثنا أبو معاوية ووكيع، عن الأعمش، عن عبيد بن الحسن، عن ابن أبي أوفى قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (476/202)","chapter_en":"What to say when raising the head from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Ibn Abi Awfa said: When the Messenger of Allah ﷺ raised his back from bowing, he would say: “Allah hears the one who praises Him. O Allah, our Lord, to You belongs all praise—filling the heavens, filling the earth, and filling whatever You will of anything thereafter.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (476: 202)."},{"num":2066,"demo":false,"sanad":"","matn":["عَنِ عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَقُولُ: اللَّهُمَّ لَكَ الْحَمْدُ، مِلْءَ السَّمَاء وَمِلْءَ الأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، اللَّهُمَّ طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ، اللَّهُمَّ طَهِّرْنِي مِنَ الذُّنُوبِ وَالْخَطَايَا، كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الْوَسَخِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (476: 204) عن محمد بن المثنى وابن بشار، حدثنا محمد بن جعفر، حدثنا شعبة، عن مَجْزأة بن زاهر، عن عبدالله بن أبي أوفى، فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (476/204)","chapter_en":"What to say when raising the head from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["‘Abdullah ibn Abi Awfa reported from the Prophet ﷺ that he used to say: “O Allah, to You belongs all praise—filling the heaven, filling the earth, and filling whatever You will of anything thereafter. O Allah, purify me with snow, hail, and cold water. O Allah, cleanse me of sins and mistakes as a white garment is cleansed of dirt.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (476: 204)."},{"num":2067,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ، قَالَ: رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَاوَاتِ وَالأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ: وَكُلُّنَا لَكَ عَبْدٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ."],"takhrij":"صحيح: رواه مسلم في الصلاة (477) عن عبدالله بن عبدالرحمن الدارمي، أخبرنا مروان بن محمد الدمشقي، حدثنا سعيد بن عبد العزيز، عن عطية بن قيس، عن قَزْعة، عن أبي سعيد الخدري فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (477)","chapter_en":"What to say when raising the head from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: When the Messenger of Allah ﷺ raised his head from bowing, he would say: “Our Lord, to You belongs all praise—filling the heavens and the earth, and filling whatever You will of anything thereafter. You are worthy of praise and glory. The truest thing a servant can say—and we are all Your servants: O Allah, none can withhold what You give, none can give what You withhold, and the wealth or status of a person will not benefit him against You.”"]}},"tuhfa":{},"full":1,"rep":[11008,13129],"tks":"صحيح: رواه مسلم (477)."},{"num":2068,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَوَاتِ، وَمِلْءَ الأَرْضِ وَمَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ، لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ."],"takhrij":"صحيح: رواه مسلم في الصلاة (478) عن أبي بكر بن أبي شيبة، حدثنا هُشيم بن بَشير، أخبرنا هشامُ بن حسَّان، عن قيس بن سعد، عن عطاء، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (478)","chapter_en":"What to say when raising the head from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Ibn ‘Abbas reported that when the Prophet ﷺ raised his head from bowing, he would say: “O Allah, our Lord, to You belongs all praise—filling the heavens, filling the earth, and what is between them, and filling whatever You will of anything thereafter. You are worthy of praise and glory. None can withhold what You give, none can give what You withhold, and the wealth or status of a person will not benefit him against You.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (478)."},{"num":2069,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: كَانَ رَسُولُ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ."],"takhrij":"صحيح: رواه الترمذي (266) عن محمود بن غيلان، حدثنا أبو داود الطيالسي، حدثنا عبد العزيز بن عبدالله بن أبي سلمة الماجشون، حدثني عَمِّي، عن عبدالرحمن بن الأعرج، عن عبيدالله بن أبي رافع، عن علي بن أبي طالب فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Tirmidhi (266) — he said: “Hasan Sahih”","chapter_en":"What to say when raising the head from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: When the Messenger of Allah ﷺ raised his head from bowing, he would say: “Allah hears the one who praises Him. Our Lord, and to You belongs all praise—filling the heavens, filling the earth, what is between them, and filling whatever You will of anything thereafter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (266) — وقال: «حسن صحيح»."},{"num":2070,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: رَبَّنَا وَلَكَ الْحَمْدُ."],"takhrij":"صحيح: رواه أحمد (6346) عن عبدالرزاق، وهو في المصنف (2911)، حدثنا معمر، عن الزهري، عن سالم، عن ابن عمر فذكر مثله، وهذا الحديث جزء من الحديث الذي سبق ذكره في باب رفع اليدين عند الركوع وعند الرفع من الركوع.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (6346), from ‘Abd al-Razzaq (also in al-Musannaf 2911)","chapter_en":"What to say when raising the head from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said that he heard the Messenger of Allah ﷺ, when he raised his head from bowing, say: “Our Lord, and to You belongs all praise.”"]}},"tuhfa":{},"full":1,"rep":[11011],"tks":"صحيح: رواه أحمد (6346) عن عبد الرزاق، وهو في المصنف (2911)."},{"num":2071,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قال: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ."],"takhrij":"صحيح: رواه النسائي (1060) عن إسحاق بن إبراهيم، عن عبد الرزاق، وهو في المصنف (2912)، عن معمر، عن الزهري، عن أبي سلمة بن عبدالرحمن، عن أبي هريرة فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (1060); ‘Abd al-Razzaq (in al-Musannaf 2912)","chapter_en":"What to say when raising the head from bowing","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: When the Messenger of Allah ﷺ raised his head from bowing, he would say: “O Allah, our Lord, and to You belongs all praise.”"]}},"tuhfa":{},"full":1,"rep":[11014],"tks":"صحيح: رواه النسائي (1060)، عبد الرزاق (في المصنف 2912)."},{"num":2072,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا قَالَ: الْإِمَامُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (47) عن سُمَيٍّ مولى أبي بكر، عن أبي صالح السَمَّان، عن أبي هريرة فذكر الحديث، ومن طريقه البخاري في الأذان (796)، ومسلم في الصلاة (409) وقال: عن سُهيل، عن أبيه، عن أبي هريرة، عن النبي صلى الله عليه وسلم بمعنى حديث سُمي.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قول الإمام: «سمع الله لمن حمده»","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (47), al-Bukhari (796), Muslim (409)","chapter_en":"What has been narrated about the imam saying: “Allah hears the one who praises Him.”","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When the imam says: ‘Allah hears the one who praises Him,’ then say: ‘O Allah, our Lord, to You belongs all praise.’ Whoever’s saying matches the saying of the angels will have his past sins forgiven.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (47)، البخاري (796)، مسلم (409)."},{"num":2073,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ بْنِ رَافِعٍ أَنَّهُ قَالَ: كُنَّا يَوْمًا نُصَلِّي وَرَاءَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا رَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأْسَهُ مِنَ الرَّكْعَةِ، وَقَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، قَالَ رَجُلٌ وَرَاءَهُ: رَبَّنَا وَلَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: مَنِ الْمُتَكَلِّمُ آنِفًا، فَقَالَ الرَّجُلُ: أَنَا يَا رَسُولَ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ رَأَيْتُ بِضْعَةً وَثَلَاثِينَ مَلَكًا يَبْتَدِرُونَهَا أَيُّهُمْ يَكْتُبُهُنَّ أَوَّلُ."],"takhrij":"صحيح: رواه مالك في القرآن (25) عن نُعيم بن عبدالله المجمر، عن علي بن يحيى الزرقي، عن أبيه، عن رفاعة بن رافع فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في قول الإمام: «سمع الله لمن حمده»","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (25), al-Bukhari (799)","chapter_en":"What has been narrated about the imam saying: “Allah hears the one who praises Him.”","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Rifa‘ah ibn Rafi‘ al-Zuraqi said: We were praying one day behind the Messenger of Allah ﷺ. When he raised his head from bowing he said: “Allah hears the one who praises Him.” A man behind him said: “Our Lord, and to You belongs all praise—abundant, pure, and blessed.” When the Prophet ﷺ finished, he said: “Who spoke just now?” The man said: “I did.” He said: “I saw more than thirty angels rushing to it—each of them wanting to be the first to write it down.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (25)، البخاري (799)."},{"num":2074,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ يَقُولُ: سَقَطَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ فَرَسٍ فَجُحِشَ شِقُّهُ الأَيْمَنُ، فَدَخَلْنَا عَلَيْهِ نَعُودُهُ، فَحَضَرَتِ الصَّلَاةُ، فَصَلَّى بِنَا قَاعِدًا، فَصَلَّيْنَا وَرَاءَهُ قُعُودًا، فَلَمَّا قَضَى الصَّلَاةَ قَالَ: إِنَّمَا جُعِلَ الإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا سَجَدَ فَاسْجُدُوا، وَإِذَا رَفَعَ فَارْفَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَقُولُوا: رَبَّنَا وَلَكَ الْحَمْدُ، وَإِذَا صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا أَجْمَعُون."],"takhrij":"متفق عليه: رواه مسلم في الصلاة (411) من طريق سفيان بن عيينة، عن الزهري، قال: سمعتُ أنس بن مالك يقول: فذكر الحديث، ورواه البخاري في الأذان (805) من طريق سفيان قال غير مرة عن الزهري، قال: سمعت أنس بن مالك فذكر الحديث نحوه،وستأتي بقية الأحاديث في متابعة الإمام، وانظر حديث أبي هريرة في باب التأمين.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قول الإمام: «سمع الله لمن حمده»","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMuslim (411), al-Bukhari (805)","chapter_en":"What has been narrated about the imam saying: “Allah hears the one who praises Him.”","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ fell from a horse and his right side was injured. We came to visit him, and when prayer time came he led us seated, and we prayed seated behind him. When he finished, he said: “The imam has only been appointed to be followed. When he says “Allāhu akbar,” then say “Allāhu akbar”; when he prostrates, prostrate; when he rises, rise; when he says, ‘Allah hears the one who praises Him,’ then say: ‘Our Lord, and to You belongs all praise.’ And if he prays seated, then pray seated, all of you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (411)، البخاري (805)."},{"num":2075,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّهُ كَانَ يَضَعُ يَدَيْهِ قَبْلَ رُكْبَتَيْهِ، وَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ ذَلِكَ."],"takhrij":"صحيح: رواه ابن خزيمة (627)، والدارقطني (1303)، والحاكم (821)، وعنه البيهقي (2638)، والطحاوي في شرحه (1/254)، كلهم من طرق عن عبد العزيز بن محمد الدراوردي، عن عبيدالله بن عمر، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الخرور إلى السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Khuzaymah (627), al-Dāraquṭnī (1303), al-Ḥākim (917), and al-Bayhaqī (2/100).","chapter_en":"Going down into prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar ibn al-Khattab used to place his hands down before his knees, and he said: The Messenger of Allah ﷺ used to do that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (627)، والدارقطني (1303)، والحاكم (821)، والبيهقي (2638)."},{"num":2076,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا سَجَدَ أَحَدُكُمْ فَلَا يَبْرُكْ كَمَا يَبْرُكُ الْبَعِيرُ وَلْيَضَعْ يَدَيْهِ قَبْلَ رُكْبَتَيْهِ."],"takhrij":"صحيح: رواه أبو داود (840)، والنسائي (1091)، وأحمد (8955)، والدارقطني (1304,1305)، والبيهقي (2633) كلهم من طرق عن عبد العزيز بن محمد الدراوردي، عن محمد بن عبدالله بن الحسن، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الخرور إلى السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (840). Also narrated by al-Nasa’i (1091), Ahmad (8955), al-Daraqutni, and al-Bayhaqi (2/99). It is also reported via other routes: Abu Dawud (841), al-Nasa’i (1090), al-Tirmidhi (269).","chapter_en":"Going down into prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When one of you prostrates, let him not go down the way a camel goes down. Let him place his hands before his knees.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (840)، ورواه أيضا النسائي (1091)، أحمد (8955)، الدارقطني، والبيهقي (2633)، وروي أيضا من طرق أخرى: أبو داود (841)، النسائي (1090)، الترمذي (269)."},{"num":2077,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اعْتَدِلُوا فِي السُّجُودِ، وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ انْبِسَاطَ الْكَلْبِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (822)، ومسلم في الصلاة (493) كلاهما من طريق محمد بن جعفر، عن شعبة، قال: سمعتُ قتادة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب الاعتدال في السجود والنهي عن افتراش الذراعين افتراش الكلب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (822), Muslim (493)","chapter_en":"Being balanced in prostration and prohibition of spreading the forearms like a dog","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ said: “Be balanced in prostration, and let none of you spread his forearms like the spreading of a dog.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (822)، مسلم (493)."},{"num":2078,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ بِأَنْ يُعْتَدَلَ فِي السُّجُودِ، وَلَا يَسْجُدَ الرَّجُلُ بَاسِطًا ذِرَاعَيْهِ كَالْكَلْبِ."],"takhrij":"حسن: رواه عبدالرزاق (2929، 2930) من وجهين أحدهما عن ابن جريج، عن سليمان بن موسى، أن جابر بن عبدالله قال فذكر الحديث كما سبق، والوجه الثاني: عن الثوري، عن الأعمش، عن أبي سفيان، عن جابر قال: قال رسول الله صلى الله عليه وسلم: إذا سجد أحدكم فليعتدل، ولا يفترش ذارعيه افتراش الكلب.","grade":"حسن","chapter_ar":"باب الاعتدال في السجود والنهي عن افتراش الذراعين افتراش الكلب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\n‘Abd al-Razzaq (2929, 2930) and he has wording: “When one of you prostrates, be balanced and do not spread your forearms like a dog.”","chapter_en":"Being balanced in prostration and prohibition of spreading the forearms like a dog","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I heard the Prophet ﷺ command that one be balanced in prostration, and that a man should not prostrate while spreading his forearms like a dog."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الرزاق (2929، 2930)، وله لفظ: «إذا سجد أحدكم فليعتدل، ولا يفترش ذراعيه افتراش الكلب»."},{"num":2079,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَانَا أَنْ يَفْتَرِشَ أَحَدُنَا ذِرَاعَيْهِ افْتِرَاشَ السَّبُعِ."],"takhrij":"صحيح: أخرجه عبد الرزاق (3039) عن عثمان بن مطر، عن حسين، عن بُديل العقيلي، عن أبي الجوزاء، عن عائشة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب الاعتدال في السجود والنهي عن افتراش الذراعين افتراش الكلب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\n‘Abd al-Razzaq (2938), Muslim (498)","chapter_en":"Being balanced in prostration and prohibition of spreading the forearms like a dog","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["The Mother of the Believers ‘A’ishah said: The Messenger of Allah ﷺ used to forbid us from spreading our forearms like the spreading of a dog or a wild beast."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه عبد الرزاق (3039)، مسلم (498)."},{"num":2080,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَالِكٍ ابْنِ بُحَيْنَةَ أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا صَلَّى فَرَّجَ بَيْنَ يَدَيْهِ حَتَّى يَبْدُوَ بَيَاضُ إِبْطَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (390)، ومسلم في الصلاة (495) كلاهما من طريق بكر بن مُضر، عن جعفر بن ربيعة، عن الأعرج، عن عبدالله بن مالك بن بحينة فذكره.","grade":"متفق عليه","chapter_ar":"باب التجافي في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (390), Muslim (495)","chapter_en":"Keeping the arms away from the sides in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["‘Abdullah ibn Malik ibn Buhaynah reported that when the Prophet ﷺ prayed, he would separate his arms so that the whiteness of his armpits could be seen."]},"buhuth":{"en":["In a narration in Muslim: “When he prostrated, he would keep his arms away from his sides in prostration until the whiteness of his armpits was seen.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (390)، مسلم (495)."},{"num":2081,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا سَجَدْتَ، فَضَعْ كَفَّيْكَ، وَارْفَعْ مِرْفَقَيْكَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (494) عن يحيى بن يحيى قال: أخبرنا عبيدالله بن إياد، عن إياد، عن البراء فذكره.","grade":"صحيح","chapter_ar":"باب التجافي في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (494)","chapter_en":"Keeping the arms away from the sides in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Al-Bara’ reported that the Messenger of Allah ﷺ said: “When you prostrate, place your palms and lift your elbows.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (494)."},{"num":2082,"demo":false,"sanad":"","matn":["عَنْ أَبِي إِسْحَاقَ قَالَ: وَصَفَ لَنَا الْبَرَاءُ بْنُ عَازِبٍ فَوَضَعَ يَدَيْهِ، وَاعْتَمَدَ عَلَى رُكْبَتَيْهِ، وَرَفَعَ عَجِيزَتَهُ، وَقَالَ: هَكَذَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْجُدُ."],"takhrij":"حسن: رواه أبو داود (896)، والنسائي (1104) كلاهما من حديث شريك، عن أبي إسحاق، فذكره.","grade":"حسن","chapter_ar":"باب التجافي في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (896), al-Nasa’i (1104–1105), Ibn Khuzaymah (646–647), Ahmad (18701)","chapter_en":"Keeping the arms away from the sides in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Abu Ishaq said: Al-Bara’ ibn ‘Azib described it for us: he placed his hands, leaned on his knees, raised his hips, and said: “This is how the Messenger of Allah ﷺ used to prostrate.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (896)، النسائي (1104–1105)، ابن خزيمة (646–647)، أحمد (18701)."},{"num":2083,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ بِنْتِ الْحَارِثِ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا سَجَدَ، لَوْ شَاءَتْ بَهْمَةٌ، أَنْ تَمُرَّ بَيْنَ يَدَيْهِ لَمَرَّتْ.","وَفِي رِوَايَةِ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا سَجَدَ، خَوَّى بِيَدَيْهِ، يَعْنِي جَنَّحَ، حَتَّى يُرَى وَضَحُ إِبْطَيْهِ مِنْ وَرَائِهِ، وَإِذَا قَعَدَ، اطْمَأَنَّ عَلَى فَخِذِهِ الْيُسْرَى.","وَفِي رِوَايَةِ: إِذَا سَجَدَ جَافَى حَتَّى يَرَى مَنْ خَلْفَهُ وَضَحَ إِبْطَيْهِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (496،497) من طرق عن يزيد بن الأصَمِّ، عن ميمونة رضي الله عنها فذكرت مثله.","grade":"صحيح","chapter_ar":"باب التجافي في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (496–497)","chapter_en":"Keeping the arms away from the sides in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Maymunah bint al-Harith, the wife of the Prophet ﷺ, said: When the Prophet ﷺ prostrated, if a small lamb wanted to pass between his hands, it could pass. In another narration: When the Messenger of Allah ﷺ prostrated, he kept his arms away from his sides until the whiteness of his armpits could be seen from behind him. And when he sat, he would settle on his left thigh. In another narration: When he prostrated, he moved his arms away so that the whiteness of his armpits could be seen from behind him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (496–497)."},{"num":2084,"demo":false,"sanad":"","matn":["عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَقْرَمِ الْخُزَاعِيِّ، عَنْ أَبِيهِ قَالَ: كُنْتُ مَعَ أَبِي بِالْقَاعِ مِنْ نَمِرَةَ فَمَرَّتْ رَكَبَةٌ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يُصَلِّي قَالَ: فَكُنْتُ أَنْظُرُ إِلَى عُفْرَتَيْ إِبْطَيْهِ إِذَا سَجَدَ وأَريْ بَيَاضِهِ."],"takhrij":"صحيح: رواه الترمذي (274)، والنسائي (1108)، وابن ماجة (881) كلهم من طريق داود بن قيس، عن عبيدالله بن عبدالله الأقرم واللفظ للترمذي.","grade":"صحيح","chapter_ar":"باب التجافي في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Tirmidhi (274) — wording his; al-Nasa’i (1108); Ibn Majah (881)","chapter_en":"Keeping the arms away from the sides in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["‘Ubaydullah ibn ‘Abdullah ibn al-Aqram al-Khuza‘i narrated from his father: I was with my father in the plain of Namirah. A caravan passed by, and the Messenger of Allah ﷺ was standing in prayer. I used to look at the whiteness of his armpits when he prostrated."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (274) — واللفظ له، النسائي (1108)، ابن ماجه (881)."},{"num":2085,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَجَدَ، جَافَى حَتَّى يُرَى بَيَاضُ إِبْطَيْهِ."],"takhrij":"صحيح: رواه الإمام أحمد (14138) قال: حدثنا عبدالرزاق، (وهو في مصنفه 2922) ثنا معمر، عن منصور، عن سالم بن أبي الجعد، عن جابر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب التجافي في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (14138); ‘Abd al-Razzaq (2922); Ibn Khuzaymah authenticated it (649)","chapter_en":"Keeping the arms away from the sides in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: When the Messenger of Allah ﷺ prostrated, he kept his arms away from his sides until the whiteness of his armpits could be seen."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (14138)، عبد الرزاق (2922)، صححه ابن خزيمة (649)."},{"num":2086,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: لَوْ كُنْتُ قُدَّامَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَرَأَيْتُ إِبِطَيْهِ، قَالَ لَاحِقٍ (أَبُو مِجْلَزٍ): أَلَا تَرَى أَنَّهُ فِي الصَّلَاةِ، وَلَا يَسْتَطِيعُ أَنْ يَكُونَ قُدَّامَ رَسُولِ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (746) واللفظ له، والنسائي (1107) كلاهما من طريق عمران، عن أبي مِجْلَز (لاحق) عن بَشر بن نَهيك، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب التجافي في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (746) — wording his; al-Nasa’i (1107)","chapter_en":"Keeping the arms away from the sides in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah said: “If I had been in front of the Prophet ﷺ, I would have seen his armpits.” Abu Majlaz said: “Do you not see that he was in prayer, and one could not have been in front of the Prophet?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (746) — واللفظ له، النسائي (1107)."},{"num":2087,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لا تَبْسُطْ ذِرَاعَيْكَ كَبَسْطِ السَّبُعِ، وَادْعَمْ عَلَى رَاحَتَيْكَ، وَتَجَافَ عَنْ ضَبْعَيْكَ، فَإِنَّكَ إِذَا فَعَلْتَ ذَلِكَ سَجَدَ كُلُّ عُضْوٍ مِنْكَ."],"takhrij":"حسن: رواه ابن خزيمة (645) عن عبيدالله بن سعد بن إبراهيم، قال: حدثنا عمي، أنا أبي، عن ابن إسحاق، حدثني مسعر بن كدام الهلالي، عن آدم ابن علي البكري، عن ابن عمر فذكر الحديث.","grade":"حسن","chapter_ar":"باب التجافي في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (645)","chapter_en":"Keeping the arms away from the sides in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Do not spread your forearms like the spreading of a wild beast. Support yourself on your palms, and keep your upper arms away from your sides. If you do that, every limb of yours will prostrate.”"]},"buhuth":{"en":["“Your upper arms” refers to the upper arm (the part above the elbow)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (645)."},{"num":2088,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ عَمِيرَةَ الْحَضْرَمِيَّ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَجَدَ يُرَى بَيَاضُ إِبْطَيْهِ، ثُمَّ إِذَا سَلَّمَ أَقْبَلَ بِوَجْهِهِ عَنْ يَمِينِهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ، وَعَنْ يَسَارِهِ."],"takhrij":"حسن: رواه الطبراني في الأوسط (8522) عن معاذ قال: حدثنا يحيى بن معين، قال: حدثنا معْتَمِر بن سليمان، قال: قرأتُ على الفُضيل بن ميْسَرة أبي مَعاذٍ، قال: حدثنا أبو حَرِيزٍ، أن قيس بن أبي حازم حدَّثه، عن عدي بن عَمِيْرَة فذكر مثله.","grade":"حسن","chapter_ar":"باب التجافي في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (8517).","chapter_en":"Keeping the arms away from the sides in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["‘Adi ibn ‘Amirah al-Hadrami said: When the Prophet ﷺ prostrated, the whiteness of his armpits could be seen. Then when he gave the closing greetings, he would turn his face to the right until the whiteness of his cheek could be seen, and to the left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الأوسط (8522)."},{"num":2089,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: أُمِرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَسْجُدَ عَلَى سَبْعَةِ أَعْضَاءٍ، وَلَا يَكُفَّ شَعَرًا وَلَا ثَوْبًا الْجَبْهَةِ وَالْيَدَيْنِ وَالرُّكْبَتَيْنِ وَالرِّجْلَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (809)، ومسلم في الصلاة (490) كلاهما من طريق عمرو بن دينار، عن طاوس، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب السجود على سبعة أعظم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (809), Muslim (490)","chapter_en":"Prostration on seven bones","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Abbas said: The Prophet ﷺ was commanded to prostrate on seven body parts and not to gather up hair or clothing: the forehead, the two hands, the two knees, and the two feet."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (809)، مسلم (490)."},{"num":2090,"demo":false,"sanad":"","matn":["عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا سَجَدَ الْعَبْدُ سَجَدَ مَعَهُ سَبْعَةُ أَطْرَافٍ، وَجْهُهُ وَكَفَّاهُ وَرُكْبَتَاهُ وَقَدَمَاهُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (491) عن قتيبة بن سعيد، ثنا بكر (ابن مُضَر) عن ابن الهاد، عن محمد بن إبراهيم، عن عامر بن سعيد، عن العباس بن عبدالمطلب فذكره.","grade":"صحيح","chapter_ar":"باب السجود على سبعة أعظم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (491)","chapter_en":"Prostration on seven bones","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Al-‘Abbas ibn ‘Abd al-Muttalib said that he heard the Messenger of Allah ﷺ say: “When a servant prostrates, seven extremities prostrate with him: his face, his palms, his knees, and his feet.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (491)."},{"num":2091,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رُئِيَ عَلَى جَبْهَتِهِ وَعَلَى أَرْنَبَتِهِ أَثَرُ طِينٍ مِنْ صَلَاةٍ صَلَّاهَا بِالنَّاسِ."],"takhrij":"صحيح: رواه أبو داود (894، 895) عن ابن المثنى، حدثنا صفوان بن عيسى، أخبرنا معمر، ورواه أيضاً عن محمد بن يحيى، حدثنا عبدالرزاق، عن معمر، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي سعيد الخدري فذكر مثله.","grade":"صحيح","chapter_ar":"باب السجود على الجبهة مع الأنف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (894, 895). Its basis is in al-Bukhari (813) and Muslim (1167).","chapter_en":"Prostrating with the forehead along with the nose","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ was seen with traces of mud on his forehead and the tip of his nose from a prayer he had led."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (894، 895)، وأصله في البخاري (813)، ومسلم (1167)."},{"num":2092,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَجَدَ أَمْكَنَ أَنْفَهُ وَجَبْهَتَهُ مِنَ الْأَرْضِ...(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"حسن: رواه أبو داود (734)، والترمذي (270)، والطحاوي (1492)، والبيهقي (2694)، وصحّحه ابن خزيمة (640) كلهم من حديث فليح بن سليمان، حدثني عباس بن سهل، عن أبي حميد الساعدي، فذكره.","grade":"حسن","chapter_ar":"باب السجود على الجبهة مع الأنف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (734), al-Tirmidhi (270), al-Tahawi (1492), and Ibn Khuzaymah authenticated it (640)","chapter_en":"Prostrating with the forehead along with the nose","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Abu Humayd al-Sa‘idi reported that when the Prophet ﷺ prostrated, he placed his nose and his forehead firmly on the ground."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (734)، الترمذي (270)، الطحاوي (1492)، وصححه ابن خزيمة (640)."},{"num":2093,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةِ أَعْظُمٍ عَلَى الْجَبْهَةِ، وَأَشَارَ بِيَدِهِ عَلَى أَنْفِهِ وَالْيَدَيْنِ وَالرُّكْبَتَيْنِ وَأَطْرَافِ الْقَدَمَيْنِ...(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاري في الآذان (812)، ومسلم في الصلاة (490) كلاهما من حديث وهيب، عن عبدالله بن طاوس، عن أبيه، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب من قال: الاكتفاء بالسجود على الأنف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (812), Muslim (490)","chapter_en":"Those who said it is sufficient to prostrate on the nose","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Prophet ﷺ said: “I have been commanded to prostrate on seven bones: on the forehead”—and he gestured toward his nose—“and the two hands, the two knees, and the two feet.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (812)، مسلم (490)."},{"num":2094,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَفَعَهُ قَالَ: إِنَّ الْيَدَيْنِ تَسْجُدَانِ، كَمَا يَسْجُدُ الْوَجْهُ، فَإِذَا وَضَعَ أَحَدُكُمْ وَجْهَهُ، فَلْيَضَعْ يَدَيْهِ، وَإِذَا رَفَعَهُ، فَلْيَرْفَعْهُمَا."],"takhrij":"صحيح: أخرجه أبو داود (892) عن الإمام أحمد، وهو في مسنده (4501)، والنسائي (1092) عن زياد بن أيوب دلويه، كلاهما عن إسماعيل بن عليه، أنا أيوب، عن نافع، عن ابن عمر فذكر مثله.","grade":"صحيح","chapter_ar":"باب السجود على اليدين مع الجبهة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (892), Ahmad (4501), al-Nasa’i (1092)","chapter_en":"Prostrating on the hands along with the forehead","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Umar narrated it as raised to the Prophet ﷺ: “The two hands prostrate just as the face prostrates. So when one of you places his face down, let him place his hands down; and when he lifts it, let him lift them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (892)، أحمد (4501)، النسائي (1092)."},{"num":2095,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: فَقَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً مِنَ الْفِرَاشِ، فَالْتَمَسْتُهُ فَوَقَعَتْ يَدِي عَلَى بَطْنِ قَدَمَيْهِ، وَهُوَ فِي الْمَسْجِدِ (أَيْ فِي السُّجُودِ) وَهُمَا مَنْصُوبَتَانِ، وَهُوَ يَقُولُ: اللَّهُمَّ أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ، كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (486) عن أبي بكر بن أبي شيبة، حدّثنا أبو أسامة، حدثني عبيدالله بن عمر، عن محمد بن يحيى بن حبَّان، عن الأعرج، عن أبي هريرة، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب نصب القدمين ورصّهما في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (486)","chapter_en":"Keeping the feet upright and close together in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah said: I missed the Messenger of Allah ﷺ one night from the bed and searched for him. My hand fell upon the soles of his feet while he was in the mosque—meaning in prostration—while his feet were upright, and he was saying: “O Allah, I seek refuge in Your pleasure from Your wrath, and in Your pardon from Your punishment. I seek refuge in You from You. I cannot enumerate praise of You; You are as You have praised Yourself.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (486)."},{"num":2096,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: فَقَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ مَعِي عَلَى فِرَاشِي فَوَجَدْتُهُ سَاجِدًا رَاصًّا عَقِبَيْهِ، مُسْتَقْبِلا بِأَطْرَافِ أَصَابِعِهِ الْقِبْلَةَ فَسَمِعْتُهُ يَقُولُ: أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِعَفْوِكَ مِنْ عُقُوبَتِكَ، وَبِكَ مِنْكَ أُثْنِيَ عَلَيْكَ لا أَبْلَغُ كُلَّ مَا فِيكَ فَلَمَّا انْصَرَفَ، قَالَ: يَا عَائِشَةُ، أَخَذَكِ شَيْطَانُكِ ؟ فَقُلْتُ: أَمَا لَكَ شَيْطَانٌ ؟ فَقَالَ: مَا مِنْ آدَمِيٍّ إِلا لَهُ شَيْطَانٌ، فَقُلْتُ: وَأَنْتَ يَا رَسُولَ اللَّهِ ؟ قَالَ: وَأَنَا، لَكِنِّي دَعَوْتُ اللهَ عَلَيْهِ فَأَسْلَمَ."],"takhrij":"صحيح: رواه ابن خزيمة (654) ومن طريقه ابن حبان (1933)، والحاكم (838) وعنه البيهقي (2719) كلهم من حديث سعيد بن أبي مريم، أخبرنا يحيى بن أيوب، حدثني عمارة بن غزية، قال: سمعتُ أبا النضر يقول: سمعتُ عروة بن الزبير، يقول: قالت عائشة فذكرت الحديث، إلا أن ابن حبان خالفه في قوله: يا عائشة أخذك شيطانك فقال: يا عائشة أَحَرَّبَكِ شيطانُك أي: أهاجك وأغضبك.","grade":"صحيح","chapter_ar":"باب نصب القدمين ورصّهما في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Khuzaymah (654); Ibn Hibban (1933); al-Hakim (832); al-Bayhaqi (2/116)","chapter_en":"Keeping the feet upright and close together in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: I missed the Messenger of Allah ﷺ while he was with me on my bed, and I found him prostrating with his heels pressed together, directing the tips of his toes toward the direction of prayer. I heard him saying: “I seek refuge in Your pleasure from Your anger, and in Your pardon from Your punishment, and in You from You. I praise You, but I cannot fully praise You as You deserve.” When he finished, he said: “O ‘A’ishah, has your devil taken you?” She said: “Do you have a devil?” He said: “There is no human being except that he has a devil.” I said: “Even you, O Messenger of Allah ﷺ?” He said: “Even me, but I asked Allah against him and he became submissive.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (654)، ابن حبان (1933)، الحاكم (838)، البيهقي (2719)."},{"num":2097,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ سَجَدَ ويَدَيْهِ قَرِيبًا مِنْ أُذُنَيْهِ."],"takhrij":"حسن: رواه ابن أبي شيبة (2667) وعبد الرزاق (2948) كلاهما من طريق سفيان الثوري، عن عاصم بن كليب، عن أبيه، عن وائل بن حجر فذكره.","grade":"حسن","chapter_ar":"باب في اليدين أين تكونان من الرأس عند السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī Shaybah (1/260) and ʿAbd al-Razzāq (2948).","chapter_en":"Where the hands are placed relative to the head in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Wa’il ibn Hujr said: I saw the Prophet ﷺ when he prostrated, with his hands close to his ears."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة (2667)، وعبد الرزاق (2948)."},{"num":2098,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْجُدُ عَلَى أَلْيَتَيِ الْكَفِّ."],"takhrij":"حسن: رواه أحمد (18604)، وصحّحه ابن خزيمة (639)، وعنه ابن حبان (1915)، والحاكم (824) ومن طريقه البيهقي (2669) كلهم من حديث الحسين بن واقد، حدّثنا أبو إسحاق، حدثني البراء، فذكره.","grade":"حسن","chapter_ar":"باب الاعتماد على الكفين في السجود وضمّ أصابعهما وتوجيهها إلى القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (18604); Ibn Khuzaymah authenticated it (639); al-Hakim (828)","chapter_en":"Supporting on the palms in prostration, bringing the fingers together, and directing them toward the direction of prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib said: The Messenger of Allah ﷺ used to prostrate upon the fleshy parts of his palms."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (18604)، صححه ابن خزيمة (639)، الحاكم (824)."},{"num":2099,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: كَانَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَكَعَ بَسَطَ ظَهْرَهُ، وَإِذَا سَجَدَ وَجَّهَ أَصَابِعَهُ قِبَلَ الْقِبْلَةِ فَتَفَلَّجُ."],"takhrij":"حسن: رواه البيهقي (2697) عن أبي العباس محمد بن إسحاق الثقفي، ثنا الحسين بن علي الصدائي، حدثني أبي علي بن يزيد، عن زكريا بن أبي زائدة، عن أبي إسحاق، عن البراء، فذكره.","grade":"حسن","chapter_ar":"باب الاعتماد على الكفين في السجود وضمّ أصابعهما وتوجيهها إلى القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bayhaqī (2/113).","chapter_en":"Supporting on the palms in prostration, bringing the fingers together, and directing them toward the direction of prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib said: When the Prophet ﷺ bowed, he would straighten his back; and when he prostrated, he would point his fingers toward the direction of prayer and keep his arms away from his sides."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (2697)."},{"num":2100,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَكَعَ، فَرَّجَ أَصَابِعَهُ، وَإِذَا سَجَدَ ضَمَّ أَصَابِعَهُ."],"takhrij":"حسن: رواه ابن خزيمة (594)، وابن حبان (1920)، والحاكم (826)، والبيهقي (2695) كلهم من حديث الحارث بن عبدالله بن إسماعيل بن عقبة بن الخازن، ثنا هشيم، عن عاصم بن كليب، عن علقمة بن وائل بن حجر، عن أبيه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الاعتماد على الكفين في السجود وضمّ أصابعهما وتوجيهها إلى القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (594); Ibn Hibban (1920); al-Hakim (1/227); al-Bayhaqi (2/112)","chapter_en":"Supporting on the palms in prostration, bringing the fingers together, and directing them toward the direction of prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Wa’il ibn Hujr reported that the Prophet ﷺ would spread his fingers when bowing, and bring his fingers together when prostrating."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (594)، ابن حبان (1920)، الحاكم (826)، البيهقي (2695)."},{"num":2101,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ اللَّيْثِيِّ أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فَإِذَا كَانَ فِي وِتْرٍ مِنْ صَلَاتِهِ لَمْ يَنْهَضْ حَتَّى يَسْتَوِيَ قَاعِدًا."],"takhrij":"صحيح: رواه البخاري في الآذان (823) عن محمد بن الصباح، أخبرنا هُشيم، قال: أخبرنا خالد الحذاء، عن أبي قلابة، أخبرنا مالك بن الحويرث فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جلسة الاستراحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (823)","chapter_en":"The sitting of rest","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["Malik ibn al-Huwayrith al-Laythi said that he saw the Prophet ﷺ praying, and when he was in an odd-numbered unit of his prayer, he would not rise until he had sat upright."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (823)."},{"num":2102,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ فِي عَشَرَةٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِمْ أَبُو قَتَادَةَ، فَذَكَرَ الْحَدِيثَ فِي صِفَةِ صَلَاةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِيهِ:ثُمَّ يَعُودُ، يَعْنِي إِلَى السُّجُودِ، ثُمَّ يَرْفَعُ فَيَقُولُ: اللهُ أَكْبَرُ، ثُمَّ يَثْنِي رِجْلَهُ فَيَقْعُدُ عَلَيْهَا مُعْتَدِلًا حَتَّى يَرْجِعَ أَوْ يَقِرَّ كُلُّ عَظْمٍ مَوْضِعَهُ مُعْتَدِلًا."],"takhrij":"صحيح: رواه البيهقي (2758) واللفظ له، عن شيخه الحاكم أبي عبدالله، ثنا أبو العباس محمد بن يعقوب، ثنا محمد بن سنان، ثنا أبو عاصم، عن عبدالحميد بن جعفر، قال: حدثني محمد بن عمرو بن عطاء قال: سمعتُ أبا حميد الساعدي في عشرة من أصحاب النبيّ صلى الله عليه وسلم فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في جلسة الاستراحة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bayhaqī (2/123).","chapter_en":"The sitting of rest","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["Abu Humayd al-Sa‘idi, among ten Companions of the Prophet ﷺ, including Abu Qatadah, narrated the description of the Prophet’s prayer. In it: then he returns—meaning to prostration—then he raises up saying: “Allah is the Greatest,” then he folds his leg and sits on it upright until every bone returns— or settles— into its place in a balanced manner."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البيهقي (2758)."},{"num":2103,"demo":false,"sanad":"","matn":["عَنْ أَبِي الزُّبَيْرِ أَنَّهُ سَمِعَ طَاوُسًا يَقُولُ: قُلْنَا لِابْنِ عَبَّاسٍ: فِي الإِقْعَاءِ عَلَى الْقَدَمَيْنِ ؟ فَقَالَ: هِيَ السُّنَّةُ، فَقُلْنَا لَهُ: إِنَّا لَنَرَاهُ جَفَاءً بِالرَّجُلِ، فَقَالَ ابْنُ عَبَّاسٍ: بَلْ هِيَ سُنَّةُ نَبِيِّكَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: أخرجه مسلم في المساجد (536) عن إسحاق بن إبراهيم، أنبا محمد بن بكر، أنبأ ابن جريج، أخبرني أبو الزبير فذكر الحديث.","grade":"صحيح","chapter_ar":"باب القعود على العقبين بين السجدتين وهو الإقعاء المباح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (536)","chapter_en":"Sitting on the heels between the two prostrations, the permissible iq‘a’","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":17,"content":{"translation":{"en":["Abu al-Zubayr said that he heard Tawus say: We asked Ibn ‘Abbas about sitting in iq‘a’ on the feet. He said: “It is the Sunnah.” We said: “We see it as harsh on a man.” Ibn ‘Abbas said: “Rather, it is the Sunnah of your Prophet Muhammad ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (536)."},{"num":2104,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ (فَذَكَرَهَا فِي حَدِيثِ طَوِيل): كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْرِشُ رِجْلَهُ الْيُسْرَى، وَيَنْصِبُ رِجْلَهُ الْيُمْنَى، وَكَانَ يَنْهَى عَنْ عُقْبَةِ الشَّيْطَانِ... الْحَدِيثَ.","وَفِي رِوَايَةِ: وَكَانَ يَنْهَى عَنْ عَقِبِ الشَّيْطَانِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (498) من طريق حسين المعلم، عن بُديل ابن ميسرة، عن أبي الجوزاء، عن عائشة في حديث طويل سبق ذكره في بداية القراءة بفاتحة الكتاب، وفي باب الاعتدال في الركوع والسجود.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن عقبة الشيطان وهو الإقعاء المكروه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (498)","chapter_en":"Prohibition of “the devil’s sitting,” the disliked form of sitting on the heels","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ used to lay his left foot flat (sit on it) and keep his right foot upright, and he used to forbid “the devil’s sitting.” In another narration: he used to forbid “the devil’s heel-sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (498)."},{"num":2105,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى رَجُلا وَهُوَ جَالِسٌ مُعْتَمِدٌ عَلَى يَدِهِ الْيُسْرَى فِي الصَّلاةِ، فَقَالَ: إِنَّهَا صَلاةُ الْيَهُودِ."],"takhrij":"صحيح: رواه الحاكم (1007) من طريق هشام بن يوسف، عن معمر، عن إسماعيل بن أمية، عن نافع، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن عقبة الشيطان وهو الإقعاء المكروه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Hakim (1007). Also narrated by Ahmad (6347) and Abu Dawud (992) with the second wording.","chapter_en":"Prohibition of “the devil’s sitting,” the disliked form of sitting on the heels","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Ibn ‘Umar reported that the Prophet ﷺ forbade a man from sitting in prayer while leaning on his left hand, and he said: “That is the prayer of the Jews.” In another wording: “The Messenger of Allah ﷺ forbade a man from sitting in prayer while leaning on his hands.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (1007)، ورواه أيضا أحمد (6347)، وأبو داود (992) باللفظ الثاني."},{"num":2106,"demo":false,"sanad":"","matn":["عَنْ أَبِي قِلَابَةَ قَالَ: جَاءَنَا مَالِكُ بْنُ الْحُوَيْرِثِ فَصَلَّى بِنَا فِي مَسْجِدِنَا هَذَا فَقَالَ: إِنِّي لَأُصَلِّي بِكُمْ وَمَا أُرِيدُ الصَّلَاةَ، وَلَكِنْ أُرِيدُ أَنْ أُرِيَكُمْ كَيْفَ رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، قَالَ أَيُّوبُ: فَقُلْتُ لِأَبِي قِلَابَةَ: وَكَيْفَ كَانَتْ صَلَاتُهُ؟ قَالَ: مِثْلَ صَلَاةِ شَيْخِنَا هَذَا يَعْنِي عَمْرَو بْنَ سَلِمَةَ، قَالَ أَيُّوبُ: وَكَانَ ذَلِكَ الشَّيْخُ يُتِمُّ التَّكْبِيرَ، وَإِذَا رَفَعَ رَأْسَهُ عَنِ السَّجْدَةِ الثَّانِيَةِ جَلَسَ وَاعْتَمَدَ عَلَى الْأَرْضِ ثُمَّ قَامَ."],"takhrij":"صحيح: رواه البخاري في الأذان (824) عن معلى بن أسد، قال: حدثنا وُهيب، عن أيوب، عن أبي قِلابة فذكر مثله.","grade":"صحيح","chapter_ar":"باب كيفية النهوض إلى الركعة الثانية وسائر الركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (824)","chapter_en":"How to rise for the second unit and the rest of the units","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Abu Qilabah said: Malik ibn al-Huwayrith came to us and led us in prayer in this mosque of ours and said: “I am praying with you, though I do not intend (this as) prayer; rather, I want to show you how I saw the Prophet ﷺ pray.” Ayyub said: I asked Abu Qilabah: “How was his prayer?” He said: “Like the prayer of our shaykh here,” meaning ‘Amr ibn Salamah. Ayyub said: That shaykh would complete the takbīrs properly, and when he raised his head from the second prostration he would sit, lean on the ground, then stand."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (824)."},{"num":2107,"demo":false,"sanad":"","matn":["عَنِ الْأَزْرَقِ بْنِ قَيْسٍ قَالَ: رَأَيْتُ ابْنَ عُمَرَ إِذَا قَامَ مِنَ الرَّكْعَتَيْنِ اعْتَمَدَ عَلَى الْأَرْضِ بِيَدَيْهِ فَقُلْتُ لِوَلَدِهِ وَلِجُلَسَائِهِ: لَعَلَّهُ يَفْعَلُ هَذَا مِنَ الْكِبَرِ؟ قَالُوا: لَا وَلَكِنْ هَذَا يَكُونُ."],"takhrij":"حسن: رواه البيهقي (2806) من حديث كامل بن طلحة، نثا حماد بن سلمة، عن الأزرق، فذكره.","grade":"حسن","chapter_ar":"باب كيفية النهوض إلى الركعة الثانية وسائر الركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bayhaqī (2/135).","chapter_en":"How to rise for the second unit and the rest of the units","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Al-Azraq ibn Qays said: I saw Ibn ‘Umar, when he rose after two units, lean on the ground with his hand. I asked his son and those sitting with him: “Perhaps he does this due to old age?” They said: “No, rather this is how it is done.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (2806)."},{"num":2108,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كَشَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السِّتَارَةَ، وَالنَّاسُ صُفُوفٌ خَلْفَ أَبِي بَكْرٍ، فَقَالَ: أَيُّهَا النَّاسُ إِنَّهُ لَمْ يَبْقَ مِنْ مُبَشِّرَاتِ النُّبُوَّةِ إِلَّا الرُّؤْيَا الصَّالِحَةُ يَرَاهَا الْمُسْلِمُ، أَوْ تُرَى لَهُ، أَلَا وَإِنِّي نُهِيتُ أَنْ أَقْرَأَ الْقُرْآنَ رَاكِعًا أَوْ سَاجِدًا، فَأَمَّا الرُّكُوعُ فَعَظِّمُوا فِيهِ الرَّبَّ عَزَّ وَجَلَّ، وَأَمَّا السُّجُودُ فَاجْتَهِدُوا فِي الدُّعَاءِ، فَقَمِنٌ أَنْ يُسْتَجَابَ لَكُمْ."],"takhrij":"صحيح: رواه مسلم في الصلاة (479) من أوجه عن سفيان بن عيينة، قال: أخبرني سليمان بن سُحيم، عن إبراهيم بن عبدالله بن معبد، عن أبيه، عن ابن عباس فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن قراءة القرآن في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (479)","chapter_en":"Prohibition of reciting Qur’an while bowing and prostrating","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":20,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ drew back the curtain while the people were standing in rows behind Abu Bakr, and he said: “O people, nothing remains of the glad tidings of prophethood except a righteous dream that a Muslim sees or is shown to him. Indeed, I have been forbidden from reciting the Qur’an while bowing or prostrating. As for bowing, then magnify the Lord, Mighty and Majestic, in it. As for prostration, strive hard in supplication, for it is most worthy that you will be answered.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[771,2111,10931,11814],"tks":"صحيح: رواه مسلم (479)."},{"num":2109,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: نَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنْ أَقْرَأَ رَاكِعًا أَوْ سَاجِدًا."],"takhrij":"صحيح: رواه مسلم في الصلاة (480) من طريق ابن شهاب والوليد بن كثير وزيد بن أسلم كلهم عن إبراهيم بن عبدالله بن حُنين، عن أبيه، أنه سمع علي بن أبي طالب فذكره وألفاظهم متقاربة.","grade":"صحيح","chapter_ar":"باب النهي عن قراءة القرآن في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (480)","chapter_en":"Prohibition of reciting Qur’an while bowing and prostrating","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":20,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ forbade me from reciting while bowing and while prostrating."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (480)."},{"num":2110,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)، أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا فَرَغَ اللَّهُ مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ وَأَرَادَ أَنْ يُخْرِجَ بِرَحْمَتِهِ مَنْ أَرَادَ مِنْ أَهْلِ النَّارِ أَمَرَ الْمَلَائِكَةَ أَنْ يُخْرِجُوا مِنَ النَّارِ مَنْ كَانَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا مِمَّنْ أَرَادَ اللَّهُ أَنْ يَرْحَمَهُ مِمَّنْ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، فَيَعْرِفُونَهُمْ فِي النَّارِ بِأَثَرِ السُّجُودِ تَأْكُلُ النَّارُ ابْنَ آدَمَ إِلَّا أَثَرَ السُّجُودِ حَرَّمَ اللَّهُ عَلَى النَّارِ أَنْ تَأْكُلَ أَثَرَ السُّجُودِ، فَيَخْرُجُونَ مِنَ النَّارِ قَدِ امْتُحِشُوا، فَيُصَبُّ عَلَيْهِمْ مَاءُ الْحَيَاةِ فَيَنْبُتُونَ تَحْتَهُ كَمَا تَنْبُتُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ... الْحَدِيثَ."],"takhrij":"متفق عليه: رواه البخاري في كتاب التوحيد (7437) ومسلمٌ في الإيمانِ (182) كلاهما من طريق إبراهيم بن سعد، عن ابن شهابٍ، عن عطاء بن يزيد الليثي، عن أبي هريرة.. فذكره، في حديثٍ طويلٍ سبق ذكره في الإيمانِ.","grade":"متفق عليه","chapter_ar":"باب فضل السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (7437), Muslim (182)","chapter_en":"The virtue of prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When Allah finishes judging between His servants, He will, by His mercy, bring out from the people of the Fire whom He wills. He will command the angels to take out from the Fire those who did not associate anything with Allah—among those whom He wishes to show mercy, those who testified that there is no god worthy of worship except Allah. They will recognize them in the Fire by the marks of prostration. The Fire consumes the son of Adam except the marks of prostration. Allah has forbidden the Fire from consuming the marks of prostration. They will be brought out of the Fire, burned, and then the water of life will be poured over them, and they will grow beneath it like a seed grows in the silt carried by a flood.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7437)، مسلم (182)."},{"num":2111,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كَشَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السِّتَارَةَ، وَالنَّاسُ صُفُوفٌ خَلْفَ أَبِي بَكْرٍ فَقَالَ: أَيُّهَا النَّاسُ إِنَّهُ لَمْ يَبْقَ مِنْ مُبَشِّرَاتِ النُّبُوَّةِ إِلَّا الرُّؤْيَا الصَّالِحَةُ يَرَاهَا الْمُسْلِمُ، أَوْ تُرَى لَهُ، أَلَا وَإِنِّي نُهِيتُ أَنْ أَقْرَأَ الْقُرْآنَ رَاكِعًا أَوْ سَاجِدًا، فَأَمَّا الرُّكُوعُ فَعَظِّمُوا فِيهِ الرَّبَّ عَزَّ وَجَلَّ، وَأَمَّا السُّجُودُ فَاجْتَهِدُوا فِي الدُّعَاءِ، فَقَمِنٌ أَنْ يُسْتَجَابَ لَكُمْ."],"takhrij":"صحيح: رواه مسلم في الصلاة (479) من طريق سفيان بن عيينة، أخبرني سليمان بن سُحيم، عن إبراهيم بن عبدالله بن معبد، عن أبيه، عن ابن عباس فذكره، وسبق ذكر الحديث في باب النهي عن قراءة القرآن في الرّكوع والسجود.","grade":"صحيح","chapter_ar":"باب الأمر بالاجتهاد في الدعاء في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (479)","chapter_en":"Command to strive in supplication while prostrating","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ drew back the curtain while the people were in rows behind Abu Bakr and said: “O people, nothing remains of the glad tidings of prophethood except a righteous dream that a Muslim sees or is shown to him. Indeed, I have been forbidden from reciting the Qur’an while bowing or prostrating. As for bowing, then magnify the Lord, Mighty and Majestic, in it. As for prostration, strive hard in supplication, for it is most worthy that you will be answered.”"]}},"tuhfa":{},"full":1,"rep":[771,2108,10931,11814],"tks":"صحيح: رواه مسلم (479)."},{"num":2112,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكْثِرُوا الدُّعَاءَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (482) من طريق سُمي مولى أبي بكر، أنه سمع أبا صالح ذكوان، يحدث عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الأمر بالاجتهاد في الدعاء في السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (482)","chapter_en":"Command to strive in supplication while prostrating","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The closest a servant is to his Lord is while he is prostrating, so increase in supplication.”"]}},"tuhfa":{},"full":1,"rep":[10932],"tks":"صحيح: رواه مسلم (482)."},{"num":2113,"demo":false,"sanad":"","matn":["عَنْ مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمَرِيِّ قَالَ: لَقِيتُ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: أَخْبِرْنِي بِعَمَلٍ أَعْمَلُهُ يُدْخِلُنِي اللَّهُ بِهِ الْجَنَّةَ ؟ أَوَ قَالَ: قُلْتُ: بِأَحَبِّ الأَعْمَالِ إِلَى اللَّهِ، فَسَكَتَ، ثُمَّ سَأَلْتُهُ فَسَكَت، ثُمَّ سَأَلْتُهُ الثَّالِثَةَ، فَقَالَ: سَأَلْتُ عَنْ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: عَلَيْكَ بِكَثْرَةِ السُّجُودِ لِلَّهِ، فَإِنَّكَ لَا تَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَكَ اللَّهُ بِهَا دَرَجَةً وَحَطَّ عَنْكَ بِهَا خَطِيئَةً.","قَالَ مَعْدَانُ: ثُمَّ لَقِيتُ أَبَا الدَّرْدَاءِ فَسَأَلْتُهُ، فَقَالَ لِي مِثْلَ مَا قَالَ لِي ثَوْبَانُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (488) من طريق الأوزاعي، قال: حدثني الوليد بن هشام المُعيطي، حدثني معدان بن أبي طلحة اليَعْمَري فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في الحث على كثرة السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (488)","chapter_en":"Encouragement to increase in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["Ma‘dan ibn Abi Talhah al-Ya‘mari said: I met Thawban, the freed slave of the Messenger of Allah ﷺ, and said: “Tell me of an action that I can do that will cause Allah to admit me into Paradise”—or I said: “(Tell me) of the most beloved deeds to Allah.” He remained silent. Then I asked him and he remained silent. Then I asked him a third time. He said: “I asked the Messenger of Allah ﷺ about that and he said: ‘You must increase in prostration to Allah. You do not make one prostration to Allah except that Allah raises you by it one rank and removes from you by it one sin.’” Ma‘dan said: Then I met Abu al-Darda’ and asked him, and he told me the same as Thawban told me."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (488)."},{"num":2114,"demo":false,"sanad":"","matn":["عَنْ رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ قَالَ: كُنْتُ أَبِيتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَيْتُهُ بِوَضُوئِهِ وَحَاجَتِهِ، فَقَالَ لِي: سَلْ، فَقُلْتُ: أَسْأَلُكَ مُرَافَقَتَكَ فِي الْجَنَّةِ ؟ قَالَ: أَوَغَيْرَ ذَلِكَ، قُلْتُ: هُوَ ذَاكَ، قَالَ: فَأَعِنِّي عَلَى نَفْسِكَ بِكَثْرَةِ السُّجُودِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (489) من طريق الأوزاعي، قال: حدثني يحيى بن أبي كثير، حدثني أبو سلمة، حدثني ربيعة بن كعب الأسلمي فذكر مثله، وفي الحديث دليل لمن يقول: إن تكثير السجود أفضل من تطويل القيام. ولكن لما عارضه حديث جابر في صحيح مسلم أن النبيَّ صلى الله عليه وسلم قال: أفضل الصلاة طول القنوت توقف الإمام أحمد عن الترجيح. والمراد بالقنوت القيام.","grade":"صحيح","chapter_ar":"باب ما جاء في الحث على كثرة السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (489)","chapter_en":"Encouragement to increase in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["Rabi‘ah ibn Ka‘b al-Aslami said: I used to stay the night with the Messenger of Allah ﷺ, and I would bring him his water for ablution and whatever he needed. He said to me: “Ask.” I said: “I ask for your companionship in Paradise.” He said: “Or something else?” I said: “That is it.” He said: “Then help me to attain that for you by increasing in prostration.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[930],"tks":"صحيح: رواه مسلم (489)."},{"num":2115,"demo":false,"sanad":"","matn":["عَنْ خَادِمٍ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٍ أَوْ امْرَأَةٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِمَّا يَقُولُ لِلْخَادِم: أَلَكَ حَاجَةٌ ؟ قَالَ: حَتَّى كَانَ ذَاتَ يَوْمٍ، فَقَالَ: يَا رَسُولَ اللَّهِ حَاجَتِي، قَالَ: وَمَا حَاجَتُكَ ؟ قَالَ: حَاجَتِي أَنْ تَشْفَعَ لِي يَوْمَ الْقِيَامَةِ، قَالَ: وَمَنْ دَلَّكَ عَلَى هَذَا ؟ قَالَ: رَبِّي، قَالَ: إِمَّا لَا فَأَعِنِّي بِكَثْرَةِ السُّجُودِ."],"takhrij":"صحيح: رواه أحمد (16076) عن عفان، حدثنا خالد – يعني الواسطي، ، قال: حدثنا عمرو بن يحيى الأنصاري، عن زياد بن أبي زياد مولى بني مخزوم، عن خادم للنبي صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الحث على كثرة السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (16076)","chapter_en":"Encouragement to increase in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["A servant of the Prophet ﷺ—a man or a woman—said: The Prophet ﷺ would say to the servant: “Do you have a need?” One day the servant said: “O Messenger of Allah, I have a need.” He said: “What is your need?” The servant said: “My need is that you intercede for me on the Day of Resurrection.” He said: “Who guided you to this?” The servant said: “My Lord.” He said: “If that is the case, then help me by increasing in prostration.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[931],"tks":"صحيح: رواه أحمد (16076)."},{"num":2116,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اعْلَمْ أَنَّكَ لَنْ تَسْجُدَ لِلَّهِ سَجْدَةً إِلَّا رَفَعَ اللَّهُ لَكَ بِهَا دَرَجَةً , وَحَطَّ عَنْكَ بِهَا خَطِيئَةً."],"takhrij":"صحيح: رواه أحمد (22140) عن روح، عن هشام، عن واصل مولى أبي عيينة، عن محمد بن أبي يعقوب، عن رجاء بن حيوة، عن أبي أمامة فذكره بطوله.","grade":"صحيح","chapter_ar":"باب ما جاء في الحث على كثرة السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (22140)","chapter_en":"Encouragement to increase in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["Abu Umamah reported that the Messenger of Allah ﷺ said: “Know that you will not prostrate to Allah a single prostration except that Allah raises you by it one rank and removes from you by it one sin.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (22140)."},{"num":2117,"demo":false,"sanad":"","matn":["عَنْ أَبِي فَاطِمَةَ قَالَ: قُلْتُ يَا رَسُولَ اللَّهِ: أَخْبِرْنِي بِعَمَلٍ أَسْتَقِيمُ عَلَيْهِ وَأَعْمَلُهُ، قَالَ: عَلَيْكَ بِالسُّجُودِ، فَإِنَّكَ لَا تَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَكَ اللَّهُ بِهَا دَرَجَةً، وَحَطَّ بِهَا عَنْكَ خَطِيئَةً."],"takhrij":"حسن: رواه ابن ماجه (1422) عن هشام بن عمار وعبدالرحمن بن إبراهيم االدّمشقيان قالا: حدثنا الوليد بن مسلم، قال: حدثنا عبدالرحمن بن ثابت بن ثوبان، عن أبيه، عن مكحول، عن كثير بن مرة أنّ أبا فاطمة قال: فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في الحث على كثرة السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (1422)","chapter_en":"Encouragement to increase in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["Abu Fatimah said: I said: “O Messenger of Allah ﷺ, tell me of an action that I can remain steadfast upon and do.” He said: “You must prostrate, for you do not prostrate to Allah a single prostration except that Allah raises you by it one rank and removes from you by it one sin.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1422)."},{"num":2118,"demo":false,"sanad":"","matn":["عَنِ الْأَحْنَفِ بْنِ قَيْسٍ قَالَ: دَخَلْتُ بَيْتَ الْمَقْدِسِ، فَوَجَدْتُ فِيهِ رَجُلًا يُكْثِرُ السُّجُودَ، فَوَجَدْتُ فِي نَفْسِي مِنْ ذَلِكَ، فَلَمَّا انْصَرَفَ قُلْتُ: أَتَدْرِي عَلَى شَفْعٍ انْصَرَفْتَ أَمْ عَلَى وِتْرٍ ؟ قَالَ: إِنْ أَكُ لَا أَدْرِي فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَدْرِي، ثُمَّ قَالَ: أَخْبَرَنِي حِبِّي أَبُو الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ بَكَى ثُمَّ قَالَ: أَخْبَرَنِي حِبِّي أَبُو الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ بَكَى ثُمَّ قَالَ: أَخْبَرَنِي حِبِّي أَبُو الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: مَا مِنْ عَبْدٍ يَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً، وَحَطَّ عَنْهُ بِهَا خَطِيئَةً، وَكَتَبَ لَهُ بِهَا حَسَنَةً.","قَالَ: قُلْتُ: أَخْبِرْنِي مَنْ أَنْتَ يَرْحَمُكَ اللَّهُ ؟ قَالَ: أَنَا أَبُو ذَرٍّ صَاحِبُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَتَقَاصَرَتْ إِلَيَّ نَفْسِي."],"takhrij":"صحيح: رواه الإمام أحمد (21452) عن عبد الرزاق – وهو في مصنَّفه (3061، 4847) قال: سمعت الأوزاعي يقول: أخبرني هارون بن رئاب، عن الأحنف بن قيس فذكره. ورواه البزّار (3903) من طريق الأوزاعي به.","grade":"صحيح","chapter_ar":"باب ما جاء في الحث على كثرة السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (21452); ‘Abd al-Razzaq in al-Musannaf (3061, 4847); al-Bazzar (3903)","chapter_en":"Encouragement to increase in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["Al-Ahnaf ibn Qays said: I entered Jerusalem and found a man there making many prostrations, and I felt something about that within myself. When he finished, I said: “Do you know whether you finished on an even number or an odd number?” He said: “If I do not know, then Allah knows.” Then he said: “My beloved Abu al-Qasim ﷺ told me”—then he wept. Then he said again: “My beloved Abu al-Qasim ﷺ told me”—then he wept. Then he said: “My beloved Abu al-Qasim ﷺ told me that he said: ‘No servant prostrates to Allah a single prostration except that Allah raises him by it one degree, removes from him by it one sin, and writes for him by it one good deed.’” I said: “Tell me—who are you, may Allah have mercy on you?” He said: “I am Abu Dharr, a Companion of the Messenger of Allah ﷺ.” So I felt small in myself."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (21452)، عبد الرزاق في المصنف (3061، 4847)، البزار (3903)."},{"num":2119,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ عَبْدٍ يَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا كَتَبَ اللَّهُ لَهُ بِهَا حَسَنَةً، وَمَحَا عَنْهُ بِهَا سَيِّئَةً، وَرَفَعَ لَهُ بِهَا دَرَجَةً، فَاسْتَكْثِرُوا مِنَ السُّجُودِ."],"takhrij":"صحيح: رواه ابن ماجه (1424) عن العباس بن عثمان الدمشقي، قال: حدثنا الوليد بن مسلم، عن خالد بن يزيد المُرِّي، عن يونس بن ميسرة بن حلبس، عن الصُنابحي، عن عبادة بن الصامت فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الحث على كثرة السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (1424)","chapter_en":"Encouragement to increase in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["‘Ubadah ibn al-Samit reported that he heard the Prophet ﷺ say: “No servant prostrates to Allah a single prostration except that Allah writes for him by it a good deed, erases from him by it a sin, and raises him by it a degree—so increase in prostration.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1424)."},{"num":2120,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:إِنَّ الْعَبْدَ إِذَا قَامَ إِلَى الصَّلَاةِ أُتِيَ بِذُنُوبِهِ كُلِّهَا فَوُضِعَتْ عَلَى عَاتِقَيْهِ فَكُلَّمَا رَكَعَ أَوْ سَجَدَ تَسَاقَطَتْ عَنْهُ."],"takhrij":"حسن: رواه محمد بن نصر المروزي في تعظيم قدر الصلاة (293)، وأبو نعيم في حلية الأولياء (6/99، 100) كلاهما من طريق إسحاق بن إبراهيم بن راهويه، أنا عيسى بن يونس، ثنا ثور بن يزيد، عن أبي المنيب قال: رأى ابن عمر فتى قد أطال الصلاة وأطنب، فقال: أيكم يعرف هذا؟ فقال رجل: أنا أعرفه، فقال: أما إني لو عرفته لأمرته بكثرة الركوع والسجود، فإني سمعت رسول الله صلى الله عليه وسلم يقول: الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في الحث على كثرة السجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nMuhammad ibn Nasr al-Marwazi in Ta‘zim Qadr al-Salah (293); Abu Nu‘aym in al-Hilyah (6/99–100)","chapter_en":"Encouragement to increase in prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: I heard the Messenger of Allah ﷺ say: “When a servant stands for prayer, all of his sins are brought and placed upon his shoulders. Each time he bows or prostrates, they fall away from him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه محمد بن نصر المروزي في تعظيم قدر الصلاة (293)، أبو نعيم في الحلية (1421)."},{"num":2121,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي يَتَأَوَّلُ الْقُرْآنَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4968)، ومسلم في الصلاة (484) كلاهما من طريق جرير، عن منصور، عن أبي الضُحى، عن مسروق، عن عائشة فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (4968), Muslim (484)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The Prophet ﷺ would often say in his bowing and prostration: “Glory be to You, O Allah, our Lord, and with Your praise. O Allah, forgive me,” interpreting the Qur’an (acting upon it)."]},"buhuth":{"en":["“Interpreting the Qur’an” means he was acting upon Allah’s command in: “When the help of Allah and the victory come, and you see the people entering the religion of Allah in crowds, then glorify your Lord with praise and seek His forgiveness. Indeed, He is ever accepting of repentance.” (Qur’an 110:1–3)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4968)، مسلم (484)."},{"num":2122,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتِ: افْتَقَدْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَظَنَنْتُ أَنَّهُ ذَهَبَ إِلَى بَعْضِ نِسَائِهِ، فَتَحَسَّسْتُ ثُمَّ رَجَعْتُ فَإِذَا هُوَ رَاكِعٌ، أَوْ سَاجِدٌ يَقُولُ: سُبْحَانَكَ وَبِحَمْدِكَ، لَا إِلَهَ إِلَّا أَنْتَ، فَقُلْتُ: بِأَبِي أَنْتَ وَأُمِّي! إِنِّي لَفِي شَأْنٍ، وَإِنَّكَ لَفِي آخَرَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (485) من طريق عبد الرزاق، أخبرنا ابن جريج قال: قلت لعطاء: كيف تقول أنت في الركوع؟ قال: أمَّا سبحانك وبحمدك لا إله إلا أنت. فأخبرني ابن أبي مليكة، عن عائشة قالت: فذكرتِ الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (485)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah said: I missed the Prophet ﷺ one night and thought he had gone to one of his wives. I felt around, then returned and found him bowing or prostrating, saying: “Glory be to You and with Your praise; there is no god worthy of worship except You.” I said: “May my father and mother be sacrificed for you! I was thinking one thing, while you were in something else entirely.”"]}},"tuhfa":{},"full":1,"rep":[6407,10998],"tks":"صحيح: رواه مسلم (485)."},{"num":2123,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: فَقَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً مِنَ الْفِرَاشِ، فَالْتَمَسْتُهُ فَوَقَعَتْ يَدِي عَلَى بَطْنِ قَدَمَيْهِ، وَهُوَ فِي الْمَسْجِدِ، وَهُمَا مَنْصُوبَتَانِ وَهُوَ يَقُولُ: اللَّهُمَّ أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ لَا أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ، كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (486) عن أبي بكر بن أبي شيبة، ثنا أبو أسامة، حدثني عبيدالله بن عمر، عن محمد بن يحيى بن حبان، عن الأعرج، عن أبي هريرة، عن عائشة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (486)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah said: I missed the Messenger of Allah ﷺ one night from the bed and searched for him. My hand fell upon the soles of his feet while he was in the mosque, with his feet upright, and he was saying: “O Allah, I seek refuge in Your pleasure from Your anger, and in Your pardon from Your punishment. I seek refuge in You from You. I cannot enumerate praise of You; You are as You have praised Yourself.”"]}},"tuhfa":{},"full":1,"rep":[10999],"tks":"صحيح: رواه مسلم (486)."},{"num":2124,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ ّرَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي رُكُوعِهِ وَسُجُودِه، سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (487) عن أبي بكر بن أبي شيبة، ثنا محمد بن بِشْر العبدي، حدثنا سعيد بن أبي عروبة، عن قتادة، عن مطرِفّ بن عبدالله بن الشخّير، أن عائشة نَبَّأته فذكرتِ الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (487)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah reported that the Messenger of Allah ﷺ used to say in his bowing and prostration: “Perfectly Glorious, Perfectly Pure—Lord of the angels and the Spirit.”"]},"buhuth":{"en":["“Subbuh” means: the One declared free from deficiency, partners, and anything unbefitting divinity. “Quddus” means: the One purified from anything unbefitting the Creator."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11000],"tks":"صحيح: رواه مسلم (487)."},{"num":2125,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ قَالَ: كَانَ نَبِيُّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ رَاكِعًا أَوْ سَاجِدًا قَالَ: سُبْحَانَكَ وَبِحَمْدِكَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."],"takhrij":"حسن: رواه الطبراني في الكبير (10302) عن أحمد بن خليد الحلبي، حدثنا عبدالله بن جعفر الرقي، حدثنا عبيد الله بن عمرو، عن زيد بن أبي أنيسة، عن حماد، عن أبي الضحى، عن مسروق، عن عبد الله بن مسعود، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Kabir (10/192)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: When your Prophet ﷺ was bowing or prostrating, he would say: “Glory be to You and with Your praise. I seek Your forgiveness and repent to You.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الكبير (10302)."},{"num":2126,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ أَنَّهُ صَلَّى مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَانَ يَقُولُ فِي رُكُوعِهِ: سُبْحَانَ رَبِّيَ الْعَظِيمِ، وَفِي سُجُودِهِ: سُبْحَانَ رَبِّيَ الْأَعْلَى، وَمَا مَرَّ بِآيَةِ رَحْمَةٍ إِلَّا وَقَفَ عِنْدَهَا فَسَأَلَ، وَلَا بِآيَةِ عَذَابٍ إِلَّا وَقَفَ عِنْدَهَا فَتَعَوَّذَ.","وَفِي رِوَايَةِ: وَإِذَا مَرَّ بِتَعَوُّذٍ تَعَوَّذَ، ثُمَّ رَكَعَ، فَجَعَلَ يَقُولُ: سُبْحَانَ رَبِّيَ الْعَظِيمِ، فَكَانَ رُكُوعُهُ نَحْوًا مِنْ قِيَامِهِ، ثُمَّ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، ثُمَّ قَامَ طَوِيلًا، قَرِيبًا مِمَّا رَكَعَ، ثُمَّ سَجَدَ، فَقَالَ: سُبْحَانَ رَبِّيَ الأَعْلَى، فَكَانَ سُجُودُهُ قَرِيبًا مِنْ قِيَامِه."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (772) و أبو داود (871) من طريق سعد بن عبيدة، عن المستورد بن الأحنف، عن صِلة بن زفر، عن حذيفة في حديث طويل وسيأتي في صلاة الليل.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (772)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Hudhayfah ibn al-Yaman said: I prayed with the Prophet ﷺ. He would say in his bowing: “Glory be to my Lord, the Magnificent,” and in his prostration: “Glory be to my Lord, the Most High.” Whenever he passed a verse about mercy, he would pause and ask (Allah); and whenever he passed a verse about punishment, he would pause and seek refuge."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (772)."},{"num":2127,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي سُجُودِهِ: اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (483) من طريق سمى مولى أبي بكر، عن أبي صالح، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (483)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ used to say in his prostration: “O Allah, forgive me all of my sins: the small and the great, the first and the last, what is public and what is hidden.”"]}},"tuhfa":{},"full":1,"rep":[11002],"tks":"صحيح: رواه مسلم (483)."},{"num":2128,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ وَإِذَا رَكَعَ، قَالَ: اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي، وَبَصَرِي، وَمُخِّي، وَعَظْمِي، وَعَصَبِي.","وَإِذَا سَجَدَ قَالَ: اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (771) انظر باب ما جاء من دعاء النبيّ صلى الله عليه وسلم في السكتين بعد التكبير.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (771)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Prophet ﷺ used to say when he bowed: “O Allah, to You I have bowed; in You I have believed; to You I have submitted. My hearing, my sight, my mind, my bones, and my nerves have humbled themselves to You.” And when he prostrated he would say: “O Allah, to You I have prostrated; in You I have believed; to You I have submitted. My face has prostrated to the One who created it and formed it, and split open its hearing and its sight. Blessed is Allah, the best of creators.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (771)."},{"num":2129,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ قَالَ: قُمْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً فَقَامَ فَقَرَأَ سُورَةَ الْبَقَرَةِ لَا يَمُرُّ بِآيَةِ رَحْمَةٍ إِلَّا وَقَفَ فَسَأَلَ، وَلَا يَمُرُّ بِآيَةِ عَذَابٍ إِلَّا وَقَفَ فَتَعَوَّذَ، قَالَ: ثُمَّ رَكَعَ بِقَدْرِ قِيَامِهِ يَقُولُ فِي رُكُوعِهِ: سُبْحَانَ ذِي الْجَبَرُوتِ وَالْمَلَكُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ، ثُمَّ سَجَدَ بِقَدْرِ قِيَامِهِ، ثُمَّ قَالَ فِي سُجُودِهِ مِثْلَ ذَلِكَ، ثُمَّ قَامَ فَقَرَأَ بِآلِ عِمْرَانَ، ثُمَّ قَرَأَ سُورَةً سُورَةً."],"takhrij":"حسن: رواه أبو داود (873)، والنسائي (1132) والترمذي في الشمائل (306) كلهم من طريق معاوية بن صالح، عن عمرو بن قيس الكندي، يقول: سمعت عاصم بن حميد، يقول سمعت عوف بن مالك يقول: فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (873), al-Nasa’i (1132), al-Tirmidhi in al-Shama’il (306)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["‘Awf ibn Malik al-Ashja‘i said: I stood with the Messenger of Allah ﷺ one night. He stood and recited Surat al-Baqarah, pausing at every verse of mercy to ask (Allah) and at every verse of punishment to seek refuge. Then he bowed for about as long as he had been standing, saying in his bowing: “Glory be to the One of might, dominion, majesty, and greatness.” Then he prostrated for about as long as he had been standing and said the same in his prostration. Then he stood and recited Al ‘Imran, then recited surah by surah."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11004,13159],"tks":"حسن: رواه أبو داود (873)، النسائي (1132)، الترمذي في الشمائل (306)."},{"num":2130,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي سُجُودِهِ: اللَّهُمَّ لَكَ سَجَدْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ وَأَنْتَ رَبِّي سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ."],"takhrij":"صحيح: رواه النسائي (1127) عن يحيى بن عثمان قال: أخبرنا أبو حيوة، قال: حدثنا شعيب بن أبي حمزة، عن محمد بن المنكدر، عن جابر بن عبدالله، عن النبي صلى الله عليه وسلم فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (1127)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that the Prophet ﷺ used to say in his prostration: “O Allah, to You I have prostrated; in You I have believed; to You I have submitted; and You are my Lord. My face has prostrated to the One who created it and formed it, and split open its hearing and its sight. Blessed is Allah, the best of creators.”"]}},"tuhfa":{},"full":1,"rep":[11006],"tks":"صحيح: رواه النسائي (1127)."},{"num":2131,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَكَعَ قَالَ: اللَّهُمَّ لَكَ رَكَعْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ وَعَلَيْكَ تَوَكَّلْتُ أَنْتَ رَبِّي خَشَعَ سَمْعِي وَبَصَرِي وَدَمِي وَلَحْمِي وَعَظْمِي وَعَصَبِي لِلَّهِ رَبِّ الْعَالِمِينَ."],"takhrij":"صحيح: رواه النسائي (1051) عن يحيى بن عثمان الحمصي، حدثنا أبو حيوة، حدثنا شُعيب، عن محمد بن المنكدر، عن جابر بن عبدالله فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (1051)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that when the Prophet ﷺ bowed, he would say: “O Allah, to You I have bowed; in You I have believed; to You I have submitted; and upon You I have relied. You are my Lord. My hearing, my sight, my blood, my flesh, my bones, and my nerves have humbled themselves to Allah, Lord of all worlds.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11005],"tks":"صحيح: رواه النسائي (1051)."},{"num":2132,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُسَبِّحُ فِي رُكُوعِهِ: سُبْحَانَ رَبِّيَ الْعَظِيمِ ثَلاثًا، وَفِي سُجُودِهِ: سُبْحَانَ رَبِّيَ الأَعْلَى."],"takhrij":"حسن: رواه البزار -كشف الأستار (538) عن محمد بن صالح بن العوَّام، عن عبدالرحمن بن بكار بن عبد العزيز بن أبي بكرة، عن أبيه، عن جده، عن أبي بكرة فذكره.","grade":"حسن","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Bazzar in Kashf al-Astar (538)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Abu Bakrah reported that the Messenger of Allah ﷺ used to glorify in his bowing “Glory be to my Lord, the Magnificent” three times, and in his prostration “Glory be to my Lord, the Most High.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (538)."},{"num":2133,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى، فَلَمَّا رَكَعَ قَالَ: سُبْحَانَ اللهِ وَبِحَمْدِهِ ثَلَاثَ مَرَّاتٍ، ثُمَّ رَفَعَ رَأْسَهُ."],"takhrij":"حسن: رواه الطبراني في الكبير (3422)، وأحمد (22906) كلاهما من طرق عن عبد الحميد بن بهرام الفزاري، عن شهر بن حوشب، عن عبد الرحمن بن غنم، عن أبي مالك الأشعري فذكره. والسياق للطبراني، وسياق أحمد أطول.","grade":"حسن","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Kabir (3/321) and Ahmad (22906) — al-Tabarani’s wording; Ahmad’s version is longer","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Abu Malik al-Ash‘ari reported that the Messenger of Allah ﷺ prayed, and when he bowed he said: “Glory be to Allah and with His praise” three times, then raised his head."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الكبير (3422)، وأحمد (22906)، واللفظ للطبراني، ورواية أحمد أطول."},{"num":2134,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا رَكَعَ سُبْحَانَ رَبِّيَ الْعَظِيمِ ثَلَاثَ مَرَّاتٍ، وَإِذَا سَجَدَ قَالَ: سُبْحَانَ رَبِّيَ الْأَعْلَى ثَلَاثَ مَرَّاتٍ."],"takhrij":"حسن: رواه ابن ماجة (888) عن محمد بن رُمْح المِصري قال: أنبأنا ابن لَهيعة، عن عبيدالله بن أبي جعفر، عن أبي الأزهر، عن حذيفة فذكره.","grade":"حسن","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good\nIbn Majah (888), Ibn Khuzaymah (604)","chapter_en":"What is said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Hudhayfah ibn al-Yaman said that he heard the Messenger of Allah ﷺ say when bowing: “Glory be to my Lord, the Magnificent” three times; and when prostrating: “Glory be to my Lord, the Most High” three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (888)، ابن خزيمة (604)."},{"num":2135,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قال: بِتُّ عِنْدَ خَالَتِي مَيْمُونَةَ بِنْتِ الْحَارِثِ وَبَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَهَا فَرَأَيْتُهُ قَامَ لِحَاجَتِهِ فَأَتَى الْقِرْبَةَ فَحَلَّ شِنَاقَهَا، ثُمَّ تَوَضَّأَ وُضُوءًا بَيْنَ الْوُضُوءَيْنِ، ثُمَّ أَتَى فِرَاشَهُ فَنَامَ، ثُمَّ قَامَ قَوْمَةً أُخْرَى فَأَتَى الْقِرْبَةَ فَحَلَّ شِنَاقَهَا، ثُمَّ تَوَضَّأَ وُضُوءًا هُوَ الْوُضُوءُ، ثُمَّ قَامَ يُصَلِّي وَكَانَ يَقُولُ فِي سُجُودِهِ: اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا وَاجْعَلْ فِي سَمْعِي نُورًا وَاجْعَلْ فِي بَصَرِي نُورًا وَاجْعَلْ مِنْ تَحْتِي نُورًا وَاجْعَلْ مِنْ فَوْقِي نُورًا وَعَنْ يَمِينِي نُورًا وَعَنْ يَسَارِي نُورًا وَاجْعَلْ أَمَامِي نُورًا وَاجْعَلْ خَلْفِي نُورًا وَأَعْظِمْ لِي نُورًا، ثُمَّ نَامَ حَتَّى نَفَخَ فَأَتَاهُ بِلَالٌ فَأَيْقَظَهُ لِلصَّلَاةِ."],"takhrij":"صحيح: رواه النسائي (1120) عن هنَّاد بن السري، عن أبي الأحوص، عن سعيد بن مسروق، عن سلمة بن كُهيل، عن رِشْدين، وهو كريب مولى ابن عباس، عن ابن عباس فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء من أدعية الركوع والسجود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (1120)","chapter_en":"Supplications said in bowing and prostration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":25,"content":{"translation":{"en":["Ibn ‘Abbas said: I spent the night at the home of my maternal aunt Maymunah bint al-Harith, and the Messenger of Allah ﷺ spent the night with her. I saw him get up for a need, then he came to the water-skin and untied its strap, performed a moderate ablution—not excessive, yet complete, then returned to his bed and slept. Then he got up again, came to the water-skin and untied it, then performed a complete ablution. Then he stood and prayed, and in his prostration he would say: “O Allah, place light in my heart; place light in my hearing; place light in my sight; place light beneath me; place light above me; place light on my right; place light on my left; place light in front of me; place light behind me; and greatly increase light for me.” Then he slept until he was breathing deeply, and Bilal came and woke him for prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11007],"tks":"صحيح: رواه النسائي (1120)."},{"num":2136,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: إِنِّي لَا آلُو أَنْ أُصَلِّيَ بِكُمْ كَمَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِنَا، قَالَ ثَابِتٌ: كَانَ أَنَسُ يَصْنَعُ شَيْئًا لَمْ أَرَكُمْ تَصْنَعُونَهُ، كَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَامَ حَتَّى يَقُولَ الْقَائِلُ قَدْ نَسِيَ، وَبَيْنَ السَّجْدَتَيْنِ حَتَّى يَقُولَ الْقَائِلُ قَدْ نَسِيَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (821)، ومسلم في الصلاة (472) كلاهما من طريق حماد بن زيد، عن ثابت، عن أنس واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب المكث بين السجدتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (821), Muslim (472)","chapter_en":"Remaining briefly between the two prostrations","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":26,"content":{"translation":{"en":["Anas ibn Malik said: I do my utmost to pray with you as I saw the Prophet ﷺ pray with us. Thabit said: Anas used to do something I did not see you doing: when he raised his head from bowing, he would stand until someone would say: “He has forgotten,” and between the two prostrations he would remain until someone would say: “He has forgotten.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (821)، مسلم (472)."},{"num":2137,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ: يَقُولُ بَيْنَ السَّجْدَتَيْنِ: رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي."],"takhrij":"حسن: رواه ابن ماجة (897) من طريقين أحدهما عن علي بن محمد قال: حدثنا حفص بن غِياث، قال: حدثنا العلاء بن المسيب، عن عمرو بن مرة، عن طلحة بن يزيد، عن حذيفة فذكر مثله، وصحَّحه الحاكم (1003) على شرط الشيخين.","grade":"حسن","chapter_ar":"باب ما يقول بين السجدتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (897); al-Hakim authenticated it (1/271)","chapter_en":"What is said between the two prostrations","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":27,"content":{"translation":{"en":["Hudhayfah reported that the Prophet ﷺ used to say between the two prostrations: “My Lord, forgive me. My Lord, forgive me.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11016],"tks":"حسن: رواه ابن ماجه (897)، وصححه الحاكم (1003)."},{"num":2138,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ بَيْنَ السَّجْدَتَيْنِ: اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي."],"takhrij":"حسن: رواه أبو داود (850) واللفظ له، والترمذي (284)، وابن ماجة (898) كلهم من طريق كامل أبي العلاء، حدثني حبيب بن أبي ثابت، عن سعيد بن جُبير، عن ابن عباس فذكر مثله إلا أن ابن ماجة زاد فيه: في صلاة الليل، وزاد الترمذي: واجبرني، وقال: هذا حديث غريب. وروى بعضهم هذا الحديث عن كامل أبي العلاء مرسَلاً. انتهى.","grade":"حسن","chapter_ar":"باب ما يقول بين السجدتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (850), al-Tirmidhi (284), Ibn Majah (898)","chapter_en":"What is said between the two prostrations","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":27,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Prophet ﷺ used to say between the two prostrations: “O Allah, forgive me, have mercy on me, grant me well-being, guide me, and provide for me.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11015],"tks":"حسن: رواه أبو داود (850)، الترمذي (284)، ابن ماجه (898)."},{"num":2139,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ قَالَ: كَانَ رُكُوعُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسُجُودُهُ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ وَبَيْنَ السَّجْدَتَيْنِ قَرِيبًا مِنَ السَّوَاءِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (801)، ومسلم في الصلاة (471) كلاهما من طريق شعبة، عن الحكم، عن ابن أبي ليلى، عن البراء، واللفظ للبخاري، ولمسلم من طريق أبي عوانة، عن هلال بن أبي حُميد، عن عبدالرحمن بن أبي ليلى، عن البراء قال: رفَقْتُ الصلاة مع النبي صلى الله عليه وسلم فوجدت قيامَه فركعتَه فاعتدالَه بعد ركوعه، فسجدتَه، فجلستَه بين السجدتين، فسجدتَه، فجلستَه ما بين التسليم والانصراف، قريباً من السواء.","grade":"متفق عليه","chapter_ar":"باب ما جاء من التسوية بين أركان الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (801), Muslim (471/194)","chapter_en":"Equalizing the pillars of the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب ما جاء في الركوع والسجود","group_en":"Chapters on what has been narrated about bowing and prostration","part_no":9,"group_no":5,"chapter_no":28,"content":{"translation":{"en":["Al-Bara’ said: The bowing of the Prophet ﷺ, his prostration, his standing after rising from bowing, and his sitting between the two prostrations were close to being equal in length."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (801)، مسلم (471/194)."},{"num":2140,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا جَلَسَ فِي الصَّلَاةِ، وَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ، وَرَفَعَ إِصْبَعَهُ الْيُمْنَى، الَّتِي تَلِي الإِبْهَامَ، فَدَعَا بِهَا، وَيَدَهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى، بَاسِطُهَا عَلَيْهَا.","وَفِي رِوَايَةِ: كَانَ إِذَا قَعَدَ فِي التَّشَهُّدِ، وَضَعَ يَدَهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى، وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى رُكْبَتِهِ الْيُمْنَى، وَعَقَدَ ثَلَاثَةً وَخَمْسِينَ، وَأَشَارَ بِالسَّبَّابَةِ."],"takhrij":"صحيح: رواه مسلم في المساجد (580) الرواية الأولى من طريق عبد الرزاق، أخبرنا معمر، عن عبيدالله بن عمر، عن نافع، عن ابن عمر فذكره، والرواية من طريق حماد بن سلمة، عن أيوب، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب هيئة الجلوس في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (580)","chapter_en":"The manner of sitting for the testimony of faith","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Umar reported that when the Prophet ﷺ sat in prayer, he would place his hands on his knees, raise his right finger—the one next to the thumb—and supplicate with it, and place his left hand on his left knee, spreading it on it. In another narration: When he sat for the tashahhud, he placed his left hand on his left knee, his right hand on his right knee, formed the “fifty-three” hand position, and pointed with the index finger."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (580)."},{"num":2141,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَعَدَ فِي الصَّلَاةِ جَعَلَ قَدَمَهُ الْيُسْرَى بَيْنَ فَخِذِهِ وَسَاقِهِ، وَفَرَشَ قَدَمَهُ الْيُمْنَى، وَوَضَعَ يَدَهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى، وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى وَأَشَارَ بِإِصْبَعِهِ.","وَفِي رِوَايَةِ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَعَدَ يَدْعُو وَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَيَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى، وَأَشَارَ بِإِصْبَعِهِ السَّبَّابَةِ، وَوَضَعَ إِبْهَامَهُ عَلَى إِصْبَعِهِ الْوُسْطَى، وَيُلْقِمُ كَفَّهُ الْيُسْرَى رُكْبَتَهُ."],"takhrij":"صحيح: أخرجه مسلم في المساجد (579) الرواية الأولى من طريق عثمان بن حكيم، حدثني عامر بن عبدالله بن الزبير، عن أبيه فذكر مثله.","grade":"صحيح","chapter_ar":"باب هيئة الجلوس في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (579)","chapter_en":"The manner of sitting for the testimony of faith","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["‘Abdullah ibn al-Zubayr said: When the Messenger of Allah ﷺ sat in prayer, he would place his left foot between his thigh and shin, lay his right foot flat, place his left hand on his left knee, place his right hand on his right thigh, and gesture with his finger. In another narration: When the Messenger of Allah ﷺ sat to supplicate, he placed his right hand on his right thigh and his left hand on his left thigh, pointed with his index finger, placed his thumb on his middle finger, and placed his left palm firmly on his left knee."]},"buhuth":{"en":["The wording “laid his right foot flat” differs from the more common authentic descriptions that mention keeping the right foot upright; this could indicate he did it at times to show permissibility. Placing the left foot between the thigh and shin describes the tawarruk posture. As for the finger formations, the narration of Ibn ‘Umar and the narration of Ibn al-Zubayr describe two different ways that were practiced at different times."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2151],"tks":"صحيح: رواه مسلم (579)."},{"num":2142,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ عَبْدِ الرَّحْمَنِ الْمُعَاوِيِّ أَنَّهُ قَالَ: رَآنِي عَبْدُ اللَّهِ بْنُ عُمَرَ وَأَنَا أَعْبَثُ بِالْحَصْبَاءِ فِي الصَّلَاةِ فَلَمَّا انْصَرَفْتُ نَهَانِي وَقَالَ: اصْنَعْ كَمَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ، فَقُلْتُ: وَكَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ ؟ قَالَ: كَانَ إِذَا جَلَسَ فِي الصَّلَاةِ، وَضَعَ كَفَّهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَقَبَضَ أَصَابِعَهُ كُلَّهَا، وَأَشَارَ بِأُصْبُعِهِ الَّتِي تَلِي الْإِبْهَامَ، وَوَضَعَ كَفَّهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى. وَقَالَ: هَكَذَا كَانَ (رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ) يَفْعَلُ."],"takhrij":"صحيح: رواه مالك في الصلاة (48) عن مسلم بن أبي مريم، عن علي ابن عبدالرحمن المعاوِي به مثله، ورواه مسلم في المساجد (580،116) عن يحيى بن يحيى قال: قرأت على مالك به مثله.","grade":"صحيح","chapter_ar":"باب هيئة الجلوس في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (48), Muslim (580/116)","chapter_en":"The manner of sitting for the testimony of faith","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["‘Ali ibn ‘Abd al-Rahman al-Mu‘awi said: ‘Abdullah ibn ‘Umar saw me fiddling with pebbles during prayer. When I finished, he forbade me and said: “Do as the Messenger of Allah ﷺ used to do.” I said: “How did the Messenger of Allah ﷺ do?” He said: “When he sat in prayer, he would place his right palm (on his thigh), curl all his fingers, and point with the finger next to the thumb, and he would place his left palm on his left thigh.” Then he said: “This is how the Messenger of Allah ﷺ used to do.”"]}},"tuhfa":{},"full":1,"rep":[2154],"tks":"صحيح: رواه مالك (48)، مسلم (580/116)."},{"num":2143,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّهُ أَخْبَرَهُ، أَنَّهُ كَانَ يَرَى عَبْدَ اللَّهِ بْنَ عُمَرَ يَتَرَبَّعُ فِي الصَّلَاةِ إِذَا جَلَسَ، قَالَ: فَفَعَلْتُهُ وَأَنَا يَوْمَئِذٍ حَدِيثُ السِّنِّ فَنَهَانِي عَبْدُ اللَّهِ، وَقَالَ: إِنَّمَا سُنَّةُ الصَّلَاةِ أَنْ تَنْصِبَ رِجْلَكَ الْيُمْنَى، وَتَثْنِيَ رِجْلَكَ الْيُسْرَى فَقُلْتُ لَهُ: فَإِنَّكَ تَفْعَلُ ذَلِكَ، فَقَالَ: إِنَّ رِجْلَيَّ لَا تَحْمِلَانِي."],"takhrij":"صحيح: رواه مالك في الصلاة (51) عن عبدالرحمن بن القاسم، عن عبدالله بن عبدالله بن عمر فذكر مثله، ورواه البخاري في الأذان (827) عن عبدالله بن مسْلَمة، عن مالك به مثله.","grade":"صحيح","chapter_ar":"باب كيف الجلوس في التشهد الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (51), al-Bukhari (827)","chapter_en":"How to sit in the first testimony of faith","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn ‘Abdullah ibn ‘Umar said: He told me that he used to see ‘Abdullah ibn ‘Umar sit cross-legged in prayer when sitting. I did that while I was young, and ‘Abdullah forbade me and said: “The Sunnah of prayer is to keep your right foot upright and to fold your left foot.” I said: “But you do that (sit cross-legged).” He said: “My legs cannot carry me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (51)، البخاري (827)."},{"num":2144,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قال: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَأَيْتُهُ يَرْفَعُ يَدَيْهِ إِذَا افْتَتَحَ الصَّلَاةَ حَتَّى يُحَاذِيَ مَنْكِبَيْهِ، وَإِذَا أَرَادَ أَنْ يَرْكَعَ وَإِذَا جَلَسَ فِي الرَّكْعَتَيْنِ أَضْجَعَ الْيُسْرَى وَنَصَبَ الْيُمْنَى، وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَنَصَبَ أُصْبُعَهُ لِلدُّعَاءِ وَوَضَعَ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى قَالَ، ثُمَّ أَتَيْتُهُمْ مِنْ قَابِلٍ فَرَأَيْتُهُمْ يَرْفَعُونَ أَيْدِيَهُمْ فِي الْبَرَانِسِ."],"takhrij":"حسن: رواه النسائي (1159) عن محمد بن عبدالله بن يزيد المقرئ، قال: حدثنا سفيان، قال: حدثنا عاصم بن كليب، عن أبيه، عن وائل بن حجر فذكره.","grade":"حسن","chapter_ar":"باب كيف الجلوس في التشهد الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (1159)","chapter_en":"How to sit in the first testimony of faith","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Wa’il ibn Hujr said: I came to the Messenger of Allah ﷺ and saw him raise his hands when he began the prayer until they were level with his shoulders, and when he intended to bow. And when he sat after two units, he laid the left (foot) and kept the right upright, placed his right hand on his right thigh, raised his finger for supplication, and placed his left hand on his left thigh. He said: Then I came to them the following year and saw them raising their hands from their cloaks. In another narration: “Then he sat and sat on his left foot (iftirash).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1159)."},{"num":2145,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ، أَنَّهُ كَانَ جَالِسًا مَعَ نَفَرٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرْنَا صَلَاةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَبُو حُمَيْدٍ السَّاعِدِيُّ: أَنَا كُنْتُ أَحْفَظَكُمْ لِصَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، (فَذَكَرَ صِفَةٌ صَلَاة النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ) ثُمَّ قَالَ: فَإِذَا جَلَسَ فِي الرَّكْعَتَيْنِ جَلَسَ عَلَى رِجْلِهِ الْيُسْرَى وَنَصَبَ الْيُمْنَى، وَإِذَا جَلَسَ فِي الرَّكْعَةِ الْآخِرَةِ قَدَّمَ رِجْلَهُ الْيُسْرَى وَنَصَبَ الْأُخْرَى وَقَعَدَ عَلَى مَقْعَدَتِهِ."],"takhrij":"صحيح: رواه البخاري في الأذان (828) عن يحيى بن بكير، حدثنا الليث، عن خالد (وهو ابن يزيد) عن سعيد (وهو ابن أبي هلال)، عن محمد ابن عمرو بن حلْحلة، عن محمد بن عمرو بن عطاء فذكر الحديث. وسبق الحديث بالتفصيل في باب رفع اليدين عند الركوع وعند الرفع منه.","grade":"صحيح","chapter_ar":"باب كيف الجلوس في التشهد الثاني","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (828)","chapter_en":"How to sit in the second (final) testimony of faith","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Muhammad ibn ‘Amr ibn ‘Ata’ said: I was sitting with a group of the Companions of the Prophet ﷺ and we mentioned the prayer of the Prophet ﷺ. Abu Humayd al-Sa‘idi said: “I know the prayer of the Messenger of Allah ﷺ best.” He then described the prayer of the Prophet ﷺ and said: “When he sat after two units, he sat on his left foot and kept the right upright. And when he sat in the final unit, he brought the left foot forward, kept the other upright, and sat on his buttocks.”"]},"buhuth":{"en":["This indicates that the sitting posture in the first tashahhud differs from the posture in the final tashahhud: in the final sitting, one sits in tawarruk, seated on the buttocks leaning to the left side."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (828)."},{"num":2146,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: عَلَّمَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ التَّشَهُّدَ فِي وَسَطِ الصَّلَاةِ وَفِي آخِرِهَا، فَكُنَّا نَحْفَظُ عَنْ عَبْدِ اللَّهِ حِينَ أَخْبَرَنَا أَنَّ رَسُولَ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَّمَهُ إِيَّاهُ قَالَ: فَكَانَ يَقُولُ إِذَا جَلَسَ فِي وَسَطِ الصَّلَاةِ وَفِي آخِرِهَا عَلَى وَرِكِهِ الْيُسْرَى: التَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، قَالَ ثُمَّ إِنْ كَانَ فِي وَسَطِ الصَّلَاةِ نَهَضَ حِينَ يَفْرُغُ مِنْ تَشَهُّدِهِ، وَإِنْ كَانَ فِي آخِرِهَا، دَعَا بَعْدَ تَشَهُّدِهِ مَا شَاءَ اللَّهُ أَنْ يَدْعُوَ، ثُمَّ يُسَلِّمَ."],"takhrij":"حسن: رواه الإمام أحمد (4382) عن يعقوب، قال: حدّثني أبي، عن ابن إسحاق، قال: حَدِّثْني عن تشهّد رسول الله صلى الله عليه وسلم وفي آخرها عبدالرحمن بن الأسود بن يزيد النّخعيّ، عن أبيه، عن عبدالله، فذكر الحديث.","grade":"حسن","chapter_ar":"باب كيف الجلوس في التشهد الثاني","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (4382)","chapter_en":"How to sit in the second (final) testimony of faith","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: The Messenger of Allah ﷺ taught me the tashahhud in the middle of the prayer and at its end. We used to preserve from ‘Abdullah, when he informed us that the Messenger of Allah ﷺ had taught it to him, that he said: When he sat in the middle of the prayer and at its end, leaning on his left hip, he would say: “All greetings are for Allah, and prayers, and good things. Peace be upon you, O Prophet, and Allah’s mercy and blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god worthy of worship except Allah, and I bear witness that Muhammad is His servant and His Messenger.” He said: If it was in the middle of the prayer, he would rise after finishing his tashahhud; and if it was at the end, he would supplicate after the tashahhud with whatever Allah willed him to supplicate, then give the closing greetings."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (4382)."},{"num":2147,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَسْتَفْتِحُ الصَّلَاةَ (إلَى أَنْ ذَكَرَت): وَكَانَ يَقُولُ فِي كُلِّ رَكْعَتَيْنِ: التَّحِيَّةَ، وَكَانَ يَفْرِشُ رِجْلَهُ الْيُسْرَى، وَيَنْصِبُ رِجْلَهُ الْيُمْنَى، وَكَانَ يَنْهَى عَنْ عُقْبَةِ الشَّيْطَانِ... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (498) في سياق صفة صلاة النبي صلى الله عليه وسلم من طريق حسين المعلم، عن بُديل بن ميسرة، عن أبي الجوزاء، عن عائشة، فذكرت مثله.","grade":"صحيح","chapter_ar":"باب من قال بوجوب التشهد الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (498)","chapter_en":"Those who held the first tashahhud to be obligatory","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["The Mother of the Believers ‘A’ishah said: The Messenger of Allah ﷺ used to begin the prayer… and she mentioned (among other things) that he would recite the tashahhud in every two units, he would sit on his left foot and keep his right foot upright, and he would forbid “the devil’s sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (498)."},{"num":2148,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ بْنِ رَافِعٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ الْحَدِيثَ الْمَسِي صَلَاتُهُ وَقَالَ فِيهِ: فَإِذَا جَلَسْتَ فِي وَسَطِ الصَّلَاةِ فَاطْمَئِنَّ وَافْتَرِشْ فَخِذَكَ الْيُسْرَى ثُمَّ تَشَهَّدْ، ثُمَّ إِذَا قُمْتَ فَمِثْلَ ذَلِكَ حَتَّى تَفْرُغَ مِنْ صَلَاتِكَ."],"takhrij":"حسن: رواه أبو داود (860) حدثنا مؤمل بن هشام، ثنا إسماعيل، عن محمد بن إسحاق، حدثني علي بن يحيى بن خلاَّد بن رافع، عن أبيه، عن عمه رفاعة بن رافع فذكره. ومحمد بن إسحاق مدلس، ولكنه صرَّح بالتحديث.","grade":"حسن","chapter_ar":"باب من قال بوجوب التشهد الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (860)","chapter_en":"Those who held the first tashahhud to be obligatory","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Rifa‘ah ibn Rafi‘ reported that in the hadith of the one who prayed poorly, the Prophet ﷺ said: “When you sit in the middle of the prayer, be at ease, sit on your left thigh, then recite the tashahhud. Then when you stand, do likewise until you finish your prayer.”"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه أبو داود (860)."},{"num":2149,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: كُنَّا لَا نَدْرِي مَا نَقُولُ فِي كُلِّ رَكْعَتَيْنِ غَيْرَ أَنْ نُسَبِّحَ وَنُكَبِّرَ وَنَحْمَدَ رَبَّنَا وَإِنَّ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَّمَ فَوَاتِحَ الْخَيْرِ وَخَوَاتِمَهُ فَقَالَ: إِذَا قَعَدْتُمْ فِي كُلِّ رَكْعَتَيْنِ فَقُولُوا التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ وَلْيَتَخَيَّرْ أَحَدُكُمْ مِنَ الدُّعَاءِ أَعْجَبَهُ إِلَيْهِ فَلْيَدْعُ اللَّهَ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه النسائي (1163) قال: أخبرنا محمد بن المثنى، قال: حدثنا محمد قال: حدثنا شعبةُ قال: سمعت أبا إسحاق يحدث، عن أبي الأحوض، عن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب من قال بوجوب التشهد الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (1163).","chapter_en":"Those who held the first tashahhud to be obligatory","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported: “We did not know what to say after every two rakʿahs except that we would glorify Allah, declare His greatness, and praise our Lord. Muḥammad ﷺ was taught the beginnings and endings of all goodness, and he said: ‘When you sit after every two rakʿahs, say: All greetings belong to Allah, as do the prayers and all good things. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I testify that there is no deity worthy of worship except Allah, and I testify that Muḥammad is His servant and His Messenger. Then let each of you choose whichever supplication he likes best and supplicate to Allah, Mighty and Majestic, with it.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1163)."},{"num":2150,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ ابْنِ بُحَيْنَةَ، وَهُوَ مِنْ أَزْدِ شَنُوءَةَ وَهُوَ حَلِيفٌ لِبَنِي عَبْدِ مَنَافٍ، وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِهِمُ الظَّهْرَ فَقَامَ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ لَمْ يَجْلِسْ فَقَامَ النَّاسُ مَعَهُ حَتَّى إِذَا قَضَى الصَّلَاةَ وَانْتَظَرَ النَّاسُ تَسْلِيمَهُ كَبَّرَ وَهُوَ جَالِسٌ، فَسَجَدَ سَجْدَتَيْنِ قَبْلَ أَنْ يُسَلِّمَ ثُمَّ سَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (829) ومسلم في المساجد (570) كلاهما من حديث ابن شهاب، قال: حدثني عبدالرحمن بن هرمز الأعرج، مولى بني عبدالمطلب، قال مرة: مولى ربيعة بن الحارث، عن عبدالله بن بُحينة الأسدي، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب من لم ير وجوب التشهد الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (829), Muslim (570)","chapter_en":"Those who did not consider the first tashahhud obligatory","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["‘Abdullah ibn Buhaynah—who was from Azd Shanu’ah, an ally of Banu ‘Abd Manaf, and a Companion of the Prophet ﷺ—reported that the Prophet ﷺ led them in the noon prayer. He stood up after the first two units and did not sit (for the first tashahhud), so the people stood with him. When he finished the prayer and the people awaited his closing greetings, he said “Allāhu akbar” while seated, then performed two prostrations before giving the closing greetings, then he gave the closing greetings."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (829)، مسلم (570)."},{"num":2151,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَعَدَ فِي الصَّلَاةِ جَعَلَ قَدَمَهُ الْيُسْرَى بَيْنَ فَخِذِهِ وَسَاقِهِ، وَفَرَشَ قَدَمَهُ الْيُمْنَى، وَوَضَعَ يَدَهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى، وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى وَأَشَارَ بِإِصْبَعِهِ.","وَفِي رِوَايَةِ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَعَدَ يَدْعُو وَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَيَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى، وَأَشَارَ بِإِصْبَعِهِ السَّبَّابَةِ، وَوَضَعَ إِبْهَامَهُ عَلَى إِصْبَعِهِ الْوُسْطَى، وَيُلْقِمُ كَفَّهُ الْيُسْرَى رُكْبَتَهُ."],"takhrij":"صحيح: أخرجه مسلم في المساجد (579) الرواية الأولى من طريق عثمان بن حكيم، حدثني عامر بن عبدالله بن الزبير، عن أبيه فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في الإشارة بالسبابة في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (579). Also narrated by Abu Dawud (989), al-Nasa’i (1270), al-Bayhaqi (2/131). A wording adds: “He would point with his finger when he supplicated and would not move it.”","chapter_en":"Reports about pointing with the index finger in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["‘Abdullah ibn al-Zubayr said: When the Messenger of Allah ﷺ sat in prayer, he would place his left foot between his thigh and shin, lay his right foot flat, place his left hand on his left knee, place his right hand on his right thigh, and gesture with his finger. In another narration: When he sat to supplicate, he placed his right hand on his right thigh and his left hand on his left thigh, pointed with his index finger, placed his thumb on his middle finger, and placed his left palm firmly on his knee."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2141],"tks":"صحيح: رواه مسلم (579)، ورواه أيضا أبو داود (989)، والنسائي (1270)، والبيهقي (2783)، وفي لفظ: «كان يشير بإصبعه إذا دعا ولا يحركها»."},{"num":2152,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَعَدَ فِي التَّشَهُّدِ وَضَعَ يَدَهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى، وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى رُكْبَتِهِ الْيُمْنَى، وَعَقَدَ ثَلَاثَةً وَخَمْسِينَ، وَأَشَارَ بِالسَّبَّابَةِ."],"takhrij":"صحيح: رواه مسلم في المساجد (580) من طريق حمَّاد بن سلمة، عن أيُّوب، عن نافع، عن ابن عمر فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في الإشارة بالسبابة في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (580)","chapter_en":"Reports about pointing with the index finger in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Ibn ‘Umar reported that when the Prophet ﷺ sat in the tashahhud, he placed his left hand on his left knee, placed his right hand on his right knee, formed the “fifty-three” hand position, and pointed with the index finger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (580)."},{"num":2153,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا جَلَسَ فِي الصَّلَاةِ وَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ، وَرَفَعَ إِصْبَعَهُ الْيُمْنَى الَّتِي تَلِي الإِبْهَامَ فَدَعَا بِهَا، وَيَدَهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى، بَاسِطُهَا عَلَيْهَا."],"takhrij":"صحيح: رواه مسلم في الصّلاة (580) من طرق عن عبد الرزّاق، أخبرنا معمر، عن عبيدالله بن عمر، عن نافع، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الإشارة بالسبابة في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (580)","chapter_en":"Reports about pointing with the index finger in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Ibn ‘Umar reported that when the Prophet ﷺ sat in prayer, he placed his hands on his knees, raised the right finger next to the thumb and supplicated with it, and placed his left hand on his left knee, spreading it upon it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (580)."},{"num":2154,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ عَبْدِ الرَّحْمَنِ الْمُعَاوِيِّ أَنَّهُ قَالَ: رَآنِي عَبْدُ اللَّهِ بْنُ عُمَرَ وَأَنَا أَعْبَثُ بِالْحَصْبَاءِ فِي الصَّلَاةِ فَلَمَّا انْصَرَفْتُ نَهَانِي وَقَالَ: اصْنَعْ كَمَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ، فَقُلْتُ: وَكَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ ؟ قَالَ: كَانَ إِذَا جَلَسَ فِي الصَّلَاةِ، وَضَعَ كَفَّهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَقَبَضَ أَصَابِعَهُ كُلَّهَا، وَأَشَارَ بِأُصْبُعِهِ الَّتِي تَلِي الْإِبْهَامَ، وَوَضَعَ كَفَّهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى . وَقَالَ: هَكَذَا كَانَ (رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ) يَفْعَلُ."],"takhrij":"صحيح: رواه مالك في الصلاة (48) عن مسلم بن أبي مريم، عن علي ابن عبدالرحمن المعاوِي به مثله، ورواه مسلم في المساجد (580،116) عن يحيى بن يحيى قال: قرأت على مالك به مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في الإشارة بالسبابة في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (48), Muslim (580/116)","chapter_en":"Reports about pointing with the index finger in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["‘Ali ibn ‘Abd al-Rahman al-Mu‘awi said: ‘Abdullah ibn ‘Umar saw me playing with pebbles in prayer. When I finished, he forbade me and said: “Do as the Messenger of Allah ﷺ used to do.” I said: “How did the Messenger of Allah ﷺ do?” He said: “When he sat in prayer, he would place his right palm on his right thigh, curl all his fingers, and point with the finger next to the thumb; and he would place his left palm on his left thigh.” Then he said: “This is how the Messenger of Allah ﷺ used to do.”"]}},"tuhfa":{},"full":1,"rep":[2142],"tks":"صحيح: رواه مالك (48)، مسلم (580/116)."},{"num":2155,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ قَالَ: كَانَ عَبْدُ اللَّهِ بْنُ عُمَرَ إِذَا جَلَسَ فِي الصَّلَاةِ وَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ، وَأَشَارَ بِإِصْبَعِهِ، وَأَتْبَعَهَا بَصَرَهُ، ثُمَّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَهِيَ أَشَدُّ عَلَى الشَّيْطَانِ مِنَ الْحَدِيدِ، يَعْنِي السَّبَّابَةَ."],"takhrij":"حسن: رواه الإمام أحمد (6000) والبزار - كشف الأستار (563) كلاهما من طريق محمد بن عبدالله أبي أحمد الزبيري، حدثنا كثير بن زيد، عن نافع، فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في الإشارة بالسبابة في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (6000), al-Bazzar in Kashf al-Astar (563)","chapter_en":"Reports about pointing with the index finger in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Nafi‘ said: When ‘Abdullah ibn ‘Umar sat in prayer, he would place his hands on his knees, point with his finger, and follow it with his gaze. Then he said: The Messenger of Allah ﷺ said: “It is more severe upon Satan than iron,” meaning the index finger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6000)، البزار في كشف الأستار (563)."},{"num":2156,"demo":false,"sanad":"","matn":["عَنْ عَبَّاسِ بْنِ سَهْلٍ السَّاعِدِيِّ قَالَ: اجْتَمَعَ أَبُو حُمَيْدٍ، وَأَبُو أُسَيْدٍ، وَسَهْلُ بْنُ سَعْدٍ، وَمُحَمَّدُ بْنُ مَسْلَمَةَ، فَذَكَرُوا صَلَاةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَبُو حُمَيْدٍ: أَنَا أَعْلَمُكُمْ بِصَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ صِفَةٌ صَلَاة رَسُولَ اللَّهِ وَقَالَ فِيهِ: فَافْتَرَشَ رِجْلَهُ الْيُسْرَى، وَأَقْبَلَ بِصَدْرِ الْيُمْنَى عَلَى قِبْلَتِهِ، وَوَضَعَ كَفَّهُ الْيُمْنَى عَلَى رُكْبَتِهِ الْيُمْنَى وَكَفَّهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى، وَأَشَارَ بِأُصْبُعِهِ يَعْنِي السَّبَّابَةَ."],"takhrij":"حسن: رواه أبو داود (734) والترمذي (293) كلاهما من طريق أبي عامر العقدي هو عبدالملك بن عمرو، أخبرني فُلَيح بن سليمان المدني، حدَّثنا عبَّاس بن سهل فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الإشارة بالسبابة في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (734), al-Tirmidhi (293) — al-Tirmidhi said: “Hasan Sahih”","chapter_en":"Reports about pointing with the index finger in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["‘Abbas ibn Sahl al-Sa‘idi said: Abu Humayd, Abu Usayd, Sahl ibn Sa‘d, and Muhammad ibn Maslamah gathered and discussed the prayer of the Messenger of Allah ﷺ. Abu Humayd said: “I know the prayer of the Messenger of Allah ﷺ best…” and in it he said: He would sit on his left foot, face the direction of prayer with his right foot, place his right palm on his right knee and his left palm on his left knee, and point with his finger—meaning the index finger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (734)، والترمذي (293)، وقال الترمذي: حسن صحيح."},{"num":2157,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ، أَنَّهُ ذَكَرَ صِفَةٌ صَلَاة النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَاءَ فِيهِ: ثُمَّ جَلَسَ فَافْتَرَشَ رِجْلَهُ الْيُسْرَى وَوَضَعَ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى وَحَدَّ مِرْفَقَهُ الْأَيْمَنَ عَلَى فَخِذِهِ الْيُمْنَى وَقَبَضَ ثِنْتَيْنِ وَحَلَّقَ حَلْقَةً، وَرَأَيْتُهُ يَقُولُ هَكَذَا: وَحَلَّقَ بِشْرٌ الْإِبْهَامَ وَالْوُسْطَى وَأَشَارَ بِالسَّبَّابَةِ."],"takhrij":"حسن: رواه أبو داود (726) واللفظ له، والنسائي (1267) وابن ماجه (867) كلهم من طريق بشر بن المفضل، عن عاصم بن كُلَيب، عن أبيه، عن وائل بن حجر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الإشارة بالسبابة في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (726) — wording his; al-Nasa’i (1265); Ibn Majah (867)","chapter_en":"Reports about pointing with the index finger in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Wa’il ibn Hujr described the prayer of the Prophet ﷺ, and in it: Then he sat and sat on his left foot, placed his left hand on his left thigh, placed his right elbow on his right thigh, folded two fingers, formed a circle, and I saw him do it like this. Bishr formed the circle with the thumb and middle finger, and he pointed with the index finger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (726)، واللفظ له، النسائي (1267)، ابن ماجه (867)."},{"num":2158,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ قَالَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَعَدَ فِي التَّشَهُّدِ، وَضَعَ كَفَّهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى، وَأَشَارَ بِالسَّبَّابَةِ لَا يُجَاوِزُ بَصَرُهُ إِشَارَتَهُ."],"takhrij":"حسن: رواه أبو داود (990)، والنسائي (1275) كلاهما من طريق يحيى","grade":"حسن","chapter_ar":"باب موضع البصر عند الإشارة بالسبابة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (990), al-Nasa’i (1275)","chapter_en":"Where the gaze should be when pointing with the index finger","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["‘Abdullah ibn al-Zubayr said: When the Prophet ﷺ sat for the tashahhud, he placed his left palm on his left thigh and pointed with the index finger; his gaze would not go beyond where he was pointing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (990)، النسائي (1275)."},{"num":2159,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: مَرَّ عَلَيَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَدْعُو بِأُصْبُعَيَّ فَقَالَ: أَحِّدْ أَحِّدْ وَأَشَارَ بِالسَّبَّابَةِ."],"takhrij":"صحيح: رواه أبو داود (1499)، والنسائي (1273) كلاهما من طريق أبي معاوية، قال: حدثنا الأعمش، عن أبي صالح، عن سعد بن أبي وقاص فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن الإشارة بإصبعين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (1499), al-Nasa’i (1273)","chapter_en":"Prohibition of pointing with two fingers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: The Prophet ﷺ passed by me while I was supplicating with two fingers, and he said: “Make it one, make it one,” and he pointed with the index finger."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10907],"tks":"صحيح: رواه أبو داود (1499)، النسائي (1273)."},{"num":2160,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَجُلًا كَانَ يَدْعُو بِأُصْبُعَيْهِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَحِّدْ أَحِّدْ."],"takhrij":"حسن: رواه النسائي (1272)، والترمذي (3557) كلاهما عن محمد بن بشار، ثنا صفوان بن عيسى، قال: حدثنا محمد بن عجلان، عن القعقاع، عن أبي صالح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الإشارة بإصبعين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (1272), al-Tirmidhi (3557) — he said: “Hasan Sahih Gharib”","chapter_en":"Prohibition of pointing with two fingers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that a man was supplicating with two fingers, so the Messenger of Allah ﷺ said: “Make it one, make it one.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1272)، والترمذي (3557)، وقال: حسن صحيح غريب."},{"num":2161,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: مِنَ السُّنَّةِ أَنْ يُخْفِيَ التَّشَهُّدَ."],"takhrij":"حسن: رواه أبو داود (986)، والترمذي (291) كلاهما من طريق يونس بن بكير، عن محمد بن إسحاق، عن عبدالرحمن بن الأسود، عن أبيه، عن عبدالله بن مسعود، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إخفاء التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (986), al-Tirmidhi (291), al-Hakim (1/230) — al-Tirmidhi said: “Hasan Gharib”","chapter_en":"Keeping the tashahhud quiet","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: “It is from the Sunnah to keep the tashahhud quiet.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (986)، والترمذي (291)، والحاكم (275)، وقال الترمذي: حسن غريب."},{"num":2162,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: كُنَّا إِذَا صَلَّيْنَا خَلْفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قُلْنَا السَّلَامُ عَلَى جِبْرِيلَ، وَمِيكَائِيلَ، السَّلَامُ عَلَى فُلَانٍ وَفُلَانٍ، فَالْتَفَتَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ اللَّهَ هُوَ السَّلَامُ، فَإِذَا صَلَّى أَحَدُكُمْ فَلْيقُلِ التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، فَإِنَّكُمْ إِذَا قُلْتُمُوهَا أَصَابَتْ كُلَّ عَبْدٍ لِلَّهِ صَالِحٍ فِي السَّمَاءِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (831) عن أبي نعيم، قال: حدثنا الأعمش، عن شقيق بن سلمة، قال: قال عبدالله فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيغ التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (831), Muslim (402)","chapter_en":"Forms of the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Ibn Mas‘ud said: When we prayed behind the Prophet ﷺ, we used to say: “Peace be upon Jibril and Mika’il; peace be upon so-and-so and so-and-so.” The Messenger of Allah ﷺ turned to us and said: “Indeed Allah is al-Salam. So when one of you prays, let him say: All greetings are for Allah, and prayers, and good things. Peace be upon you, O Prophet, and Allah’s mercy and blessings. Peace be upon us and upon the righteous servants of Allah—when you say it, it reaches every righteous servant of Allah in the heavens and the earth. I bear witness that there is no god worthy of worship except Allah, and I bear witness that Muhammad is His servant and His Messenger.”"]},"intro":{"ar":["تشهد ابن مسعود"],"en":["The Tashahhud of Ibn Mas‘ud"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (831)، مسلم (402)."},{"num":2163,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا التَّشَهُّدَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ، فَكَانَ يَقُولُ: التَّحِيَّاتُ الْمُبَارَكَاتُ، الصَّلَوَاتُ الطَّيِّبَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (403) عن قتيبة بن سعيد، حدثنا ليث (هو ابن سعد) عن أبي الزبير، عن سعيد بن جبير وعن طاوس، عن ابن عباس فذكره، وذكر له وجهاً آخر عن عبدالرحمن بن حميد، حدثني أبو الزبير، عن طاوس، عن ابن عباس به، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في صيغ التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (403)","chapter_en":"Forms of the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ used to teach us the tashahhud as he taught us a surah of the Qur’an. He would say: “All greetings, blessed greetings, prayers, and good things are for Allah. Peace be upon you, O Prophet, and Allah’s mercy and blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god worthy of worship except Allah, and I bear witness that Muhammad is the Messenger of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11018],"tks":"صحيح: رواه مسلم (403)."},{"num":2164,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ قَالَ: إن رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَنَا فَبَيَّنَ لَنَا سُنَّتَنَا، وَعَلَّمَنَا صَلَاتَنَا فَقَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): وَإِذَا كَانَ عِنْدَ الْقَعْدَةِ فَلْيَكُنْ مِنْ أَوَّلِ قَوْلِ أَحَدِكُمْ: التَّحِيَّاتُ الطَّيِّبَاتُ الصَّلَوَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (404) عن حِطّان بن عبدالله الرقاشي قال: صليتُ مع أبي موسى الأشعري صلاة، ثم ذكر حديثا طويلاً ومنه هذا.","grade":"صحيح","chapter_ar":"باب ما جاء في صيغ التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (404)","chapter_en":"Forms of the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ delivered a sermon to us, clarified our Sunnah, and taught us our prayer. He said: “When you are at the sitting, let the first of what one of you says be: All greetings, good things, and prayers are for Allah. Peace be upon you, O Prophet, and Allah’s mercy and blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god worthy of worship except Allah, and I bear witness that Muhammad is His servant and His Messenger.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (404)."},{"num":2165,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي التَّشَهُّدِ: التَّحِيَّاتُ لِلَّهِ الصَّلَوَاتُ الطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. قَالَ: قَالَ ابْنُ عُمَرَ: زِدْتَ فِيهَا وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ. قَالَ ابْنُ عُمَرَ: زِدْتُ فِيهَا وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."],"takhrij":"صحيح: رواه أبو داود (971) عن نصر بن علي، حدثني أبي، حدثنا شعبة، عن أبي بشر، سمعتُ مجاهداً يحدث عن ابن عمر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في صيغ التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (971)","chapter_en":"Forms of the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Ibn ‘Umar narrated from the Messenger of Allah ﷺ regarding the tashahhud: “All greetings are for Allah; prayers and good things; peace be upon you, O Prophet, and Allah’s mercy.” Ibn ‘Umar said: I added “and His blessings.” “Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god worthy of worship except Allah.” Ibn ‘Umar said: I added “alone with no partner.” “And I bear witness that Muhammad is His servant and His Messenger.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11020],"tks":"صحيح: رواه أبو داود (971)."},{"num":2166,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ الْقَارِيِّ أَنَّهُ سَمِعَ عُمَرَ بْنَ الْخَطَّابِ يُعَلِّمُ النَّاسَ التَّشَهُّدِ عَلَى الْمِنْبَرِ فَيَقُولُ: قُولُوا: التَّحِيَّاتُ لِلَّهِ الزَّاكِيَّاتُ لِلَّهِ الطَّيِّبَاتُ لِلَّهِ، الصَّلَوَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."],"takhrij":"صحيح: رواه مالك في الصلاة (57) عن ابن شهاب، عن عروة بن الزبير، عن عبدالرحمن بن عبد القاري، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في صيغ التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (57)","chapter_en":"Forms of the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["‘Abd al-Rahman ibn ‘Abd al-Qari said that he heard ‘Umar ibn al-Khattab teaching the people the tashahhud from the pulpit, saying: “Say: All greetings are for Allah; the purifying deeds are for Allah; the good things are for Allah; the prayers are for Allah. Peace be upon you, O Prophet ﷺ, and Allah’s mercy and blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god worthy of worship except Allah, and I bear witness that Muhammad is His servant and His Messenger.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (57)."},{"num":2167,"demo":false,"sanad":"","matn":["عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ أَنَّهُ أَخْبَرَهُ، أَنَّ عَائِشَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَانَتْ تَقُولُ إِذَا تَشَهَّدَتْ: التَّحِيَّاتُ الطَّيِّبَاتُ الصَّلَوَاتُ الزَّاكِيَاتُ لِلَّهِ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ . السَّلَامُ عَلَيْكُمْ."],"takhrij":"صحيح: رواه مالك في الصلاة (59، 60) من وجهين عن عبدالرحمن ابن القاسم، ويحيى بن سعيد الأنصاري كلاهما عن القاسم بن محمد، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في صيغ التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (59, 60)","chapter_en":"Forms of the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Al-Qasim ibn Muhammad reported that ‘A’ishah, the wife of the Prophet ﷺ, used to say when she recited the tashahhud: “All greetings and good things; and the purifying prayers are for Allah. I bear witness that there is no god worthy of worship except Allah alone with no partner, and I bear witness that Muhammad is His servant and His Messenger. Peace be upon you, O Prophet, and Allah’s mercy and blessings. Peace be upon us and upon the righteous servants of Allah. Peace be upon you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11022],"tks":"صحيح: رواه مالك (59، 60)."},{"num":2168,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ، كَيْفَ نُصَلِّي عَلَيْكَ ؟ فَقَالَ: قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (66) عن عبدالله بن أبي بكر بن حزم، عن أبيه، عن عمرو بن سُلَيم الزرقي، أنه قال: أخبرني أبو حُميد الساعدي فذكره.","grade":"متفق عليه","chapter_ar":"باب الصلاة على النبي في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (66), al-Bukhari (3369), Muslim (407)","chapter_en":"Sending prayers upon the Prophet ﷺ in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Abu Humayd al-Sa‘idi said: They said: “O Messenger of Allah ﷺ, how should we send prayers upon you?” He said: “Say: O Allah, send prayers upon Muhammad, his wives, and his offspring, as You sent prayers upon the family of Ibrahim. And bless Muhammad, his wives, and his offspring, as You blessed the family of Ibrahim. Indeed, You are Praiseworthy, Glorious.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10856],"tks":"متفق عليه: رواه مالك (66)، البخاري (3369)، مسلم (407)."},{"num":2169,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ أَنَّهُ قَالَ: أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَجْلِسِ سَعْدِ بْنِ عُبَادَةَ، فَقَالَ لَهُ بَشِيرُ بْنُ سَعْدٍ: أَمَرَنَا اللَّهُ أَنْ نُصَلِّيَ عَلَيْكَ يَا رَسُولَ اللَّهِ، فَكَيْفَ نُصَلِّي عَلَيْكَ ؟ قَالَ: فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى تَمَنَّيْنَا أَنَّهُ لَمْ يَسْأَلْهُ، ثُمَّ قَالَ: قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ، إِنَّكَ حَمِيدٌ مَجِيدٌ وَالسَّلَامُ كَمَا قَدْ عَلِمْتُمْ."],"takhrij":"صحيح: رواه مالك في قصر الصلاة (67) عن نعيم بن عبدالله المُجْمِر، عن محمد بن عبدالله بن زيد، أنه أخبره عن أبي مسعود الأنصاري فذكر مثله.","grade":"صحيح","chapter_ar":"باب الصلاة على النبي في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (67), Muslim (405)","chapter_en":"Sending prayers upon the Prophet ﷺ in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Abu Mas‘ud al-Ansari said: The Messenger of Allah ﷺ came to us in the gathering of Sa‘d ibn ‘Ubadah. Bashir ibn Sa‘d said to him: “Allah has commanded us to send prayers upon you, O Messenger of Allah. How should we send prayers upon you?” The Messenger of Allah ﷺ remained silent until we wished he had not asked. Then he said: “Say: O Allah, send prayers upon Muhammad and upon the family of Muhammad, as You sent prayers upon Ibrahim. And bless Muhammad and the family of Muhammad as You blessed the family of Ibrahim among all the worlds. Indeed, You are Praiseworthy, Glorious. And the greeting of peace is as you have been taught.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (67)، مسلم (405)."},{"num":2170,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى قَالَ: لَقِيَنِي كَعْبُ بْنُ عُجْرَةَ، فَقَالَ: أَلَا أُهْدِي لَكَ هَدِيَّةً ؟ إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَيْنَا، فَقُلْنَا: يَا رَسُولَ اللَّهِ، قَدْ عَلِمْنَا كَيْفَ نُسَلِّمُ عَلَيْكَ، فَكَيْفَ نُصَلِّي عَلَيْكَ ؟ قَالَ: فَقُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6357)، ومسلم في الصلاة (406) كلاهما من طريق شعبة، حدَّثنا الحكم، قال: سمعت عبدالرحمن بن أبي ليلى، فذكره.","grade":"متفق عليه","chapter_ar":"باب الصلاة على النبي في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (6357), Muslim (406)","chapter_en":"Sending prayers upon the Prophet ﷺ in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["‘Abd al-Rahman ibn Abi Layla said: Ka‘b ibn ‘Ujrah met me and said: “Shall I give you a gift? The Prophet ﷺ came out to us and we said: ‘O Messenger of Allah, we have learned how to greet you with peace—so how should we send prayers upon you?’ He said: ‘Say: O Allah, send prayers upon Muhammad and the family of Muhammad as You sent prayers upon the family of Ibrahim. Indeed, You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad as You blessed the family of Ibrahim. Indeed, You are Praiseworthy, Glorious.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10855,13103],"tks":"متفق عليه: رواه البخاري (6357)، مسلم (406)."},{"num":2171,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قُلْنَا يَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا السَّلَامُ عَلَيْكَ، فَكَيْفَ نُصَلِّي ؟ قَالَ: قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ."],"takhrij":"صحيح: رواه البخاري في الدعوات (6358) عن إبراهيم بن حمزة، حدثنا ابن أبي حازم والدراوردي، عن يزيد (هو ابن الهاد)، عن عبدالله بن حَبَّاب، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على النبي في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (6358)","chapter_en":"Sending prayers upon the Prophet ﷺ in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: We said: “O Messenger of Allah ﷺ, this is the greeting of peace upon you—so how should we send prayers?” He said: “Say: O Allah, send prayers upon Muhammad, Your servant and Messenger, as You sent prayers upon Ibrahim. And bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6358)."},{"num":2172,"demo":false,"sanad":"","matn":["عَنْ فَضَالَةَ بْنِ عُبَيْدٍ صَاحِبَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: سَمِعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يَدْعُو فِي صَلَاتِهِ لَمْ يُمَجِّدِ اللَّهَ تَعَالَى، وَلَمْ يُصَلِّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَجِلَ هَذَا ثُمَّ دَعَاهُ، فَقَالَ لَهُ أَوْ لِغَيْرِهِ: إِذَا صَلَّى أَحَدُكُمْ فَلْيَبْدَأْ بِتَحْمِيدِ رَبِّهِ جَلَّ وَعَزَّ وَالثَّنَاءِ عَلَيْهِ، ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ يَدْعُو بَعْدُ بِمَا شَاءَ."],"takhrij":"صحيح: رواه أبو داود (1481)، والترمذي (3477) كلاهما من طريق عبدالله بن يزيد المُقرئ، ثنا حيوة بن شريح، أخبرني أبو هاني حُميد بن هانئ، أن أبا علي عمرو بن مالك الجَنْبيَّ أخبره، أنه سمع فَضالة بن عبيد فذكر مثله .","grade":"صحيح","chapter_ar":"باب الصلاة على النبي في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (1481) — wording his; al-Tirmidhi (3477) — he said: “Hasan Sahih”","chapter_en":"Sending prayers upon the Prophet ﷺ in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Fudalah ibn ‘Ubayd said: The Messenger of Allah ﷺ heard a man supplicating in his prayer without praising Allah and without sending prayers upon the Prophet. The Messenger of Allah ﷺ said: “This one has rushed.” Then he called him and said to him—or to someone else: “When one of you prays, let him begin by glorifying his Lord, Mighty and Majestic, and praising Him, then send prayers upon the Prophet, then supplicate afterward with whatever he wishes.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10867,10893],"tks":"صحيح: رواه أبو داود (1481) واللفظ له، والترمذي (3477)، وقال: حسن صحيح."},{"num":2173,"demo":false,"sanad":"","matn":["عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ قَالَ: قُلْنَا يَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:كَيْفَ الصَّلَاةُ عَلَيْكَ ؟ قَالَ: قُولُوا اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ."],"takhrij":"حسن: رواه النسائي (1290) عن إسحاق بن إبراهيم قال: أخبرنا محمد ابن بشر، قال: حدّثنا مجمع بن يحيى، عن عثمان بن موهب، عن موسى بن طلحة، عن أبيه فذكره .","grade":"حسن","chapter_ar":"باب الصلاة على النبي في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (1290)","chapter_en":"Sending prayers upon the Prophet ﷺ in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Talhah ibn ‘Ubaydillah said: We said: “O Messenger of Allah ﷺ, how should we send prayers upon you?” He said: “Say: O Allah, send prayers upon Muhammad and the family of Muhammad as You sent prayers upon Ibrahim and the family of Ibrahim. Indeed, You are Praiseworthy, Glorious. And bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim. Indeed, You are Praiseworthy, Glorious.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1290)."},{"num":2174,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّهُمْ سَأَلُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَيْفَ نُصَلِّي عَلَيْكَ؟ قَالَ: قُولُوا اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَبَارِكْ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ وَبَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، وَالسَّلامُ كَمَا قَدْ عُلِّمْتُمْ."],"takhrij":"صحيح: رواه البزار-كشف الأستار (565) حدثنا أحمد بن عبدة، أنبأ سُلَيم بن أخضر، ثنا داود بن قيس، عن نُعيم، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الصلاة على النبي في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bazzar in Kashf al-Astar (565)","chapter_en":"Sending prayers upon the Prophet ﷺ in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah said: They asked the Messenger of Allah ﷺ: “How should we send prayers upon you?” He said: “Say: O Allah, send prayers upon Muhammad and bless Muhammad and the family of Muhammad, as You sent prayers and blessings upon Ibrahim and the family of Ibrahim among all the worlds. Indeed, You are Praiseworthy, Glorious. And the greeting of peace is as you have been taught.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10861],"tks":"صحيح: رواه البزار في كشف الأستار (565)."},{"num":2175,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَارِجَةَ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِنَفْسِي فَقُلْتُ: كَيْفَ الصَّلَاةُ عَلَيْكَ ؟ قَالَ :صَلُّوا وَاجْتَهِدُوا، ثُمَّ قُولُوا اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ."],"takhrij":"صحيح: رواه الإمام أحمد (1714) حدثنا علي بن بَحْر، حدثنا عيسى بن يونس، حدثنا عثمان بن حكيم، حدثنا خالد بن سلمة، أن عبدالحميد بن عبدالرحمن دعا موسى بن طلحة حين عرَّس على ابنه فقال: يا أبا عيسى كيف بلغك في الصلاة على النبي صلى الله عليه وسلم؟ فقال موسى: سألتُ زيد بن خارجة عن الصلاة على النبي صلى الله عليه وسلم فقــال زيد: أنا سألت رسول الله صلى الله عليه وسلم نفسي: كيف الصلاة عليك؟ فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الصلاة على النبي في التشهد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (1714)","chapter_en":"Sending prayers upon the Prophet ﷺ in the tashahhud","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Zayd ibn Kharijah said: I asked the Messenger of Allah ﷺ: “How should we send prayers upon you?” He said: “Send prayers and be diligent, then say: O Allah, bless Muhammad and the family of Muhammad as You blessed the family of Ibrahim. Indeed, You are Praiseworthy, Glorious.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (1714)."},{"num":2176,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَتْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو فِي الصَّلَاةِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَفِتْنَةِ الْمَمَاتِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ، فَقَالَ لَهُ قَائِلٌ: مَا أَكْثَرَ مَا تَسْتَعِيذُ مِنَ الْمَغْرَمِ، فَقَالَ: إِنَّ الرَّجُلَ إِذَا غَرِمَ حَدَّثَ فَكَذَبَ وَوَعَدَ فَأَخْلَفَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (832)، ومسلم في المساجد (589) كلاهما من طريق أبي اليمان، أخبرنا شُعيب، عن الزهري، قال: أخبرني عروة بن الزبير، أن عائشة أخبرته فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (832), Muslim (589)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, reported that the Prophet ﷺ used to supplicate in prayer: “O Allah, I seek refuge in You from the punishment of the grave; I seek refuge in You from the trial of the false messiah; I seek refuge in You from the trials of life and the trials of death. O Allah, I seek refuge in You from sin and from debt.” Someone said: “How often you seek refuge from debt, O Messenger of Allah!” He said: “When a man is burdened by debt, he speaks and lies, and he promises and breaks his promise.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11024],"tks":"متفق عليه: رواه البخاري (832)، مسلم (589)."},{"num":2177,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أَنَّ يَهُودِيَّةً دَخَلَتْ عَلَيْهَا فَذَكَرَتْ عَذَابَ الْقَبْرِ، فَقَالَتْ لَهَا: أَعَاذَكِ اللَّهُ مِنْ عَذَابِ الْقَبْرِ، فَسَأَلَتْ عَائِشَةُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ عَذَابِ الْقَبْرِ، فَقَالَ: نَعَمْ، عَذَابُ الْقَبْرِ، قَالَتْ عَائِشَةُ: فَمَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدُ صَلَّى صَلَاةً إِلَّا تَعَوَّذَ مِنْ عَذَابِ الْقَبْرِ.","زَادَ غُنْدَرٌ عَذَابُ الْقَبْرِ حَقٌّ ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1372)، ومسلم في المساجد (126،586) كلاهما من طريق أشعث، عن أبيه، عن مسروق، عن عائشة فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (1372), Muslim (586/126)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah said: A Jewish woman entered upon her and mentioned the punishment of the grave. The woman said to her: “May Allah protect you from the punishment of the grave.” Then ‘A’ishah asked the Messenger of Allah ﷺ about the punishment of the grave, and he said: “Yes, the punishment of the grave is true.” ‘A’ishah said: I never saw the Messenger of Allah ﷺ pray after that except that he sought refuge from the punishment of the grave."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1372)، مسلم (586/126)."},{"num":2178,"demo":false,"sanad":"","matn":["عَنْ فَرْوَةَ بْنِ نَوْفَلٍ قَالَ: قُلْتُ لِعَائِشَةَ حَدِّثِينِي بِشَيْءٍ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْعُو بِهِ فِي صَلَاتِهِ، فَقَالَتْ: نَعَمْ، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ."],"takhrij":"صحيح: رواه مسلم في كتاب الذكر والدعاء (2716) عن يحيى بن يحيى وإسحاق بن إبراهيم واللفظ ليحيى قالا: أخبرنا جرير، عن منصور، عن هلال، عن فروة بن نوفل الأشجعي قال: سألت عائشة فذكر الحديث، ومسلم ساق لفظ يحيى، وليس في روايته أنه كان يدعو به في صلاته، وإنما ذكره إسحاق بن إبراهيم، وعنه رواه النسائي (1307) بالسند المذكور عند مسلم، والمتن الذي سقتُه منه. وكذا لم يرو أبو داود (1550) وابن ماجه (3839) من طريق إسحاق بن إبراهيم، فلم يذكرا أيضاً أن ذلك كان في الصلاة.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (2716)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Furwah ibn Nawfal said: I said to ‘A’ishah: “Tell me something the Messenger of Allah ﷺ used to supplicate with in his prayer.” She said: “Yes. The Messenger of Allah ﷺ used to say: ‘O Allah, I seek refuge in You from the evil of what I have done and from the evil of what I have not done.’”"]}},"tuhfa":{},"full":1,"rep":[11031],"tks":"صحيح: رواه مسلم (2716)."},{"num":2179,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَت: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي بَعْضِ صَلَاتِهِ: اللَّهُمَّ حَاسِبْنِي حِسَابًا يَسِيرًا، فَلَمَّا انْصَرَفَ قُلْتُ: يَا نَبِيَّ اللَّهِ مَا الْحِسَابُ الْيَسِيرُ ؟ قَالَ: أَنْ يَنْظُرَ فِي كِتَابِهِ، فَيَتَجَاوَزَ عَنْه، إِنَّهُ مَنْ نُوقِشَ الْحِسَابَ يَوْمَئِذٍ يَا عَائِشَةُ هَلَكَ، وَكُلُّ مَا يُصِيبُ الْمُؤْمِنَ يُكَفِّرُ اللَّهُ عَزَّ وَجَلَّ بِهِ عَنْه حَتَّى الشَّوْكَةُ تَشُوكُهُ."],"takhrij":"حسن: رواه الإمام أحمد (24215) قال: حدثنا إسماعيل، حدثنا محمد ابن إسحاق، قال: حدثني عبدالواحد بن حمزة بن عبدالله بن الزبير، عن عبَّاد ابن عبدالله بن الزبير، عن عائشة فذكرت الحديث.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (24215); Ibn Khuzaymah authenticated it (849)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah said: I heard the Prophet ﷺ say in one of his prayers: “O Allah, take me to account with an easy reckoning.” When he finished, I said: “O Prophet of Allah, what is an easy reckoning?” He said: “That his record is looked at and he is pardoned. Whoever is examined closely in the reckoning that day will be ruined, O ‘A’ishah. And whatever afflicts a believer, Allah, Mighty and Majestic, expiates it for him—even a thorn that pricks him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11032,13697,16196],"tks":"حسن: رواه أحمد (24215)، وصححه ابن خزيمة (849)."},{"num":2180,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْعُو اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ النَّارِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1377)، ومسلم في المساجد (588، 131) كلاهما من حديث هشام، عن يحيى، عن أبي سلمة، أنه سمع أبا هريرة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (1377), Muslim (588/131)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ used to supplicate: “O Allah, I seek refuge in You from the punishment of the grave, from the punishment of the Fire, from the trials of life and death, and from the trial of the false messiah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11026,11330],"tks":"متفق عليه: رواه البخاري (1377)، مسلم (588/131)."},{"num":2181,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِرَجُلٍ: مَا تَقُولُ فِي الصَّلَاةِ ؟ قَالَ: أَتَشَهَّدُ ثُمَّ أَسْأَلُ اللَّهَ الْجَنَّةَ، وَأَعُوذُ بِهِ مِنَ النَّارِ، أَمَا وَاللَّهِ مَا أُحْسِنُ دَنْدَنَتَكَ وَلَا دَنْدَنَةَ مُعَاذٍ، فَقَالَ: حَوْلَهُمَا نُدَنْدِنُ."],"takhrij":"صحيح: رواه ابن ماجه (910، 3847) عن يوسف بن موسى القطَّان، قال: حدثنا جرير (ابن عبدالحميد) عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (910, 3847); Ibn Khuzaymah authenticated it (725); Ibn Hibban (868)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said to a man: “What do you say in prayer?” He said: “I recite the tashahhud, then I ask Allah for Paradise and seek refuge with Him from the Fire. By Allah, I do not know your murmuring nor Mu‘adh’s murmuring.” He said: “Around these two we murmur in supplication.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11033],"tks":"صحيح: رواه ابن ماجه (910، 3847)، وصححه ابن خزيمة (725)، ورواه ابن حبان (868)."},{"num":2182,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهُمْ هَذَا الدُّعَاءَ كَمَا يُعَلِّمُهُمُ السُّورَةَ مِنَ الْقُرْآنِ، يَقُولُ: قُولُوا اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ."],"takhrij":"صحيح: رواه مسلم في المساجد (590) عن قتيبة بن سعيد، عن مالك ابن أنس، عن أبي الزبير، عن طاوس، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (590)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ used to teach them this supplication as he taught them a surah of the Qur’an. He would say: “Say: O Allah, we seek refuge in You from the punishment of Hell, and I seek refuge in You from the punishment of the grave, and I seek refuge in You from the trial of the false messiah, and I seek refuge in You from the trials of life and death.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (590)."},{"num":2183,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرٍ الصِّدِّيقِ أَنَّهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَلِّمْنِي دُعَاءً أَدْعُو بِهِ فِي صَلَاتِي، قَالَ: قُلْ، اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا َلاَ يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي إِنَّك أَنْتَ الْغَفُورُ الرَّحِيمُ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (834)، ومسلم في الذكر والدعاء (2705) كلاهما عن قتيبة بن سعيد، قال: حدثنا الليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عبدالله بن عمرو بن العاص، عن أبي بكر الصديق فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (834), Muslim (2705)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abu Bakr al-Siddiq said to the Messenger of Allah ﷺ: “Teach me a supplication to say in my prayer.” He said: “Say: O Allah, I have wronged myself with great wrongdoing, and none forgives sins except You. So forgive me with a forgiveness from You and have mercy on me. Indeed, You are the Forgiving, the Merciful.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11029],"tks":"متفق عليه: رواه البخاري (834)، مسلم (2705)."},{"num":2184,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ) يَقُولُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ التَّشَهُّدِ وَالتَّسْلِيمِ: اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ..الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في المسافرين (771) من طريق يوسف الماجشون، عن أبيه، عن عبدالرحمن الأعرج، عن عبيدالله بن أبي رافع، عن علي رضي الله عنه.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (771)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["‘Ali ibn Abi Talib reported that the Prophet ﷺ used to say between the tashahhud and the closing greetings: “O Allah, forgive me what I have sent ahead and what I have left behind, what I have concealed and what I have made public, what I have gone to excess in, and what You know better than I. You are the One who brings forward and the One who delays. There is no god worthy of worship except You.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (771)."},{"num":2185,"demo":false,"sanad":"","matn":["عَنْ مِحْجَنِ بْنِ الْأَدْرَعِ قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ قَدْ قَضَى صَلَاتَهُ وَهُوَ يَتَشَهَّدُ وَهُوَ يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اللَّهُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ، قَالَ: فَقَالَ قَدْ غُفِرَ لَهُ، قَدْ غُفِرَ لَهُ ثَلَاثًا."],"takhrij":"صحيح: رواه أبو داود (985)، والنسائي (1301) كلاهما من طريق عبدالوارث، حدثنا الحسين المعلم، عن عبدالله بن بريدة، عن حنظلة بن علي، أن محجن بن الأدْرع حدثه فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (985), al-Nasa’i (1301)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Mahjan ibn al-Adra‘ said: The Messenger of Allah ﷺ entered the mosque and found a man who had finished his prayer and was in the tashahhud saying: “O Allah, I ask You—O Allah, the One, the Self-Sufficient, who neither begets nor is born and there is none comparable to Him—that You forgive me my sins. Indeed, You are the Forgiving, the Merciful.” The Messenger of Allah ﷺ said: “He has been forgiven, he has been forgiven,” three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (985)، النسائي (1301)."},{"num":2186,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الْحُصَيْبٍ الأَسْلَمِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَ رَجُلًا يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ، فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ سَأَلْتَ اللَّهَ بِالِاسْمِ الَّذِي إِذَا سُئِلَ بِهِ أَعْطَى، وَإِذَا دُعِيَ بِهِ أَجَابَ."],"takhrij":"صحيح: رواه أبو داود (1493، 1494) من وجهين، من طريق يحيى، عن مالك بن مغول، ومن طريق زيد بن حُباب قال: حدثنا مالك بن مغول، وابن ماجه (3857) من طريق وكيع، عن مالك بن مغول، والترمذي (3475) من طريق زيد بن حُباب، عن زهير بن معاوية، عن مالك بن مِغول، عن عبدالله بن بريدة، عن أبيه فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (1493–1494), Ibn Majah (3857), al-Tirmidhi (3475)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Buraydah ibn al-Husayb al-Aslami reported that the Messenger of Allah ﷺ heard a man saying: “O Allah, I ask You by my bearing witness that You are Allah—there is no god worthy of worship except You—the One, the Self-Sufficient, who neither begets nor is born, and there is none comparable to Him.” The Messenger of Allah ﷺ said: “You have asked Allah by the Name which, if He is asked by it, He gives; and if He is called upon by it, He answers.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10899,10966,11035],"tks":"صحيح: رواه أبو داود (1493–1494)، ابن ماجه (3857)، الترمذي (3475)."},{"num":2187,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا وَرَجُلٌ يُصَلِّي، ثُمَّ دَعَا: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدُ، لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيعُ السَّمَوَاتِ وَالْأَرْضِ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ دَعَا اللَّهَ بِاسْمِهِ الْعَظِيمِ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ، وَإِذَا سُئِلَ بِهِ أَعْطَى."],"takhrij":"حسن: رواه أبو داود (1495)، والنسائي (1300) كلاهما من طريق خلف بن خليفة، عن حفص بن أخي أنس، عن أنس بن مالك فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (1495), al-Nasa’i (1300)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik said: I was sitting with the Messenger of Allah ﷺ while a man was praying. Then the man supplicated: “O Allah, I ask You by the fact that all praise belongs to You; there is no god worthy of worship except You, the Bestower; Originator of the heavens and the earth; O Possessor of majesty and honor; O Ever-Living, O Sustainer.” The Prophet ﷺ said: “He has supplicated to Allah by His Greatest Name—when He is called upon by it, He answers; and when He is asked by it, He gives.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1495)، النسائي (1300)."},{"num":2188,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: جَاءَتْ أُمُّ سُلَيْمٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ عَلِّمْنِي كَلِمَاتٍ أَدْعُو بِهِنَّ فِي صَلَاتِي قَالَ: سَبِّحِي اللَّهَ عَشْرًا، وَاحْمَدِيهِ عَشْرًا، وَكَبِّرِيهِ عَشْرًا، ثُمَّ سَلِيهِ حَاجَتَكِ يَقُلْ نَعَمْ نَعَمْ."],"takhrij":"حسن: رواه النسائي (1299)، والترمذي (481) كلاهما من طريق عكرمة بن عمار، عن إسحاق بن عبدالله بن أبي طلحة، عن أنس فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (1299), al-Tirmidhi (481)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Anas said: Umm Sulaym came to the Prophet ﷺ and said: “O Messenger of Allah, teach me words that I can supplicate with in my prayer.” He said: “Glorify Allah ten times, praise Him ten times, and say Allāhu akbar ten times. Then ask for your need—He will say: yes, yes.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11037],"tks":"حسن: رواه النسائي (1299)، الترمذي (481)."},{"num":2189,"demo":false,"sanad":"","matn":["عَنْ عَمَّارِ بْنِ يَاسِرٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي صَلَاتِهِ: اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَاءَ بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ."],"takhrij":"صحيح: رواه النسائي (1305) من طريق حماد بن زيد، حدثنا عطاء بن السائب بن مالك، عن أبيه قال: صلى بنا عمار بن ياسر صلاة، فأوجز فيها، فقال له بعض القوم، لقد خفَّفتَ، أو أوجزتَ الصلاة. قال: ما عَلَيَّ ذلك، فقد دعوتُ فيها دعوات سمعتُهن من رسول الله صلى الله عليه وسلم، فلما قام، تبعه رجل من القوم، هو أبي (أي أبو عطاء) غير أنه كنى عن نفسه فسأله عن الدعاء، ثم جاء فأخبر به القوم، فذكر الدعاء.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (1305)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["‘Ammar ibn Yasir said: I heard the Messenger of Allah ﷺ say in his prayer: “O Allah, by Your knowledge of the unseen and Your power over creation: keep me alive as long as You know life is better for me, and cause me to die when You know death is better for me. O Allah, I ask You for fear of You—meaning in private and in public; I ask You for a word of truth in pleasure and in anger; I ask You for moderation in poverty and in wealth; I ask You for blessings that do not end; I ask You for comfort of the eye that does not cease; I ask You for contentment after Your decree; I ask You for a coolness of life after death; I ask You for the delight of looking at Your Face and longing to meet You, without harmful hardship and without misguiding trial. O Allah, adorn us with the adornment of faith and make us guides who are rightly guided.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1305)."},{"num":2190,"demo":false,"sanad":"","matn":["عَنْ عَاصِمِ بْنِ كُلَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي وَقَدْ وَضَعَ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَقَبَضَ أَصَابِعَهُ وَبَسَطَ السَّبَّابَةَ وَهُوَ يَقُولُ: يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ."],"takhrij":"حسن: رواه الترمذي (3587) عن عقبة بن مُكْرَم، حدثنا سعيد بن سفيان الجحدري، حدثنا عبدالله بن مَعْدان، أخبرني عاصم بن كليب الجرميُّ، عن أبيه، عن جدّه قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tirmidhi (3587)","chapter_en":"Supplications said before the closing greetings","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["‘Asim ibn Kulayb narrated from his father, from his grandfather, who said: I entered upon the Prophet ﷺ while he was praying. He had placed his left hand on his left thigh and his right hand on his right thigh, curled his fingers, and extended the index finger while saying: “O Turner of hearts, keep my heart firm upon Your religion.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3587)."},{"num":2191,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: كُنْتُ أَرَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُسَلِّمُ عَنْ يَمِينِهِ، وَعَنْ يَسَارِهِ، حَتَّى أَرَى بَيَاضَ خَدِّهِ."],"takhrij":"صحيح: رواه مسلم في المساجد (582) عن إسحاق بن إبراهيم، أخبرنا أبو عامر العقدي، حدثنا عبدالله بن جعفر، عن إسماعيل بن محمد، عن عامر بن سعد، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في السلام للتحليل من الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (582)","chapter_en":"The closing greetings that end the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: I used to see the Messenger of Allah ﷺ give the closing greeting to his right and to his left until I could see the whiteness of his cheek."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (582)."},{"num":2192,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: كُنَّا إِذَا صَلَّيْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْنَا: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ، السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ، وَأَشَارَ بِيَدِهِ إِلَى الْجَانِبَيْنِ، فَقَال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَلَامَ تُومِئُونَ بِأَيْدِيكُمْ كَأَنَّهَا أَذْنَابُ خَيْلٍ شُمْسٍ، إِنَّمَا يَكْفِي أَحَدَكُمْ أَنْ يَضَعَ يَدَهُ عَلَى فَخِذِهِ، ثُمَّ يُسَلِّمُ عَلَى أَخِيهِ مَنْ عَلَى يَمِينِهِ وَشِمَالِهِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (431) من طريق مسعر، حدثني عبيدالله ابن القِبْطية،، عن جابر بن سمرة فذكر مثله، وفي رواية قال: صلَّيت مع رسول الله صلى الله عليه وسلم فكنا إذا سلَّمنا قلنا بأيدينا: السلام عليكم. السلام عليكم. فنظر إلينا رسول الله صلى الله عليه وسلم فقال: ما شانكم؟ تُشيرون بأيديكم كأنها أذْناب خَيل شُمُس، إذا سلَّم أحدكم فليلتفِتْ إلى صاحبه، ولا يُومِئ بيده رواه أيضاً مسلم من وجه آخر عن فرات القزَّاز، عن عبيدالله، عن جابر بن سمرة به.","grade":"صحيح","chapter_ar":"باب ما جاء في السلام للتحليل من الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (431)","chapter_en":"The closing greetings that end the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn Samurah said: When we prayed with the Messenger of Allah ﷺ, we would say: “Peace be upon you and Allah’s mercy,” “Peace be upon you and Allah’s mercy,” and we would gesture with our hands to both sides. The Messenger of Allah ﷺ said: “Why do you gesture with your hands as if they were the tails of restless horses? It is sufficient for one of you to place his hand on his thigh, then give the greeting of peace to his brother on his right and on his left.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (431)."},{"num":2193,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَعْمَرٍ أَنَّ أَمِيرًا كَانَ بِمَكَّةَ يُسَلِّمُ تَسْلِيمَتَيْنِ، فَقَالَ عَبْدُ اللَّهِ: أَنَّى عَلِقَهَا، قَالَ الْحَكَمُ فِي حَدِيثِهِ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَانَ يَفْعَلُهُ."],"takhrij":"صحيح: رواه مسلم في المساجد (581) عن زهير بن حرب، حدثنا يحيى ابن سعيد، عن شعبة، عن الحكم ومنصور، عن مجاهد، عن أبي معمر فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في السلام للتحليل من الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (581)","chapter_en":"The closing greetings that end the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Abu Ma‘mar said: A leader in Makkah used to give two greetings of peace (to end the prayer). ‘Abdullah said: “From where did he pick that up?” Al-Hakam said in his narration: The Messenger of Allah ﷺ used to do that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (581)."},{"num":2194,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُسَلِّمُ عَنْ يَمِينِهِ، وَعَنْ شِمَالِهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ، السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ، السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ."],"takhrij":"حسن: رواه أبو داود (996)، والترمذي (295)، والنسائي (1084،1320)، وابن ماجه (914) كلهم من طرق عن أبي إسحاق، عن أبي الأحوص، عن عبدالله بن مسعود فذكر مثله، واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب ما جاء في السلام للتحليل من الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (996) — wording his; al-Tirmidhi (295); al-Nasa’i (1084, 1320)","chapter_en":"The closing greetings that end the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud reported that the Messenger of Allah ﷺ used to give the greeting of peace to his right and to his left until the whiteness of his cheek could be seen: “Peace be upon you and Allah’s mercy; peace be upon you and Allah’s mercy.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (996)، واللفظ له، الترمذي (295)، النسائي (1084، 1320)."},{"num":2195,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَانَ يُسَلِّمُ عَنْ يَمِينِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، وَعَنْ شِمَالِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ."],"takhrij":"حسن: رواه أبو داود (997) قال: حدثنا عبدةُ بن عبدالله، حدثنا يحيى ابن آدم، حدثنا موسى بن قيس الحضرمي، عن سلمة بن كُهيل، عن علقمة ابن وائل، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في السلام للتحليل من الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (997)","chapter_en":"The closing greetings that end the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Wa’il ibn Hujr said: I prayed with the Prophet ﷺ. He would give the greeting to his right: “Peace be upon you and Allah’s mercy and blessings,” and to his left: “Peace be upon you and Allah’s mercy.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (997)."},{"num":2196,"demo":false,"sanad":"","matn":["عَنْ وَاسِعِ بْنِ حَبَّانَ أَنَّهُ سَأَلَ عَبْدَ اللَّهِ بْنَ عُمَرَ عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: اللَّهُ أَكْبَرُ كُلَّمَا وَضَعَ، اللَّهُ أَكْبَرُ كُلَّمَا رَفَعَ، ثُمَّ يَقُولُ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ عَنْ يَمِينِهِ، السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ عَنْ يَسَارِهِ."],"takhrij":"صحيح: رواه النسائي (1320) قال: أخبرنا الحسن بن محمد الزعفراي، عن حجّاج قال: ابن جريج أنبأنا عمرو بن يحيى، عن محمد بن يحيى بن حبَّان، عن عمِّه واسع بن حَبَّان أنه سأل ابن عمر فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في السلام للتحليل من الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (1320); Ibn Khuzaymah authenticated it (576)","chapter_en":"The closing greetings that end the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Wasi‘ ibn Habban said that he asked ‘Abdullah ibn ‘Umar about the prayer of the Messenger of Allah ﷺ. He said: “Allāhu akbar” whenever he went down, and “Allāhu akbar” whenever he rose. Then he would say: “Peace be upon you and Allah’s mercy” to his right, and “Peace be upon you and Allah’s mercy” to his left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1320)، وصححه ابن خزيمة (576)."},{"num":2197,"demo":false,"sanad":"","matn":["عَنِ الْعَبَّاسِ بْنِ سَهْلٍ السَّاعِدِيِّ أَنَّهُ كَانَ فِي مَجْلِسٍ فِيهِ أَبُوهُ، وَأَبُو هُرَيْرَةَ، وَأَبُو أُسَيْدٍ، وَأَبُو حُمَيْدٍ، وَأَنَّهُمْ تَذَاكَرُوا صَلَاةَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرُوا أَنَّهُ سَلَّمَ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ."],"takhrij":"حسن: رواه ابن حبان (1866) والطبراني في الكبير (5738) كلاهما من حديث أبي همام الوليد بن شجاع بن الوليد السكوني، قال حدثنا أبي، قال: حدثنا أبو خيثمة قال: حدثنا الحسن بن الحِرّ قال: حدثني عيسى بن عبدالله بن مالك، عن محمد بن عمرو بن عطاء أحد بني مالك، عن عباس بن سهل بن سعد الساعدي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في السلام للتحليل من الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Hibban (1866); al-Tabarani in al-Kabir (6/158)","chapter_en":"The closing greetings that end the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["‘Abbas ibn Sahl ibn Sa‘d said: He was in a gathering in which his father, Abu Hurayrah, Abu Usayd, and Abu Humayd al-Sa‘idi were present. They discussed the prayer of the Messenger of Allah ﷺ and mentioned that he would give the greeting of peace to his right and to his left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (1866)، الطبراني في المعجم الكبير (5738)."},{"num":2198,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ أَنَّهُ قَالَ لِقَوْمِهِ: أَلَا أُصَلِّي بِكُمْ صَلَاةَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ الصَّلَاةَ وَسَلَّمَ عَنْ يَمِينِهِ، وَعَنْ شِمَالِهِ، ثُمَّ قَالَ: هَكَذَا كَانَتْ صَلَاةُ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه الطحاوي في شرحه (1610) عن ابن أبي داود، قال: ثنا عياش الرقام، قال: ثنا عبدالأعلى، قال: ثنا قرة، قال: ثنا بُديل، عن شهر بن حوشب، عن عبدالرحمن بن غنم، قال: قال أبو مالك الأشعري فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في السلام للتحليل من الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tahawi in Sharh (1/269)","chapter_en":"The closing greetings that end the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Abu Malik al-Ash‘ari said to his people: “Shall I not pray with you the prayer of the Messenger of Allah ﷺ?” He then described the prayer, gave the greetings to his right and to his left, and said: “This is how the prayer of the Messenger of Allah ﷺ was.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطحاوي في شرح معاني الآثار (1610)."},{"num":2199,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا سُئِلَتْ عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ فَقَالَتْ (فَذَكَرَتِ الْحَدِيثَ): كَانَ يُصَلِّي ثَمَانِ رَكَعَاتٍ يَقْرَأُ فِيهِنَّ بِفَاتِحَةِ الْكِتَابِ، وَمَا شَاءَ مِنَ الْقُرْآنِ، وَقَالَ مَرَّةً: مَا شَاءَ اللَّهُ مِنَ الْقُرْآنِ، فَلَا يَقْعُدُ فِي شَيْءٍ مِنْهُنَّ إِلَّا فِي الثَّامِنَةِ، فَإِنَّهُ يَقْعُدُ فِيهَا، فَيَتَشَهَّدُ، ثُمَّ يَقُومُ وَلَا يُسَلِّمُ، فَيُصَلِّيَ رَكْعَةً وَاحِدَةً ثُمَّ يَجْلِسُ فَيَتَشَهَّدُ وَيَدْعُو، ثُمَّ يُسَلِّمُ تَسْلِيمَةً وَاحِدَةً: السَّلَامُ عَلَيْكُمْ، يَرْفَعُ بِهَا صَوْتَهُ حَتَّى يُوقِظَنَا."],"takhrij":"صحيح: رواه الإمام أحمد (25987) قال: حدثنا بهز بن حكيم،، وقال مرة: أخبرنا، قال: سمعت زرارة بن أوفى يقول: سئلتْ عائشة فذكر الحديث. ورواه أيضاً أبو داود (1346) من طريق ابن عدي، عن بهز بن حكيم وفيه: ويُسلم تسليمة واحدة شديدة يكاد يُوقظ أهل البيت من شدّة تسليمه.","grade":"صحيح","chapter_ar":"باب ما جاء في تسليمة واحدة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (25987). Also narrated by Abu Dawud (1346) with an added note that he would give one taslim that would almost wake the people of the house.","chapter_en":"What has been narrated about a single taslim","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["‘A’ishah was asked about the night prayer of the Messenger of Allah ﷺ. She said: He used to pray eight units, reciting in them the Opening of the Book and whatever he wished of the Qur’an. He would not sit in any of them until the eighth, where he would sit and recite the tashahhud, then stand without giving the taslim. Then he would pray one unit, then sit, recite the tashahhud and supplicate, then give a single taslim: “Peace be upon you,” raising his voice with it until he would wake us."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (25987)، ورواه أيضا أبو داود (1346) بزيادة أنه كان يسلم تسليمة تكاد توقظ أهل الدار."}]);